// Src/common/filters/http-exception.filter.ts
import {
  ResponseWrapper,
  STATUS_CODE,
  WrappedResponse,
} from '@mesx/common-lib';
import {
  ArgumentsHost,
  Catch,
  HttpException,
  HttpStatus,
} from '@nestjs/common';
import { BaseExceptionFilter } from '@nestjs/core';
import { AppLogger } from '@/common/logger/app-logger';

type WrappedErrorStatusCode =
  | STATUS_CODE.BAD_REQUEST
  | STATUS_CODE.NOT_FOUND
  | STATUS_CODE.CONFLICT
  | STATUS_CODE.INTERNAL_SERVER_ERROR;

@Catch()
export class MesGenericErrorFilter extends BaseExceptionFilter {
  private static isWrappedResponse(
    value: unknown,
  ): value is WrappedResponse<unknown> {
    return (
      typeof value === 'object' &&
      value !== null &&
      'success' in value &&
      'statusCode' in value &&
      'messages' in value
    );
  }

  private static mapHttpToWrappedStatus(
    status: number,
  ): WrappedErrorStatusCode {
    if (status === HttpStatus.BAD_REQUEST) {
      return STATUS_CODE.BAD_REQUEST;
    }
    if (status === HttpStatus.NOT_FOUND) {
      return STATUS_CODE.NOT_FOUND;
    }
    if (status === HttpStatus.CONFLICT) {
      return STATUS_CODE.CONFLICT;
    }
    return STATUS_CODE.INTERNAL_SERVER_ERROR;
  }

  private static normalizeHttpException(
    exception: HttpException,
    status: number,
  ): {
    wrapped?: WrappedResponse<unknown>;
    message: string | Array<string>;
    data?: unknown;
  } {
    const exceptionResponse = exception.getResponse();

    if (MesGenericErrorFilter.isWrappedResponse(exceptionResponse)) {
      return {
        wrapped: exceptionResponse,
        message: 'Internal server error',
      };
    }

    if (status >= HttpStatus.INTERNAL_SERVER_ERROR) {
      return { message: 'Internal server error' };
    }

    if (typeof exceptionResponse === 'string') {
      return { message: exceptionResponse };
    }

    if (typeof exceptionResponse === 'object' && exceptionResponse !== null) {
      const messageValue = (
        exceptionResponse as { message?: string | Array<string> }
      ).message;
      const message =
        Array.isArray(messageValue) || typeof messageValue === 'string'
          ? messageValue
          : exception.message;

      const details = (exceptionResponse as { error?: string }).error;
      return {
        message,
        ...(details ? { data: { error: details } } : {}),
      };
    }

    return { message: exception.message };
  }

  private readonly logger = new AppLogger(MesGenericErrorFilter.name);

  private logException(
    request: { method: string; url: string },
    exception: unknown,
    status: number,
  ): void {
    const stack = exception instanceof Error ? exception.stack : undefined;
    this.logger.error(
      `${request.method} ${request.url} failed with status ${status}: ${
        exception instanceof Error ? exception.message : String(exception)
      }`,
      stack,
    );
  }

  public catch(exception: unknown, host: ArgumentsHost): void {
    const context = host.switchToHttp();
    const response = context.getResponse();
    const request = context.getRequest();

    const status =
      exception instanceof HttpException
        ? exception.getStatus()
        : HttpStatus.INTERNAL_SERVER_ERROR;

    const normalized =
      exception instanceof HttpException
        ? MesGenericErrorFilter.normalizeHttpException(exception, status)
        : { message: 'Internal server error' as const };

    if (normalized.wrapped) {
      this.logException(request, exception, status);
      response.status(HttpStatus.OK).json(normalized.wrapped);
      return;
    }

    this.logException(request, exception, status);

    const wrappedStatus = MesGenericErrorFilter.mapHttpToWrappedStatus(status);

    const payload =
      wrappedStatus === STATUS_CODE.INTERNAL_SERVER_ERROR
        ? ResponseWrapper.error(
            STATUS_CODE.INTERNAL_SERVER_ERROR,
            'Internal server error',
          )
        : ResponseWrapper.error(
            wrappedStatus,
            normalized.message,
            normalized.data,
          );

    response.status(wrappedStatus).json(payload);
  }
}

import { Logger } from '@nestjs/common';

export class AppLogger extends Logger {
  public log(message: unknown): void {
    super.log(`${new Date().toISOString()} -- ${message}`);
  }

  public error(message: unknown, stack?: string): void {
    super.error(`${new Date().toISOString()} -- ${message}`, stack);
  }

  public warn(message: unknown): void {
    super.warn(`${new Date().toISOString()} -- ${message}`);
  }

  public debug(message: unknown): void {
    super.debug(`${new Date().toISOString()} -- ${message}`);
  }

  public verbose(message: unknown): void {
    super.verbose(`${new Date().toISOString()} -- ${message}`);
  }
}

