const isTsRuntime = __filename.endsWith('.ts');

export const mssqlConfiguration = (): MssqlEnvironmentVariableConfig => ({
  mssql: {
    authType: process.env.DB_AUTH_TYPE,
    database: process.env.DB_NAME,
    encrypt: process.env.DB_ENCRYPT_CONNECTION === 'true',
    entities: [isTsRuntime ? 'src/**/*.entity.ts' : 'dist/**/*.entity.js'], // Entity files path
    host: process.env.DB_HOST,
    managedIdentityClientId: process.env.DB_MANAGED_ID_CLIENT_ID,
    migrations: ['dist/**/migration/*{.ts,.js}'], // Migrations files path
    migrationsTableName: 'migrations_TypeORM', // Name of the migrations table
    migrationsWaitDelayMilliseconds: Number(
      process.env.DB_MIGRATION_WAIT_DELAY_MILLISECONDS,
