import { VersioningType } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';
import { AppModule } from '@/app.module';
import { MesGenericErrorFilter } from '@/common/filters/mes-generic-error.filter';
import { AppLogger } from '@/common/logger/app-logger';
import { MssqlConfigurationService } from '@/config/database/mssql/abstract.mssql.config.service';
import { UrlApiConfigService } from '@/config/url-api/url-api.service';
import { Isa9PhysicalAssetModelModule } from '@/modules/isa9-physical-asset-model/isa9-physical-asset-model.module';
import { Isa95EquipmentModelModule } from '@/modules/isa95-equipment-model/isa95-equipment-model.module';
import { MssqlDatabaseChecker } from '@/providers/database/mssql/mssql.database.checker';
/**
 *
 */
async function bootstrap(): Promise<void> {
  const app = await NestFactory.create(AppModule);
  app.useGlobalFilters(new MesGenericErrorFilter());
  const { urlApi } = app.get(UrlApiConfigService);
  const config = new DocumentBuilder()
    .setTitle('plant-hierarchy-api Swagger Documentation')
    .setDescription(
      "In this page you'll find all of the necessary informations about the microservice plant-hierarchy-api  and it's different endpoints.",
    )
    .setVersion('1.0')
    .addServer(urlApi, 'pre-production') // It will replaced by environment variable

    .build();
  app.enableVersioning({
    prefix: 'v',
    type: VersioningType.URI,
  });
  const document = SwaggerModule.createDocument(app, config);

  // Keep ISA95 endpoints in a dedicated Swagger document.
  const isa95Prefixes = [
    '/isa95-equipment-model',
    '/isa95-physical-asset-model',
  ];
  document.paths = Object.fromEntries(
    Object.entries(document.paths).filter(
      ([path]) => !isa95Prefixes.some((prefix) => path.startsWith(prefix)),
    ),
  );
  SwaggerModule.setup('api', app, document);

  const isa95SwaggerConfig = new DocumentBuilder()
    .setTitle('ISA95 Equipment Model Swagger Documentation')
    .setDescription(
      'Dedicated Swagger page for ISA95 Equipment Model endpoints.',
    )
    .setVersion('1.0')
    .addServer(urlApi, 'pre-production')
    .build();

  const isa95Document = SwaggerModule.createDocument(app, isa95SwaggerConfig, {
    include: [Isa95EquipmentModelModule],
    deepScanRoutes: true,
  });
  SwaggerModule.setup('api/isa95-equipment-model', app, isa95Document);

  const physicalAssetSwaggerConfig = new DocumentBuilder()
    .setTitle('ISA95 Physical Asset Model Swagger Documentation')
    .setDescription(
      'Dedicated Swagger page for ISA95 Physical Asset Model endpoints.',
    )
    .setVersion('1.0')
    .addServer(urlApi, 'pre-production')
    .build();

  const physicalAssetDocument = SwaggerModule.createDocument(
    app,
    physicalAssetSwaggerConfig,
    {
      include: [Isa9PhysicalAssetModelModule],
      deepScanRoutes: true,
    },
  );
  SwaggerModule.setup(
    'api/isa95-physical-asset-model',
    app,
    physicalAssetDocument,
  );

  const databaseConfig = app.get(MssqlConfigurationService);
  const { migrationsWaitDelayMilliseconds, migrationsWaitRetryLimit } =
    databaseConfig;
  const logger = new AppLogger(bootstrap.name);
  const mssqlDatabaseChecker = app.get(MssqlDatabaseChecker);

  await mssqlDatabaseChecker.waitForMigrations(
    logger,
    migrationsWaitDelayMilliseconds,
    migrationsWaitRetryLimit,
  );

  await app.listen(3000);
}
bootstrap();

