@Injectable()
export class PhysicalAssetClassCrudService {
  private static readonly defaultDescriptionLanguageCode = 'EN';

  private static normalizeLanguageCode(languageCode?: string): string {
    return (
      languageCode ??
      PhysicalAssetClassCrudService.defaultDescriptionLanguageCode
    )
      .trim()
      .toUpperCase();
  }

  private static selectPhysicalAssetClassDescription(
    descriptions: Array<PhysicalAssetClassDescription> | undefined,
    languageCode: string,
  ): { description: string | null; descriptionLanguageCode: string | null } {
    if (!descriptions || descriptions.length === 0) {
      return { description: null, descriptionLanguageCode: null };
    }

    const selected =
      descriptions.find(
        (description) => description.code?.trim() === languageCode,
      ) ??
      descriptions.find(
        (description) =>
          description.code?.trim() ===
          PhysicalAssetClassCrudService.defaultDescriptionLanguageCode,
      ) ??
      descriptions[0];

    return {
      description: selected?.description ?? null,
      descriptionLanguageCode: selected?.code?.trim() ?? null,
    };
  }

  private static selectPhysicalAssetDescription(
    descriptions: Array<PhysicalAssetDescriptionByLanguage> | undefined,
    languageCode: string,
  ): PhysicalAssetDescriptionByLanguage | undefined {
    if (!descriptions || descriptions.length === 0) {
      return undefined;
    }

    return (
      descriptions.find(
        (description) => description.code?.trim() === languageCode,
      ) ??
      descriptions.find(
        (description) =>
          description.code?.trim() ===
          PhysicalAssetClassCrudService.defaultDescriptionLanguageCode,
      ) ??
      descriptions[0]
    );
  }

  private static mapToResponseDto(
    physicalAssetClass: PhysicalAssetClass,
    language = 'EN',
  ): PhysicalAssetClassResponseDto {
    const { description, descriptionLanguageCode } =
      PhysicalAssetClassCrudService.selectPhysicalAssetClassDescription(
        physicalAssetClass.descriptions,
        language,
      );

    return {
      code: physicalAssetClass.code,
      description,
      descriptionLanguageCode,
      id: physicalAssetClass.id,
      isCustom: physicalAssetClass.isCustom,
      parentPhysicalAssetClassId: null,
      physicalAssetClassPropertiesCount: (
        physicalAssetClass as unknown as {
          physicalAssetClassPropertiesCount: number;
        }
      ).physicalAssetClassPropertiesCount,
    };
  }

  private static mapToRelationsResponseDto(
    physicalAssetClass: PhysicalAssetClass,
    language = 'EN',
  ): PhysicalAssetClassWithRelationsResponseDto {
    const baseDto = PhysicalAssetClassCrudService.mapToResponseDto(
      physicalAssetClass,
      language,
    );

    return {
      ...baseDto,
      childPhysicalAssetClasses:
        physicalAssetClass.childInheritances?.map((inh) =>
          PhysicalAssetClassCrudService.mapToResponseDto(
            inh.childPhysicalAssetClass,
            language,
          ),
        ) ?? [],
      parentPhysicalAssetClasses:
        physicalAssetClass.parentInheritances?.map((inh) =>
          PhysicalAssetClassCrudService.mapToResponseDto(
            inh.parentPhysicalAssetClass,
            language,
          ),
        ) ?? [],
      physicalAssetClassProperties:
        physicalAssetClass.physicalAssetClassProperties ?? [],
      physicalAssetIds:
        physicalAssetClass.physicalAssetClassPhysicalAssets?.map(
          (paca) => paca.physicalAssetId,
        ) ?? [],
    };
  }

  private static mapPhysicalAssetForClass(
    physicalAsset: PhysicalAsset,
    physicalAssetClassId: number,
    languageCode: string,
  ): PhysicalAsset {
    const selectedDescription =
      PhysicalAssetClassCrudService.selectPhysicalAssetDescription(
        physicalAsset.descriptions,
        languageCode,
      );

    return {
      ...physicalAsset,
      descriptions: selectedDescription ? [selectedDescription] : [],
      physicalAssetProperties: (physicalAsset.physicalAssetProperties ?? [])
        .filter(
          (property) => property.physicalAssetClassId === physicalAssetClassId,
        )
        .sort((left, right) => left.id - right.id)
        .map((property) => ({
          ...property,
          physicalAssetClass: property.physicalAssetClass
            ? {
                ...property.physicalAssetClass,
                physicalAssetClassProperties: [],
              }
            : property.physicalAssetClass,
        })),
    };
  }

  private static applyPhysicalAssetClassUpdates(
    physicalAssetClass: PhysicalAssetClass,
    payload: UpdatePhysicalAssetClassDto,
  ): PhysicalAssetClass {
    const updated = physicalAssetClass;

    if (payload.code !== undefined) {
      updated.code = payload.code;
    }

    return updated;
  }

  private static async syncParentInheritance(
    manager: EntityManager,
    childPhysicalAssetClassId: number,
    parentPhysicalAssetClassId: number | null | undefined,
  ): Promise<void> {
    if (parentPhysicalAssetClassId === undefined) {
      return;
    }

    const inheritanceRepository = manager.getRepository(
      PhysicalAssetClassInheritance,
    );
    const physicalAssetClassRepository =
      manager.getRepository(PhysicalAssetClass);

    await inheritanceRepository.delete({
      childPhysicalAssetClassId,
    });

    if (parentPhysicalAssetClassId === null) {
      return;
    }

    if (parentPhysicalAssetClassId === childPhysicalAssetClassId) {
      throw new BadRequestException(
        'A physical asset class cannot inherit from itself.',
      );
    }

    const parentExists = await physicalAssetClassRepository.exists({
      where: {
        id: parentPhysicalAssetClassId,
      },
    });

    if (!parentExists) {
      throw new BadRequestException(
        `Parent physical asset class ${parentPhysicalAssetClassId} does not exist.`,
      );
    }

    await inheritanceRepository.save(
      inheritanceRepository.create({
        childPhysicalAssetClassId,
        parentPhysicalAssetClassId,
      }),
    );
  }

  private static async upsertDescription(
    manager: EntityManager,
    physicalAssetClassId: number,
    description: string,
    languageCode?: string,
  ): Promise<void> {
    const descriptionRepository = manager.getRepository(
      PhysicalAssetClassDescription,
    );
    const code =
      PhysicalAssetClassCrudService.normalizeLanguageCode(languageCode);

    const existingDescription = await descriptionRepository.findOne({
      where: {
        code,
        physicalAssetClassId,
      },
    });

    if (existingDescription) {
      existingDescription.description = description;
      await descriptionRepository.save(existingDescription);
      return;
    }

    const physicalAssetClassDescription = descriptionRepository.create({
      code,
      description,
      physicalAssetClassId,
    });

    await descriptionRepository.save(physicalAssetClassDescription);
  }

  private readonly logger = new AppLogger(PhysicalAssetClassCrudService.name);

