    @InjectRepository(PhysicalAssetClass)
    private readonly physicalAssetClassRepository: Repository<PhysicalAssetClass>,
    @InjectRepository(PhysicalAssetClassInheritance)
    private readonly physicalAssetClassInheritanceRepository: Repository<PhysicalAssetClassInheritance>,
    @InjectRepository(PhysicalAssetClassPhysicalAsset)
