  ) {}

  public async getRestrictedPhysicalAssetDetailsFlat(
    plant: number,
    limit: number,
    offset: number,
  ): Promise<RestrictedPhysicalAssetFlatPaginatedResponse> {
    const safeLimit = Number.isNaN(limit)
      ? 50
      : Math.min(Math.max(limit, 1), 500);
    const safeOffset = Number.isNaN(offset) || offset < 0 ? 0 : offset;

    const rows = await this.physicalAssetRepository
      .createQueryBuilder('physicalAsset')
      .leftJoin(
        PhysicalAssetDescriptionByLanguage,
        'description',
        'description.physical_asset_id = physicalAsset.id',
      )
      .leftJoin(
        PhysicalAssetClassPhysicalAsset,
        'classLink',
        'classLink.physical_asset_id = physicalAsset.id AND classLink.plant = physicalAsset.plant',
      )
      .leftJoin(
        PhysicalAssetClass,
        'physicalAssetClass',
        'physicalAssetClass.id = classLink.physical_asset_class_id',
      )
      .leftJoin(
        PhysicalAssetProperty,
        'property',
        'property.physical_asset_id = physicalAsset.id AND property.plant = physicalAsset.plant AND (classLink.physical_asset_class_id IS NULL OR property.physical_asset_class_id = classLink.physical_asset_class_id)',
      )
      .where('physicalAsset.plant = :plant', { plant })
      .select([
        'physicalAsset.id AS id',
        'physicalAsset.code AS code',
        'physicalAsset.plant AS plant',
        'physicalAsset.erp_source AS erpSource',
        'physicalAsset.parent_physical_asset_id AS parentPhysicalAssetId',
        'physicalAsset.physical_asset_location AS physicalAssetLocation',
        'physicalAsset.effective_start_date AS effectiveStartDate',
        'physicalAsset.effective_end_date AS effectiveEndDate',
        'description.code AS descriptionLanguageCode',
        'description.description AS descriptionByLanguage',
        'physicalAssetClass.id AS classId',
        'physicalAssetClass.code AS classCode',
        'physicalAssetClass.is_custom AS classIsCustom',
        'property.id AS propertyId',
        'property.properties_json AS propertiesJson',
      ])
      .orderBy('physicalAsset.id', 'ASC')
      .addOrderBy('description.code', 'ASC')
      .addOrderBy('physicalAssetClass.id', 'ASC')
      .addOrderBy('property.id', 'ASC')
      .getRawMany<RestrictedPhysicalAssetFlatRow>();

    return {
      data: rows.slice(safeOffset, safeOffset + safeLimit),
      limit: safeLimit,
      offset: safeOffset,
      total: rows.length,
    };
  }

  public async findAll(): Promise<
    WrappedResponse<Array<PhysicalAssetClassResponseDto> | undefined>
  > {
    try {
      const classes = await this.physicalAssetClassRepository.find({
        relations: ['descriptions'],
        order: { id: 'ASC' },
      });
      const data = classes.map((pac) =>
        PhysicalAssetClassCrudService.mapToResponseDto(pac, 'EN'),
      );
      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical asset classes retrieved successfully',
        data,
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        'Failed to retrieve physical asset classes',
        error,
      );
    }
  }

  public async findPhysicalAssetClasses(
    pagination: PaginationDto,
    language?: string,
  ): Promise<
    WrappedResponse<
      PaginatedResponseDto<PhysicalAssetClassResponseDto> | undefined
    >
  > {
    try {
      const lang =
        PhysicalAssetClassCrudService.normalizeLanguageCode(language);

      const query = this.physicalAssetClassRepository
        .createQueryBuilder('physicalAssetClass')
        .leftJoinAndSelect(
          'physicalAssetClass.descriptions',
          'description',
          'description.code = :lang',
          { lang },
        )
        .loadRelationCountAndMap(
          'physicalAssetClass.physicalAssetClassPropertiesCount',
          'physicalAssetClass.physicalAssetClassProperties',
        )
        .orderBy('physicalAssetClass.id', 'ASC')
        .skip(pagination.offset)
        .take(pagination.limit);

      const [data, total] = await query.getManyAndCount();

      const responseData = data.map((pac) =>
        PhysicalAssetClassCrudService.mapToResponseDto(pac, lang),
      );

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical asset classes retrieved successfully',
        {
          data: responseData,
          total,
          limit: pagination.limit,
          offset: pagination.offset,
        },
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        'Failed to retrieve physical asset classes',
        error,
      );
    }
  }

  public async create(
    payload: CreatePhysicalAssetClassDto,
  ): Promise<WrappedResponse<PhysicalAssetClassResponseDto | undefined>> {
    try {
      const customCode = payload.className.trim();
      let savedPhysicalAssetClassId: number | undefined;

      await this.physicalAssetClassRepository.manager.transaction(
        async (manager) => {
          const physicalAssetClassRepository =
            manager.getRepository(PhysicalAssetClass);
          const existingPhysicalAssetClass =
            await physicalAssetClassRepository.findOne({
              where: { code: customCode },
            });

          if (existingPhysicalAssetClass) {
            throw new ConflictException(
              `Physical asset class with code ${customCode} already exists`,
            );
          }

          const physicalAssetClass = physicalAssetClassRepository.create({
            code: customCode,
            isCustom: true,
          });

          const savedPhysicalAssetClass =
            await physicalAssetClassRepository.save(physicalAssetClass);

          savedPhysicalAssetClassId = savedPhysicalAssetClass.id;

          await PhysicalAssetClassCrudService.upsertDescription(
            manager,
            savedPhysicalAssetClass.id,
            payload.description,
            payload.descriptionLanguageCode,
          );

          await PhysicalAssetClassCrudService.syncParentInheritance(
            manager,
            savedPhysicalAssetClass.id,
            payload.parentPhysicalAssetClassId,
          );
        },
      );

      const reloaded = await this.physicalAssetClassRepository.findOne({
        where: { id: savedPhysicalAssetClassId },
        relations: ['descriptions'],
      });

      if (!reloaded) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical asset class with id ${savedPhysicalAssetClassId} not found`,
        );
      }

      const response = PhysicalAssetClassCrudService.mapToResponseDto(
        reloaded,
        payload.descriptionLanguageCode ?? 'EN',
      );

      return ResponseWrapper.success(
        STATUS_CODE.CREATED,
        'Physical asset class created successfully',
        response,
      );
    } catch (error) {
      if (error instanceof ConflictException) {
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          `Physical asset class already exists`,
        );
      }
      if (error instanceof BadRequestException) {
        return ResponseWrapper.error(STATUS_CODE.BAD_REQUEST, error.message);
      }
      return throwWrappedInternalError(
        this.logger,
        'Failed to create physical asset class',
        error,
      );
    }
  }

