  public async findPhysicalAssets(
    id: number,
    language?: string,
  ): Promise<WrappedResponse<Array<PhysicalAsset> | undefined>> {
    try {
      const physicalAssetClass =
        await this.physicalAssetClassRepository.findOne({
          where: { id },
        });

      if (!physicalAssetClass) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical asset class with id ${id} not found`,
        );
      }

      const selectedLanguage =
        PhysicalAssetClassCrudService.normalizeLanguageCode(language);

      const links = await this.physicalAssetClassPhysicalAssetRepository.find({
        where: { physicalAssetClassId: id },
        order: { physicalAssetId: 'ASC' },
        relations: [
          'physicalAsset',
          'physicalAsset.descriptions',
          'physicalAsset.physicalAssetProperties',
          'physicalAsset.physicalAssetProperties.physicalAssetClass',
        ],
      });

      const seenPhysicalAssetIds = new Set<number>();

      const physicalAssets = links
        .map((link) => link.physicalAsset)
        .filter(Boolean)
        .filter((physicalAsset) => {
          if (seenPhysicalAssetIds.has(physicalAsset.id)) {
            return false;
          }

          seenPhysicalAssetIds.add(physicalAsset.id);
          return true;
        })
        .map((physicalAsset) =>
          PhysicalAssetClassCrudService.mapPhysicalAssetForClass(
            physicalAsset,
            id,
            selectedLanguage,
          ),
        );

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical assets retrieved successfully',
        physicalAssets,
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to retrieve physical assets for class id ${id}`,
        error,
      );
    }
  }

  public async update(
    id: number,
    payload: UpdatePhysicalAssetClassDto,
  ): Promise<WrappedResponse<PhysicalAssetClassResponseDto | undefined>> {
    try {
      await this.physicalAssetClassRepository.manager.transaction(
        async (manager) => {
          const physicalAssetClassRepository =
            manager.getRepository(PhysicalAssetClass);

          const physicalAssetClass = await physicalAssetClassRepository.findOne(
            {
              where: { id },
            },
          );

          if (!physicalAssetClass) {
            throw new NotFoundException(
              `Physical asset class with id ${id} not found`,
            );
          }

          const appliedUpdates =
            PhysicalAssetClassCrudService.applyPhysicalAssetClassUpdates(
              physicalAssetClass,
              payload,
            );

          await physicalAssetClassRepository.save(appliedUpdates);

          if (payload.description !== undefined) {
            await PhysicalAssetClassCrudService.upsertDescription(
              manager,
              id,
              payload.description,
              payload.descriptionLanguageCode,
            );
          }

          await PhysicalAssetClassCrudService.syncParentInheritance(
            manager,
            id,
            payload.parentPhysicalAssetClassId,
          );
        },
      );

      const reloaded = await this.physicalAssetClassRepository.findOne({
        where: { id },
        relations: ['descriptions'],
      });

      if (!reloaded) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical asset class with id ${id} not found`,
        );
      }

      const response = PhysicalAssetClassCrudService.mapToResponseDto(
        reloaded,
        payload.descriptionLanguageCode ?? 'EN',
      );

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical asset class updated successfully',
        response,
      );
    } catch (error) {
      if (error instanceof NotFoundException) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical asset class with id ${id} not found`,
        );
      }
      if (error instanceof BadRequestException) {
        return ResponseWrapper.error(STATUS_CODE.BAD_REQUEST, error.message);
      }
      return throwWrappedInternalError(
        this.logger,
        `Failed to update physical asset class ${id}`,
        error,
      );
    }
  }

  private async assertPhysicalAssetClassNotInUse(id: number): Promise<void> {
    const isAssigned =
      await this.physicalAssetClassPhysicalAssetRepository.exists({
        where: { physicalAssetClassId: id },
      });

    if (isAssigned) {
      throw new BadRequestException(
        'Cannot delete physical asset class because it is assigned to physical assets.',
      );
    }
  }

  public async remove(id: number): Promise<WrappedResponse<undefined>> {
    try {
      const physicalAssetClass =
        await this.physicalAssetClassRepository.findOne({
          where: { id },
        });

      if (!physicalAssetClass) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical asset class with id ${id} not found`,
        );
      }

      await this.assertPhysicalAssetClassNotInUse(id);

      await this.physicalAssetClassRepository.manager.transaction(
        async (manager) => {
          const classLinkRepository = manager.getRepository(
            PhysicalAssetClassPhysicalAsset,
          );
          const propertyRepository = manager.getRepository(
            PhysicalAssetClassProperty,
          );
          const descriptionRepository = manager.getRepository(
            PhysicalAssetClassPropertyDescription,
          );
          const ownedProperties = await propertyRepository.find({
            where: { physicalAssetClassId: id },
            select: ['id'],
          });
          const ownedPropertyIds = ownedProperties.map(
            (property) => property.id,
          );

          await deletePhysicalAssetClassPropertiesById(
            propertyRepository,
            descriptionRepository,
            ownedPropertyIds,
          );

          await manager.getRepository(PhysicalAssetProperty).delete({
            physicalAssetClassId: id,
          });
          await classLinkRepository.delete({ physicalAssetClassId: id });
          await manager
            .getRepository(PhysicalAssetClassInheritance)
            .createQueryBuilder()
            .delete()
            .from(PhysicalAssetClassInheritance)
            .where('parent_physical_class_id = :id', { id })
            .orWhere('child_physical_class_id = :id', { id })
            .execute();
          await manager.getRepository(PhysicalAssetClassDescription).delete({
            physicalAssetClassId: id,
          });
          await manager.getRepository(PhysicalAssetClass).delete({ id });
        },
      );

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical asset class deleted successfully',
      );
    } catch (error) {
      if (error instanceof NotFoundException) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical asset class with id ${id} not found`,
        );
      }
      if (error instanceof BadRequestException) {
        return ResponseWrapper.error(STATUS_CODE.BAD_REQUEST, error.message);
      }
      return throwWrappedInternalError(
        this.logger,
        `Failed to cascade delete physical asset class ${id}`,
        error,
      );
    }
  }

  public async replaceProperties(
    id: number,
    payload: ReplacePhysicalAssetClassPropertiesDto,
  ): Promise<
    WrappedResponse<PhysicalAssetClassWithRelationsResponseDto | undefined>
  > {
    try {
      const physicalAssetClass =
        await this.physicalAssetClassRepository.findOne({
          where: { id },
        });

      if (!physicalAssetClass) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical asset class with id ${id} not found`,
        );
      }

      await this.physicalAssetClassRepository.manager.transaction(
        async (manager) => {
          await replacePhysicalAssetClassPropertiesByCloning(
            manager,
            id,
            payload.propertyIds,
          );
        },
      );

      const reloaded = await this.physicalAssetClassRepository.findOne({
        where: { id },
        relations: [
          'descriptions',
          'parentInheritances',
          'parentInheritances.parentPhysicalAssetClass',
          'childInheritances',
          'childInheritances.childPhysicalAssetClass',
          'physicalAssetClassProperties',
          'physicalAssetClassProperties.descriptions',
          'physicalAssetClassProperties.propertyDataType',
          'physicalAssetClassProperties.children',
          'physicalAssetClassPhysicalAssets',
          'physicalAssetClassPhysicalAssets.physicalAsset',
          'physicalAssetClassPhysicalAssets.physicalAsset.descriptions',
        ],
      });

      if (!reloaded) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical asset class with id ${id} not found`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical asset class properties replaced successfully',
        PhysicalAssetClassCrudService.mapToRelationsResponseDto(reloaded),
      );
    } catch (error) {
      if (error instanceof BadRequestException) {
        return ResponseWrapper.error(STATUS_CODE.BAD_REQUEST, error.message);
      }
      return throwWrappedInternalError(
        this.logger,
        `Failed to replace properties for physical asset class ${id}`,
        error,
      );
    }
  }
