import { BadRequestException } from '@nestjs/common';
import { EntityManager, In, Repository } from 'typeorm';
import { PhysicalAssetClassProperty } from '@/modules/isa9-physical-asset-model/physical-asset-class/physical-asset-class-property/physical-asset-class-property.entity';
import { PhysicalAssetClassPropertyDescription } from '@/modules/isa9-physical-asset-model/physical-asset-class/physical-asset-class-property-description/physical-asset-class-property-description.entity';

const nullableValue = JSON.parse('null') as null;

/**
 * Ensures every requested property exists in the loaded source map.
 * @param requestedPropertyIds Property IDs requested by the caller.
 * @param sourcePropertiesById Loaded source properties keyed by ID.
 */
function assertPropertiesExist(
  requestedPropertyIds: Array<number>,
  sourcePropertiesById: Map<number, PhysicalAssetClassProperty>,
): void {
  const missingPropertyIds = requestedPropertyIds.filter(
    (propertyId) => !sourcePropertiesById.has(propertyId),
  );

  if (missingPropertyIds.length > 0) {
    throw new BadRequestException(
      `Physical asset class properties not found: ${missingPropertyIds.join(', ')}`,
    );
  }
}

/**
 * Resolves the cloned or existing parent property ID for a cloned property.
 * @param sourceProperty Source property being cloned or reused.
 * @param physicalAssetClassId Target physical asset class ID.
 * @param resolvedPropertiesBySourceId Resolved target properties by source ID.
 * @param parentPropertiesById Loaded parent property metadata by ID.
 * @param currentPropertiesByCode Current target properties keyed by code.
 * @returns Parent property ID to store.
 */
function resolveParentPropertyId(
  sourceProperty: PhysicalAssetClassProperty,
  physicalAssetClassId: number,
  resolvedPropertiesBySourceId: Map<number, PhysicalAssetClassProperty>,
  parentPropertiesById: Map<number, PhysicalAssetClassProperty>,
  currentPropertiesByCode: Map<string, PhysicalAssetClassProperty>,
): number | null {
  const parentPropertyId = sourceProperty.parentPhysicalAssetClassPropertyId;
  if (parentPropertyId === nullableValue) return nullableValue;

  const clonedParent = resolvedPropertiesBySourceId.get(parentPropertyId);
  if (clonedParent) return clonedParent.id;

  const parentProperty = parentPropertiesById.get(parentPropertyId);
  if (!parentProperty) return parentPropertyId;

  if (parentProperty.physicalAssetClassId === physicalAssetClassId) {
    return parentPropertyId;
  }

  const existingParent = currentPropertiesByCode.get(parentProperty.code);
  return existingParent?.id ?? parentPropertyId;
}

/**
 * Builds cloned properties whose parent IDs need updating.
 * @param clonedSourceProperties Source properties that were cloned.
 * @param physicalAssetClassId Target physical asset class ID.
 * @param resolvedPropertiesBySourceId Resolved target properties by source ID.
 * @param parentPropertiesById Loaded parent property metadata by ID.
 * @param currentPropertiesByCode Current target properties keyed by code.
 * @returns Cloned properties that need to be saved again.
 */
function buildPropertiesNeedingParentUpdate(
  clonedSourceProperties: Array<PhysicalAssetClassProperty>,
  physicalAssetClassId: number,
  resolvedPropertiesBySourceId: Map<number, PhysicalAssetClassProperty>,
  parentPropertiesById: Map<number, PhysicalAssetClassProperty>,
  currentPropertiesByCode: Map<string, PhysicalAssetClassProperty>,
): Array<PhysicalAssetClassProperty> {
  return clonedSourceProperties.flatMap((sourceProperty) => {
    const clonedProperty = resolvedPropertiesBySourceId.get(sourceProperty.id);
    if (!clonedProperty) return [];

    const resolvedParentId = resolveParentPropertyId(
      sourceProperty,
      physicalAssetClassId,
      resolvedPropertiesBySourceId,
      parentPropertiesById,
      currentPropertiesByCode,
    );

    if (
      clonedProperty.parentPhysicalAssetClassPropertyId === resolvedParentId
    ) {
      return [];
    }

    clonedProperty.parentPhysicalAssetClassPropertyId = resolvedParentId;
    return [clonedProperty];
  });
}

/**
 * Clones a class property and its descriptions for a target class.
 * @param manager Active transaction manager.
 * @param physicalAssetClassId Target physical asset class ID.
 * @param sourceProperty Source property to clone.
 * @returns Saved cloned property.
 */
async function clonePropertyForClass(
  manager: EntityManager,
  physicalAssetClassId: number,
  sourceProperty: PhysicalAssetClassProperty,
): Promise<PhysicalAssetClassProperty> {
  const propertyRepository = manager.getRepository(PhysicalAssetClassProperty);
  const descriptionRepository = manager.getRepository(
    PhysicalAssetClassPropertyDescription,
  );

  const clonedProperty = propertyRepository.create({
    code: sourceProperty.code,
    isCustom: sourceProperty.isCustom,
    length: sourceProperty.length,
    parentPhysicalAssetClassPropertyId:
      sourceProperty.parentPhysicalAssetClassPropertyId,
    physicalAssetClassId,
    propertyDataTypeId: sourceProperty.propertyDataTypeId,
    propertySemanticsJson: sourceProperty.propertySemanticsJson,
    scale: sourceProperty.scale,
  });
  const savedClonedProperty = await propertyRepository.save(clonedProperty);

  const descriptions = await descriptionRepository.find({
    where: { physicalAssetClassPropertyId: sourceProperty.id },
  });

  if (descriptions.length > 0) {
    await descriptionRepository.save(
      descriptions.map((description) =>
        descriptionRepository.create({
          code: description.code,
          description: description.description,
          physicalAssetClassPropertyId: savedClonedProperty.id,
        }),
      ),
    );
  }

  return savedClonedProperty;
}

/**
 * Deletes class properties and their dependent descriptions.
 * @param propertyRepository Class property repository.
 * @param descriptionRepository Class property description repository.
 * @param propertyIds Property IDs to delete.
 */
export async function deletePhysicalAssetClassPropertiesById(
  propertyRepository: Repository<PhysicalAssetClassProperty>,
  descriptionRepository: Repository<PhysicalAssetClassPropertyDescription>,
  propertyIds: Array<number>,
): Promise<void> {
  if (propertyIds.length === 0) return;

  await propertyRepository.update(
    { parentPhysicalAssetClassPropertyId: In(propertyIds) },
    { parentPhysicalAssetClassPropertyId: nullableValue as unknown as number },
  );
  await descriptionRepository.delete({
    physicalAssetClassPropertyId: In(propertyIds),
  });
  await propertyRepository.delete({ id: In(propertyIds) });
}

/**
 * Gets parent property IDs referenced by source properties.
 * @param sourceProperties Source properties to scan.
 * @returns Parent property IDs to load.
 */
function getParentIdsToLoad(
  sourceProperties: Array<PhysicalAssetClassProperty>,
): Array<number> {
  return [
    ...new Set(
      sourceProperties
        .map((property) => property.parentPhysicalAssetClassPropertyId)
        .filter((parentId): parentId is number => parentId !== nullableValue),
    ),
  ];
}

/**
 * Normalizes requested replacement property IDs.
 * @param nextPropertyIds Incoming property IDs.
 * @returns Positive integer property IDs without duplicates.
 */
function normalizePropertyIds(nextPropertyIds: Array<number>): Array<number> {
  return [
    ...new Set(
      nextPropertyIds.filter(
        (propertyId) => Number.isInteger(propertyId) && Number(propertyId) > 0,
      ),
    ),
  ];
}

/**
 * Plans which properties can be reused and which must be cloned.
 * @param sourceProperties Ordered source properties.
 * @param currentPropertiesByCode Current target properties keyed by code.
 * @param physicalAssetClassId Target physical asset class ID.
 * @returns Replacement plan details.
 */
function planPropertyReplacement(
  sourceProperties: Array<PhysicalAssetClassProperty>,
  currentPropertiesByCode: Map<string, PhysicalAssetClassProperty>,
  physicalAssetClassId: number,
): {
  aliasedCloneSourceIds: Map<number, number>;
  cloneRequests: Array<PhysicalAssetClassProperty>;
  resolvedPropertiesBySourceId: Map<number, PhysicalAssetClassProperty>;
} {
  const resolvedPropertiesBySourceId = new Map<
    number,
    PhysicalAssetClassProperty
  >();
  const cloneRequests: Array<PhysicalAssetClassProperty> = [];
  const aliasedCloneSourceIds = new Map<number, number>();
  const plannedCloneSourceIdsByCode = new Map<string, number>();

  for (const sourceProperty of sourceProperties) {
    if (sourceProperty.physicalAssetClassId === physicalAssetClassId) {
      resolvedPropertiesBySourceId.set(sourceProperty.id, sourceProperty);
      currentPropertiesByCode.set(sourceProperty.code, sourceProperty);
    } else {
      const existingProperty = currentPropertiesByCode.get(sourceProperty.code);
      if (existingProperty) {
        resolvedPropertiesBySourceId.set(sourceProperty.id, existingProperty);
      } else {
        const plannedCloneSourceId = plannedCloneSourceIdsByCode.get(
          sourceProperty.code,
        );
        if (plannedCloneSourceId === undefined) {
          plannedCloneSourceIdsByCode.set(
            sourceProperty.code,
            sourceProperty.id,
          );
          cloneRequests.push(sourceProperty);
        } else {
          aliasedCloneSourceIds.set(sourceProperty.id, plannedCloneSourceId);
        }
      }
    }
  }

  return {
    aliasedCloneSourceIds,
    cloneRequests,
    resolvedPropertiesBySourceId,
  };
}

/**
 * Replaces a class property set by reusing or cloning source properties.
 * @param manager Active transaction manager.
 * @param physicalAssetClassId Target physical asset class ID.
 * @param nextPropertyIds Desired source property IDs.
 */
export async function replacePhysicalAssetClassPropertiesByCloning(
  manager: EntityManager,
  physicalAssetClassId: number,
  nextPropertyIds: Array<number>,
): Promise<void> {
  const normalizedPropertyIds = normalizePropertyIds(nextPropertyIds);
  const propertyRepository = manager.getRepository(PhysicalAssetClassProperty);
  const descriptionRepository = manager.getRepository(
    PhysicalAssetClassPropertyDescription,
  );
  const currentClassProperties = await propertyRepository.find({
    where: { physicalAssetClassId },
    relations: ['descriptions'],
    order: { id: 'ASC' },
  });
  const currentPropertiesByCode = new Map(
    currentClassProperties.map((property) => [property.code, property]),
  );

  if (normalizedPropertyIds.length === 0) {
    const currentPropertyIds = currentClassProperties.map(
      (property) => property.id,
    );

    await deletePhysicalAssetClassPropertiesById(
      propertyRepository,
      descriptionRepository,
      currentPropertyIds,
    );
    return;
  }

  const sourceProperties = await propertyRepository.find({
    where: { id: In(normalizedPropertyIds) },
    relations: ['descriptions'],
    order: { id: 'ASC' },
  });
  const sourcePropertiesById = new Map(
    sourceProperties.map((property) => [property.id, property]),
  );
  assertPropertiesExist(normalizedPropertyIds, sourcePropertiesById);
  const orderedSourceProperties = normalizedPropertyIds.map(
    (propertyId) =>
      sourcePropertiesById.get(propertyId) as PhysicalAssetClassProperty,
  );
  const { aliasedCloneSourceIds, cloneRequests, resolvedPropertiesBySourceId } =
    planPropertyReplacement(
      orderedSourceProperties,
      currentPropertiesByCode,
      physicalAssetClassId,
    );
  const clonedProperties = await Promise.all(
    cloneRequests.map(async (sourceProperty) => ({
      clonedProperty: await clonePropertyForClass(
        manager,
        physicalAssetClassId,
        sourceProperty,
      ),
      sourcePropertyId: sourceProperty.id,
    })),
  );

  for (const { clonedProperty, sourcePropertyId } of clonedProperties) {
    currentPropertiesByCode.set(clonedProperty.code, clonedProperty);
    resolvedPropertiesBySourceId.set(sourcePropertyId, clonedProperty);
  }

  for (const [
    sourcePropertyId,
    aliasedSourcePropertyId,
  ] of aliasedCloneSourceIds) {
    const aliasedClonedProperty = resolvedPropertiesBySourceId.get(
      aliasedSourcePropertyId,
    );

    if (aliasedClonedProperty) {
      resolvedPropertiesBySourceId.set(sourcePropertyId, aliasedClonedProperty);
    }
  }

  const parentIdsToLoad = getParentIdsToLoad(orderedSourceProperties);
  const parentProperties =
    parentIdsToLoad.length === 0
      ? []
      : await propertyRepository.find({
          where: { id: In(parentIdsToLoad) },
          select: [
            'id',
            'code',
            'physicalAssetClassId',
            'parentPhysicalAssetClassPropertyId',
          ],
        });
  const parentPropertiesById = new Map(
    parentProperties.map((property) => [property.id, property]),
  );
  const propertiesNeedingParentUpdate = buildPropertiesNeedingParentUpdate(
    cloneRequests,
    physicalAssetClassId,
    resolvedPropertiesBySourceId,
    parentPropertiesById,
    currentPropertiesByCode,
  );

  if (propertiesNeedingParentUpdate.length > 0) {
    await propertyRepository.save(propertiesNeedingParentUpdate);
  }

  const desiredPropertyIds = new Set(
    [...resolvedPropertiesBySourceId.values()].map((property) => property.id),
  );
  const propertyIdsToDelete = currentClassProperties
    .map((property) => property.id)
    .filter((propertyId) => !desiredPropertyIds.has(propertyId));

  await deletePhysicalAssetClassPropertiesById(
    propertyRepository,
    descriptionRepository,
    propertyIdsToDelete,
  );
}

import {
  ResponseWrapper,
  STATUS_CODE,
  WrappedResponse,
} from '@mesx/common-lib';
import { BadRequestException, Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AppLogger } from '@/common/logger/app-logger';
import { CreatePhysicalAssetClassPropertyDto } from '@/modules/isa9-physical-asset-model/dtos/create-physical-asset-class-property.dto';
import { PhysicalAssetClassPropertyResponseDto } from '@/modules/isa9-physical-asset-model/dtos/physical-asset-class-property-response.dto';
import { PhysicalAssetClassPropertySemanticsTransformerDto } from '@/modules/isa9-physical-asset-model/dtos/physical-asset-class-property-semantics-transformer.dto';
import { UpdatePhysicalAssetClassPropertyDto } from '@/modules/isa9-physical-asset-model/dtos/update-physical-asset-class-property.dto';
import { PhysicalAssetClassProperty } from '@/modules/isa9-physical-asset-model/physical-asset-class/physical-asset-class-property/physical-asset-class-property.entity';
import { PhysicalAssetClassPropertyDescription } from '@/modules/isa9-physical-asset-model/physical-asset-class/physical-asset-class-property-description/physical-asset-class-property-description.entity';
import { PhysicalAssetClassPhysicalAsset } from '@/modules/isa9-physical-asset-model/shared/physical-asset-class-physical-asset/physical-asset-class-physical-asset.entity';

interface LocalizedDescription {
  code: string;
  description: string;
}

type PropertyDataTypeKind = 'boolean' | 'date' | 'list' | 'number' | 'string';

@Injectable()
export class PhysicalAssetClassPropertyCrudService {
  private static extractPropertyDescription(
    property: PhysicalAssetClassProperty,
    languageCode = 'EN',
  ): string | null {
    const descriptions =
      (property.descriptions as Array<LocalizedDescription> | undefined) ?? [];
    const lang = languageCode.toUpperCase();
    const requestedDescription = descriptions.find(
      (description) => description.code === lang,
    )?.description;
    const fallbackDescription = descriptions[0]?.description;

    return requestedDescription ?? fallbackDescription ?? null;
  }

  private static normalizeProperty(
    property: PhysicalAssetClassProperty,
    languageCode = 'EN',
  ): PhysicalAssetClassProperty {
    return {
      ...property,
      description:
        PhysicalAssetClassPropertyCrudService.extractPropertyDescription(
          property,
          languageCode,
        ),
      propertySemanticsJson:
        PhysicalAssetClassPropertySemanticsTransformerDto.toApi(
          property.propertySemanticsJson,
        ),
      propertyDataType: property.propertyDataType
        ? {
            id: property.propertyDataType.id,
            code: property.propertyDataType.code,
          }
        : undefined,
    } as unknown as PhysicalAssetClassProperty;
  }

  private static getPropertyDataTypeKind(
    propertyDataTypeId?: number,
    propertyDataTypeCode?: string,
  ): PropertyDataTypeKind {
    if (propertyDataTypeId === 1) {
      return 'boolean';
    }

    if (propertyDataTypeId === 2) {
      return 'date';
    }

    if (propertyDataTypeId === 3) {
      return 'list';
    }

    if (propertyDataTypeId === 4) {
      return 'number';
    }

    if (propertyDataTypeId === 5) {
      return 'string';
    }

    if (!propertyDataTypeCode) {
      return 'string';
    }

    const normalized = propertyDataTypeCode.trim().toUpperCase();
    if (normalized.includes('BOOL')) {
      return 'boolean';
    }

    if (normalized.includes('DATE') || normalized.includes('TIME')) {
      return 'date';
    }

    if (normalized.includes('LIST') || normalized.includes('ENUM')) {
      return 'list';
    }

    if (
      normalized.includes('NUMBER') ||
      normalized.includes('NUMERIC') ||
      normalized.includes('INT') ||
      normalized.includes('DEC') ||
      normalized.includes('FLOAT') ||
      normalized.includes('DOUBLE')
    ) {
      return 'number';
    }

    return 'string';
  }

  private static normalizeToNumber(value: string): number | undefined {
    const normalized = value.trim();
    const numeric = Number(normalized);
    if (!Number.isFinite(numeric)) {
      return undefined;
    }

    const numericPattern = /^[+-]?(?:\d+|\d*\.\d+)(?:[Ee][+-]?\d+)?$/;
    return numericPattern.test(normalized) ? numeric : undefined;
  }

  private static validateSemanticsDefaultValue(
    semantics: Record<string, unknown> | undefined,
    propertyDataTypeId?: number,
    propertyDataTypeCode?: string,
    length?: number | null,
  ): Record<string, unknown> | undefined {
    const apiSemantics =
      PhysicalAssetClassPropertySemanticsTransformerDto.toApi(semantics);

    if (!apiSemantics || !('defaultValue' in apiSemantics)) {
      return apiSemantics;
    }

    const { defaultValue } = apiSemantics;
    const dataTypeKind =
      PhysicalAssetClassPropertyCrudService.getPropertyDataTypeKind(
        propertyDataTypeId,
        propertyDataTypeCode,
      );
    const cardinality =
      apiSemantics.cardinality === 'array' ? 'array' : 'single';
    const allowedValues = Array.isArray(apiSemantics.allowedValues)
      ? (apiSemantics.allowedValues as Array<unknown>).map(String)
      : [];

    switch (dataTypeKind) {
      case 'boolean': {
        PhysicalAssetClassPropertyCrudService.validateBooleanDefaultValue(
          defaultValue,
        );
        return apiSemantics;
      }
      case 'date': {
        PhysicalAssetClassPropertyCrudService.validateDateDefaultValue(
          defaultValue,
        );
        return apiSemantics;
      }
      case 'number': {
        const normalizedDefaultValue =
          PhysicalAssetClassPropertyCrudService.validateNumberDefaultValue(
            defaultValue,
          );
        PhysicalAssetClassPropertyCrudService.validateDefaultValueLength(
          normalizedDefaultValue,
          dataTypeKind,
          length,
        );
        return { ...apiSemantics, defaultValue: normalizedDefaultValue };
      }
      case 'list': {
        const normalizedDefaultValue =
          PhysicalAssetClassPropertyCrudService.validateListDefaultValue(
            defaultValue,
            cardinality,
            allowedValues,
          );
        return { ...apiSemantics, defaultValue: normalizedDefaultValue };
      }
      default: {
        PhysicalAssetClassPropertyCrudService.validateScalarDefaultValue(
          defaultValue,
        );
        PhysicalAssetClassPropertyCrudService.validateDefaultValueLength(
          defaultValue,
          dataTypeKind,
          length,
        );
        return apiSemantics;
      }
    }
  }

  private static getLengthComparableValue(value: unknown): string | undefined {
    if (
      typeof value === 'string' ||
      typeof value === 'number' ||
      typeof value === 'boolean'
    ) {
      return String(value);
    }

    return undefined;
  }

  private static validateDefaultValueLength(
    defaultValue: unknown,
    dataTypeKind: PropertyDataTypeKind,
    length?: number | null,
  ): void {
    if (
      length === undefined ||
      length === null ||
      length <= 0 ||
      (dataTypeKind !== 'number' && dataTypeKind !== 'string')
    ) {
      return;
    }

    const comparableValue =
      PhysicalAssetClassPropertyCrudService.getLengthComparableValue(
        defaultValue,
      );

    if (comparableValue !== undefined && comparableValue.length > length) {
      throw new BadRequestException(
        `Property default value must not exceed ${length} characters.`,
      );
    }
  }

  private static validateBooleanDefaultValue(defaultValue: unknown): void {
    if (typeof defaultValue === 'boolean') return;
    if (
      typeof defaultValue === 'number' &&
      (defaultValue === 0 || defaultValue === 1)
    )
      return;
    if (typeof defaultValue === 'string') {
      const lowered = defaultValue.trim().toLowerCase();
      if (['true', 'false', '1', '0'].includes(lowered)) return;
    }

    throw new BadRequestException('Property default value must be a boolean.');
  }

  private static validateDateDefaultValue(defaultValue: unknown): void {
    if (typeof defaultValue !== 'string') {
      throw new BadRequestException(
        'Property default value must be a valid date string.',
      );
    }

    const parsed = new Date(defaultValue);
    if (!Number.isNaN(parsed.valueOf())) {
      return;
    }

    throw new BadRequestException(
      'Property default value must be a valid date string.',
    );
  }

  private static validateNumberDefaultValue(defaultValue: unknown): number {
    if (typeof defaultValue === 'number' && Number.isFinite(defaultValue)) {
      return defaultValue;
    }

    if (typeof defaultValue === 'string' && defaultValue.trim().length > 0) {
      const parsed =
        PhysicalAssetClassPropertyCrudService.normalizeToNumber(defaultValue);
      if (parsed !== undefined) {
        return parsed;
      }
    }

    throw new BadRequestException('Property default value must be numeric.');
  }

  private static validateListDefaultValue(
    defaultValue: unknown,
    cardinality: 'single' | 'array',
    allowedValues: Array<string>,
  ): unknown {
    if (cardinality === 'array') {
      let defaultValues: Array<unknown> | undefined;
      if (Array.isArray(defaultValue)) {
        defaultValues = defaultValue;
      } else if (typeof defaultValue === 'string') {
        defaultValues = defaultValue
          .split(',')
          .map((value) => value.trim())
          .filter((value) => value.length > 0);
      }

      if (defaultValues === undefined) {
        throw new BadRequestException(
          'Property default value must be an array for list cardinality.',
        );
      }

      if (allowedValues.length > 0) {
        const invalid = defaultValues.filter(
          (v) => typeof v !== 'string' || !allowedValues.includes(v),
        );
        if (invalid.length > 0) {
          throw new BadRequestException(
            'Property default values must be from the allowed list.',
          );
        }
      }

      return defaultValues;
    }

    if (
      typeof defaultValue === 'string' ||
      typeof defaultValue === 'number' ||
      typeof defaultValue === 'boolean'
    ) {
      const stringValue = String(defaultValue);
      if (allowedValues.length > 0 && !allowedValues.includes(stringValue)) {
        throw new BadRequestException(
          'Property default value must be one of the allowed list items.',
        );
      }

      return stringValue;
    }

    throw new BadRequestException('Invalid default value for list property.');
  }

  private static validateScalarDefaultValue(defaultValue: unknown): void {
    if (
      typeof defaultValue === 'string' ||
      typeof defaultValue === 'number' ||
      typeof defaultValue === 'boolean'
    ) {
      return;
    }

    throw new BadRequestException('Invalid property default value.');
  }

  private static stringifySemanticValue(value: unknown): string | null {
    if (value === undefined || value === null) {
      return null;
    }

    if (Array.isArray(value)) {
      const renderedValue = value.map(String).join(',');
      return renderedValue.length > 0 ? renderedValue : null;
    }

    if (
      typeof value === 'string' ||
      typeof value === 'number' ||
      typeof value === 'boolean'
    ) {
      return String(value);
    }

    return null;
  }

  private static extractBadRequestMessage(error: BadRequestException): string {
    const response = error.getResponse();

    if (typeof response === 'string') {
      return response;
    }

    const { message } = response as { message?: string | Array<string> };
    if (Array.isArray(message)) {
      return message.join(', ');
    }

    return typeof message === 'string' ? message : error.message;
  }

  private static mapToResponseDto(
    property: PhysicalAssetClassProperty,
    languageCode = 'EN',
  ): PhysicalAssetClassPropertyResponseDto {
    const selectedDescription =
      PhysicalAssetClassPropertyCrudService.extractPropertyDescription(
        property,
        languageCode,
      );
    const semantics =
      PhysicalAssetClassPropertySemanticsTransformerDto.toApi(
        property.propertySemanticsJson,
      ) ?? {};

    return {
      allowedValues:
        PhysicalAssetClassPropertyCrudService.stringifySemanticValue(
          semantics.allowedValues,
        ),
      cardinality: PhysicalAssetClassPropertyCrudService.stringifySemanticValue(
        semantics.cardinality,
      ),
      classPropertyType:
        PhysicalAssetClassPropertyCrudService.stringifySemanticValue(
          semantics.classPropertyType,
        ),
      code: property.code,
      defaultValue:
        PhysicalAssetClassPropertyCrudService.stringifySemanticValue(
          semantics.defaultValue,
        ),
      description: selectedDescription ?? null,
      descriptionLanguageCode: languageCode.toUpperCase(),
      id: property.id,
      isCustom: property.isCustom,
      length: property.length,
      parentPhysicalAssetClassPropertyId:
        property.parentPhysicalAssetClassPropertyId,
      physicalAssetClassId: property.physicalAssetClassId,
      propertyDataTypeCode: property.propertyDataType?.code ?? null,
      propertyDataTypeId: property.propertyDataTypeId,
      propertySemanticsJson: semantics,
      scale: property.scale,
      semanticsJson: semantics,
    } as unknown as PhysicalAssetClassPropertyResponseDto;
  }

  private readonly logger = new AppLogger(
    PhysicalAssetClassPropertyCrudService.name,
  );

  public constructor(
    @InjectRepository(PhysicalAssetClassProperty)
    private readonly physicalAssetClassPropertyRepository: Repository<PhysicalAssetClassProperty>,
    @InjectRepository(PhysicalAssetClassPropertyDescription)
    private readonly physicalAssetClassPropertyDescriptionRepository: Repository<PhysicalAssetClassPropertyDescription>,
    @InjectRepository(PhysicalAssetClassPhysicalAsset)
    private readonly physicalAssetClassPhysicalAssetRepository: Repository<PhysicalAssetClassPhysicalAsset>,
  ) {}

  private async upsertDescription(
    physicalAssetClassPropertyId: number,
    description: string,
    languageCode = 'EN',
  ): Promise<void> {
    const code = languageCode.toUpperCase();
    const existing =
      await this.physicalAssetClassPropertyDescriptionRepository.findOne({
        where: {
          code,
          physicalAssetClassPropertyId,
        },
      });

    if (existing) {
      existing.description = description;
      await this.physicalAssetClassPropertyDescriptionRepository.save(existing);
      return;
    }

    const nextDescription =
      this.physicalAssetClassPropertyDescriptionRepository.create({
        code,
        description,
        physicalAssetClassPropertyId,
      });
    await this.physicalAssetClassPropertyDescriptionRepository.save(
      nextDescription,
    );
  }

  private async findOneEntity(
    id: number,
  ): Promise<PhysicalAssetClassProperty | undefined> {
    const physicalAssetClassProperty =
      await this.physicalAssetClassPropertyRepository.findOne({
        where: { id },
      });

    if (!physicalAssetClassProperty) {
      this.logger.warn(`Physical asset class property with id ${id} not found`);
      return undefined;
    }

    return physicalAssetClassProperty;
  }

  public async create(
    payload: CreatePhysicalAssetClassPropertyDto,
  ): Promise<
    WrappedResponse<PhysicalAssetClassPropertyResponseDto | undefined>
  > {
    try {
      const existingPhysicalAssetClassProperty =
        await this.physicalAssetClassPropertyRepository.findOne({
          where: {
            code: payload.code,
            physicalAssetClassId: payload.physicalAssetClassId,
          },
        });

      if (existingPhysicalAssetClassProperty) {
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          `Physical asset class property with code ${payload.code} already exists`,
        );
      }

      // Validate default value (if present) against declared data type
      const propertySemanticsJson =
        PhysicalAssetClassPropertyCrudService.validateSemanticsDefaultValue(
          payload.propertySemanticsJson as Record<string, unknown> | undefined,
          payload.propertyDataTypeId,
          undefined,
          payload.length,
        );

      const physicalAssetClassProperty =
        this.physicalAssetClassPropertyRepository.create({
          ...payload,
          code: payload.code,
          isCustom: true,
          propertySemanticsJson:
            PhysicalAssetClassPropertySemanticsTransformerDto.toDatabase(
              propertySemanticsJson,
            ),
        });

      const createdProperty =
        await this.physicalAssetClassPropertyRepository.save(
          physicalAssetClassProperty,
        );

      if (payload.description?.trim()) {
        await this.upsertDescription(
          createdProperty.id,
          payload.description.trim(),
          payload.descriptionCode ?? 'EN',
        );
      }

      const result = await this.findOneResponseDto(createdProperty.id);
      if (!result) {
        return ResponseWrapper.error(
          STATUS_CODE.INTERNAL_SERVER_ERROR,
          'Failed to retrieve created property',
        );
      }
      return ResponseWrapper.success(
        STATUS_CODE.CREATED,
        'Physical asset class property created successfully',
        result,
      );
    } catch (error) {
      if (error instanceof BadRequestException) {
        return ResponseWrapper.error(
          STATUS_CODE.BAD_REQUEST,
          PhysicalAssetClassPropertyCrudService.extractBadRequestMessage(error),
        );
      }

      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET CLASS PROPERTY CREATE FAILED',
      );
    }
  }

