  public async update(
    id: number,
    payload: UpdatePhysicalAssetClassPropertyDto,
  ): Promise<
    WrappedResponse<PhysicalAssetClassPropertyResponseDto | undefined>
  > {
    try {
      const physicalAssetClassProperty = await this.findOneEntity(id);

      if (!physicalAssetClassProperty) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical asset class property with id ${id} not found`,
        );
      }

      if (payload.code !== undefined) {
        physicalAssetClassProperty.code = payload.code;
      }

      if (payload.propertySemanticsJson !== undefined) {
        // If defaultValue present in incoming semantics, validate it against the effective data type
        const effectiveDataTypeId =
          payload.propertyDataTypeId ??
          physicalAssetClassProperty.propertyDataTypeId;
        const effectiveLength =
          payload.length ?? physicalAssetClassProperty.length;
        const propertySemanticsJson =
          PhysicalAssetClassPropertyCrudService.validateSemanticsDefaultValue(
            payload.propertySemanticsJson as
              | Record<string, unknown>
              | undefined,
            effectiveDataTypeId,
            undefined,
            effectiveLength,
          );

        physicalAssetClassProperty.propertySemanticsJson =
          PhysicalAssetClassPropertySemanticsTransformerDto.toDatabase(
            propertySemanticsJson,
          ) ?? payload.propertySemanticsJson;
      }

      if (payload.description?.trim()) {
        await this.upsertDescription(
          physicalAssetClassProperty.id,
          payload.description.trim(),
          payload.descriptionCode ?? 'EN',
        );
      }

      if (payload.propertyDataTypeId !== undefined) {
        // If changing the data type and an existing default exists, validate it
        if (physicalAssetClassProperty.propertySemanticsJson) {
          const propertySemanticsJson =
            PhysicalAssetClassPropertyCrudService.validateSemanticsDefaultValue(
              physicalAssetClassProperty.propertySemanticsJson as
                | Record<string, unknown>
                | undefined,
              payload.propertyDataTypeId,
              undefined,
              payload.length ?? physicalAssetClassProperty.length,
            );
          physicalAssetClassProperty.propertySemanticsJson =
            PhysicalAssetClassPropertySemanticsTransformerDto.toDatabase(
              propertySemanticsJson,
            ) ?? physicalAssetClassProperty.propertySemanticsJson;
        }

        physicalAssetClassProperty.propertyDataTypeId =
          payload.propertyDataTypeId;
      }

      if (payload.physicalAssetClassId !== undefined) {
        physicalAssetClassProperty.physicalAssetClassId =
          payload.physicalAssetClassId;
      }

      if (payload.parentPhysicalAssetClassPropertyId !== undefined) {
        physicalAssetClassProperty.parentPhysicalAssetClassPropertyId =
          payload.parentPhysicalAssetClassPropertyId;
      }

      if (payload.length !== undefined) {
        const propertySemanticsJson =
          PhysicalAssetClassPropertyCrudService.validateSemanticsDefaultValue(
            physicalAssetClassProperty.propertySemanticsJson as
              | Record<string, unknown>
              | undefined,
            physicalAssetClassProperty.propertyDataTypeId,
            undefined,
            payload.length,
          );
        physicalAssetClassProperty.propertySemanticsJson =
          PhysicalAssetClassPropertySemanticsTransformerDto.toDatabase(
            propertySemanticsJson,
          ) ?? physicalAssetClassProperty.propertySemanticsJson;
        physicalAssetClassProperty.length = payload.length;
      }

      if (payload.scale !== undefined) {
        physicalAssetClassProperty.scale = payload.scale;
      }

      await this.physicalAssetClassPropertyRepository.save(
        physicalAssetClassProperty,
      );

      const result = await this.findOneResponseDto(id);
      if (!result) {
        return ResponseWrapper.error(
          STATUS_CODE.INTERNAL_SERVER_ERROR,
          'Failed to retrieve updated property',
        );
      }
      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical asset class property updated successfully',
        result,
      );
    } catch (error) {
      if (error instanceof BadRequestException) {
        return ResponseWrapper.error(
          STATUS_CODE.BAD_REQUEST,
          PhysicalAssetClassPropertyCrudService.extractBadRequestMessage(error),
        );
      }

      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET CLASS PROPERTY UPDATE FAILED',
      );
    }
  }

  public async remove(id: number): Promise<WrappedResponse<undefined>> {
    try {
      const physicalAssetClassProperty = await this.findOneEntity(id);

      if (!physicalAssetClassProperty) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical asset class property with id ${id} not found`,
        );
      }

      const linkedPhysicalAssetsCount =
        await this.physicalAssetClassPhysicalAssetRepository.count({
          where: {
            physicalAssetClassId:
              physicalAssetClassProperty.physicalAssetClassId,
          },
        });

      if (linkedPhysicalAssetsCount > 0) {
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          'Cannot delete this physical asset class property because its class is linked to one or more physical assets.',
        );
      }

      await this.physicalAssetClassPropertyRepository.manager.transaction(
        async (manager) => {
          await manager
            .getRepository(PhysicalAssetClassPropertyDescription)
            .delete({
              physicalAssetClassPropertyId: physicalAssetClassProperty.id,
            });

          await manager.getRepository(PhysicalAssetClassProperty).update(
            {
              parentPhysicalAssetClassPropertyId: physicalAssetClassProperty.id,
            },
            {
              parentPhysicalAssetClassPropertyId: null as unknown as number,
            },
          );

          return manager
            .getRepository(PhysicalAssetClassProperty)
            .delete({ id: physicalAssetClassProperty.id });
        },
      );

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical asset class property deleted successfully',
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET CLASS PROPERTY DELETE FAILED',
      );
    }
  }

  private async findOneResponseDto(
    id: number,
  ): Promise<PhysicalAssetClassPropertyResponseDto | undefined> {
    const property = await this.physicalAssetClassPropertyRepository.findOne({
      relations: {
        descriptions: true,
        propertyDataType: true,
      },
      where: { id },
    });

    if (!property) {
      return undefined;
    }

    return PhysicalAssetClassPropertyCrudService.mapToResponseDto(property);
  }
}

