import { BadRequestException } from '@nestjs/common';
import { PhysicalAssetClassPropertySemanticsTransformerDto } from '@/modules/isa9-physical-asset-model/dtos/physical-asset-class-property-semantics-transformer.dto';
import { PhysicalAssetResponseDto } from '@/modules/isa9-physical-asset-model/dtos/physical-asset-response.dto';
import { PhysicalAssetWithRelationsResponseDto } from '@/modules/isa9-physical-asset-model/dtos/physical-asset-with-relations-response.dto';
