import { normalizePhysicalAssetPropertyKey } from '@/modules/isa9-physical-asset-model/shared/physical-asset-json-path.util';

type ClassPropertyDataTypeKind =
  | 'boolean'
  | 'date'
  | 'list'
  | 'number'
  | 'string';

const nullableValue = JSON.parse('null') as null;

/**
 * Builds a lookup map for class properties by code and label.
 * @param classProperties Class property definitions to index.
 * @returns Class properties keyed by normalized property labels.
 */
function createPropertyCodeIndex(
  classProperties: Array<PhysicalAssetClassProperty>,
): Map<string, PhysicalAssetClassProperty> {
  const index = new Map<string, PhysicalAssetClassProperty>();

  for (const classProperty of classProperties) {
    index.set(
      normalizePhysicalAssetPropertyKey(classProperty.code),
      classProperty,
    );

    const label = classProperty.propertySemanticsJson?.label;
    if (typeof label === 'string' && label.trim().length > 0) {
      index.set(normalizePhysicalAssetPropertyKey(label), classProperty);
    }
  }

  return index;
}

/**
 * Resolves the validation category for a property data type.
 * @param propertyDataTypeId Numeric property data type identifier.
 * @param propertyDataTypeCode Text property data type code.
 * @returns Normalized validation category.
 */
function getPropertyDataTypeKind(
  propertyDataTypeId?: number,
  propertyDataTypeCode?: string,
): ClassPropertyDataTypeKind {
  if (propertyDataTypeId === 1) return 'boolean';
  if (propertyDataTypeId === 2) return 'date';
  if (propertyDataTypeId === 3) return 'list';
  if (propertyDataTypeId === 4) return 'number';
  if (propertyDataTypeId === 5) return 'string';
  if (!propertyDataTypeCode) return 'string';

  const normalized = propertyDataTypeCode.trim().toUpperCase();
  if (normalized.includes('BOOL')) return 'boolean';
  if (normalized.includes('DATE') || normalized.includes('TIME')) return 'date';
  if (normalized.includes('LIST') || normalized.includes('ENUM')) return 'list';

  if (
    normalized.includes('NUMBER') ||
    normalized.includes('NUMERIC') ||
    normalized.includes('INT') ||
    normalized.includes('DEC') ||
    normalized.includes('FLOAT') ||
    normalized.includes('DOUBLE')
  ) {
    return 'number';
  }

  return 'string';
}

/**
 * Normalizes an input value as a boolean.
 * @param value Candidate property value.
 * @returns Boolean representation.
 */
function normalizeBooleanClassPropertyValue(value: unknown): boolean {
  if (typeof value === 'boolean') return value;

  if (typeof value === 'string') {
    const normalized = value.trim().toLowerCase();
    if (normalized === 'true' || normalized === '1') return true;
    if (normalized === 'false' || normalized === '0') return false;
  }

  if (typeof value === 'number') {
    if (value === 1) return true;
    if (value === 0) return false;
  }

  throw new BadRequestException('Expected a boolean value.');
}

/**
 * Normalizes an input value as an ISO date string.
 * @param value Candidate property value.
 * @returns ISO date string.
 */
function normalizeDateClassPropertyValue(value: unknown): string {
  if (value instanceof Date && !Number.isNaN(value.valueOf())) {
    return value.toISOString();
  }

  if (typeof value === 'string') {
    const parsed = new Date(value);
    if (!Number.isNaN(parsed.valueOf())) return parsed.toISOString();
  }

  throw new BadRequestException('Expected a valid date string.');
}

/**
 * Normalizes a value against list semantics.
 * @param value Candidate property value.
 * @param cardinality Expected scalar or array cardinality.
 * @param allowedValues Optional list of accepted values.
 * @returns Normalized list value.
 */
function normalizeListClassPropertyValue(
  value: unknown,
  cardinality: 'single' | 'array',
  allowedValues: Array<string> | undefined,
): unknown {
  if (cardinality === 'array') {
    let values: Array<unknown> | undefined;
    if (Array.isArray(value)) {
      values = value;
    } else if (typeof value === 'string') {
      values = value
        .split(',')
        .map((item) => item.trim())
        .filter((item) => item.length > 0);
    }

    if (values === undefined) {
      throw new BadRequestException('Expected an array of values.');
    }

    if (allowedValues) {
      const invalidValues = values.filter(
        (item) => typeof item !== 'string' || !allowedValues.includes(item),
      );
      if (invalidValues.length > 0) {
        throw new BadRequestException(
          'Expected values to match allowed list items.',
        );
      }
    }

    return values;
  }

  if (
    typeof value === 'string' ||
    typeof value === 'number' ||
    typeof value === 'boolean'
  ) {
    const stringValue = String(value);
    if (allowedValues && !allowedValues.includes(stringValue)) {
      throw new BadRequestException('Expected a value from the allowed list.');
    }
    return stringValue;
  }

  throw new BadRequestException('Expected a list value.');
}

/**
 * Parses a finite number from text.
 * @param value Candidate numeric text.
 * @returns Parsed number when valid.
 */
function normalizeToNumber(value: string): number | undefined {
  const normalized = value.trim();
  const numeric = Number(normalized);
  if (!Number.isFinite(numeric)) return undefined;

  const numericPattern = /^[+-]?(?:\d+|\d*\.\d+)(?:[Ee][+-]?\d+)?$/;
  return numericPattern.test(normalized) ? numeric : undefined;
}

/**
 * Normalizes an input value as a number.
 * @param value Candidate property value.
 * @returns Numeric representation.
 */
function normalizeNumberClassPropertyValue(value: unknown): number {
  if (typeof value === 'number' && Number.isFinite(value)) return value;

  if (typeof value === 'string') {
    const parsed = normalizeToNumber(value);
    if (parsed !== undefined) return parsed;
  }

  throw new BadRequestException('Expected a numeric value.');
}

/**
 * Normalizes an input value as a string.
 * @param value Candidate property value.
 * @returns String representation.
 */
function normalizeStringClassPropertyValue(value: unknown): string {
  if (typeof value === 'string') return value;

  throw new BadRequestException('Expected a string value.');
}

/**
 * Returns a text representation used by the string/number length constraint.
 * @param value Normalized property value.
 * @returns Comparable text value when the property is scalar.
 */
function getLengthComparableValue(value: unknown): string | undefined {
  if (
    typeof value === 'string' ||
    typeof value === 'number' ||
    typeof value === 'boolean'
  ) {
    return String(value);
  }

  return undefined;
}

/**
 * Validates configured length for string and number properties.
 * @param value Normalized property value.
 * @param dataTypeKind Resolved data type kind.
 * @param length Optional maximum length.
 */
function validateClassPropertyValueLength(
  value: unknown,
  dataTypeKind: ClassPropertyDataTypeKind,
  length?: number | null,
): void {
  if (
    length === undefined ||
    length === null ||
    length <= 0 ||
    (dataTypeKind !== 'number' && dataTypeKind !== 'string')
  ) {
    return;
  }

  const comparableValue = getLengthComparableValue(value);

  if (comparableValue !== undefined && comparableValue.length > length) {
    throw new BadRequestException(
      `Expected value length to be at most ${length} characters.`,
    );
  }
}

/**
 * Normalizes a class property value according to metadata semantics.
 * @param value Candidate property value.
 * @param dataTypeKind Resolved property data type category.
 * @param cardinality Expected scalar or array cardinality.
 * @param allowedValues Optional accepted values.
 * @returns Normalized property value.
 */
function normalizeClassPropertyValue(
  value: unknown,
  dataTypeKind: ClassPropertyDataTypeKind,
  cardinality: 'single' | 'array',
  allowedValues: Array<string> | undefined,
): unknown {
  if (value === nullableValue) return nullableValue;

  switch (dataTypeKind) {
    case 'boolean': {
      return normalizeBooleanClassPropertyValue(value);
    }
    case 'date': {
      return normalizeDateClassPropertyValue(value);
    }
    case 'number': {
      return normalizeNumberClassPropertyValue(value);
    }
    case 'list': {
      return normalizeListClassPropertyValue(value, cardinality, allowedValues);
    }
    default: {
      return normalizeStringClassPropertyValue(value);
    }
  }
}

/**
 * Adds visible/all property projections to physical asset properties.
 * @param physicalAssets Physical assets whose properties are enriched.
 */
export function enrichPhysicalAssetProperties(
  physicalAssets: Array<PhysicalAsset>,
): void {
  for (const physicalAsset of physicalAssets) {
    for (const property of physicalAsset.physicalAssetProperties ?? []) {
      const propertiesJson = property.propertiesJson ?? {};
      const codeIndex = createPropertyCodeIndex(
        property.physicalAssetClass?.physicalAssetClassProperties ?? [],
      );

      const allProperties = Object.entries(propertiesJson).map(
        ([jsonKey, value]) => {
          const classProperty = codeIndex.get(
            normalizePhysicalAssetPropertyKey(jsonKey),
          );

          return {
            ...(classProperty ?? {
              code: jsonKey,
              propertySemanticsJson: nullableValue,
            }),
            jsonKey,
            propertySemanticsJson: classProperty
              ? PhysicalAssetClassPropertySemanticsTransformerDto.toApi(
                  classProperty.propertySemanticsJson,
                )
              : nullableValue,
            value,
          };
        },
      );

      const visibleProperties = allProperties.filter((entry) => {
        const semantics = entry.propertySemanticsJson;
        if (!semantics || typeof semantics !== 'object') return true;

        return (semantics as Record<string, unknown>).visible !== false;
      });

      Object.assign(property, {
        allProperties,
        visibleProperties,
      });

      if (property.physicalAssetClass) {
        property.physicalAssetClass.physicalAssetClassProperties = [];
      }
    }
  }
}

/**
 * Maps a physical asset entity to the base response DTO.
 * @param entity Physical asset entity to map.
 * @param language Preferred description language.
 * @returns Response DTO.
 */
export function mapPhysicalAssetToResponseDto(
  entity: PhysicalAsset,
  language = 'EN',
): PhysicalAssetResponseDto {
  const normalizedLanguage = (language || 'EN').toUpperCase();
  const selectedDescription =
    entity.descriptions?.find((d) => d.code === normalizedLanguage) ||
    entity.descriptions?.[0];

  return {
    code: entity.code,
    description: selectedDescription?.description || '',
    descriptionLanguageCode: normalizedLanguage,
    effectiveEndDate: entity.effectiveEndDate || nullableValue,
    effectiveStartDate: entity.effectiveStartDate || nullableValue,
    erpSource: entity.erpSource,
    id: entity.id,
    parentPhysicalAssetId: entity.parentPhysicalAssetId || nullableValue,
    physicalAssetLocation: entity.physicalAssetLocation || nullableValue,
    plant: entity.plant,
  };
}

/**
 * Maps a physical asset entity with nested relations to a response DTO.
 * @param entity Physical asset entity to map.
 * @param language Preferred description language.
 * @returns Response DTO with relations.
 */
export function mapPhysicalAssetToRelationsResponseDto(
  entity: PhysicalAsset,
  language = 'EN',
): PhysicalAssetWithRelationsResponseDto {
  const baseDto = mapPhysicalAssetToResponseDto(entity, language);
  const normalizedLanguage = (language || 'EN').toUpperCase();

  return {
    ...baseDto,
    children: entity.children?.map((child) =>
      mapPhysicalAssetToResponseDto(child, normalizedLanguage),
    ),
    descriptions: entity.descriptions?.map((d) => ({
      id: d.id,
      physicalAssetId: d.physicalAssetId,
      code: d.code,
      description: d.description,
    })),
    parentPhysicalAsset: entity.parentPhysicalAsset
      ? mapPhysicalAssetToResponseDto(
          entity.parentPhysicalAsset,
          normalizedLanguage,
        )
      : undefined,
    physicalAssetClassPhysicalAssets:
      entity.physicalAssetClassPhysicalAssets?.map((link) => ({
        id: link.id,
        physicalAssetClassId: link.physicalAssetClassId,
        physicalAssetId: link.physicalAssetId,
      })),
    physicalAssetProperties: entity.physicalAssetProperties?.map(
      (property) => ({
        id: property.id,
        physicalAssetClassId: property.physicalAssetClassId,
        physicalAssetClassPropertyId: 0,
        physicalAssetId: property.physicalAssetId,
        propertiesJson: property.propertiesJson,
      }),
    ),
  };
}

/**
 * Validates and normalizes physical asset property JSON against class property metadata.
 * @param classProperties Class property metadata.
 * @param properties Incoming property key-value payload.
 * @param physicalAssetClassId Physical asset class identifier for messages.
 * @returns Property payload with validated class-property values normalized.
 */
export function validatePhysicalAssetClassPropertyValues(
  classProperties: Array<PhysicalAssetClassProperty>,
  properties: Record<string, unknown>,
  physicalAssetClassId: number,
): Record<string, unknown> {
  if (!classProperties || Object.keys(properties).length === 0) {
    return properties;
  }

  const propertyIndex = createPropertyCodeIndex(classProperties);
  const normalizedProperties = { ...properties };

  for (const [jsonKey, value] of Object.entries(properties)) {
    const classProperty = propertyIndex.get(
      normalizePhysicalAssetPropertyKey(jsonKey),
    );
    if (classProperty) {
      const semantics = classProperty.propertySemanticsJson ?? {};
      const apiSemantics =
        PhysicalAssetClassPropertySemanticsTransformerDto.toApi(semantics) ??
        {};
      const cardinality =
        apiSemantics.cardinality === 'array' ? 'array' : 'single';
      const allowedValues = Array.isArray(apiSemantics.allowedValues)
        ? apiSemantics.allowedValues.map(String)
        : undefined;
      const dataTypeKind = getPropertyDataTypeKind(
        classProperty.propertyDataTypeId,
        classProperty.propertyDataType?.code,
      );

      try {
        const normalizedValue = normalizeClassPropertyValue(
          value,
          dataTypeKind,
          cardinality,
          allowedValues,
        );
        validateClassPropertyValueLength(
          normalizedValue,
          dataTypeKind,
          classProperty.length,
        );
        normalizedProperties[jsonKey] = normalizedValue;
      } catch (error) {
        throw new BadRequestException(
          `Invalid value for property "${jsonKey}" on physical asset class ${physicalAssetClassId}: ${error instanceof Error ? error.message : String(error)}`,
        );
      }
    }
  }

  return normalizedProperties;
}

