@Injectable()
export class PhysicalAssetCrudService {
  private static readonly defaultDescriptionLanguageCode = 'EN';

  private static async collectCascadeDeleteOrder(
    physicalAssetRepository: Repository<PhysicalAsset>,
    rootId: number,
  ): Promise<Array<number>> {
    const rows = await physicalAssetRepository.query(
      `WITH physical_asset_tree AS (
        SELECT
          physical_asset.id,
          physical_asset.parent_physical_asset_id,
          0 AS depth
        FROM isa95.physical_asset AS physical_asset
        WHERE physical_asset.id = @0

        UNION ALL

        SELECT
          child.id,
          child.parent_physical_asset_id,
          tree.depth + 1 AS depth
        FROM isa95.physical_asset AS child
        INNER JOIN physical_asset_tree AS tree
          ON child.parent_physical_asset_id = tree.id
      )
      SELECT id
      FROM physical_asset_tree
      ORDER BY depth DESC, id DESC
      OPTION (MAXRECURSION 0)`,
      [rootId],
    );

    return rows.map(({ id }: { id: number | string }) => Number(id));
  }

  private readonly logger = new AppLogger(PhysicalAssetCrudService.name);

  public constructor(
    @InjectRepository(PhysicalAsset)
    private readonly physicalAssetRepository: Repository<PhysicalAsset>,
    @InjectRepository(PhysicalAssetDescriptionByLanguage)
    private readonly physicalAssetDescriptionRepository: Repository<PhysicalAssetDescriptionByLanguage>,
    @InjectRepository(PhysicalAssetProperty)
    private readonly physicalAssetPropertyRepository: Repository<PhysicalAssetProperty>,
    @InjectRepository(PhysicalAssetClassPhysicalAsset)
    private readonly physicalAssetClassPhysicalAssetRepository: Repository<PhysicalAssetClassPhysicalAsset>,
  ) {}

  private async getPhysicalAssetClassPropertiesWithDataTypes(
    physicalAssetClassId: number,
  ): Promise<Array<PhysicalAssetClassProperty>> {
    return this.physicalAssetPropertyRepository.manager
      .getRepository(PhysicalAssetClassProperty)
      .createQueryBuilder('property')
      .leftJoinAndSelect('property.propertyDataType', 'propertyDataType')
      .where('property.physical_asset_class_id = :physicalAssetClassId', {
        physicalAssetClassId,
      })
      .getMany();
  }

  private buildJsonPath(key: string): string | undefined {
    const path = buildPhysicalAssetJsonPath(key);

    if (!path) {
      this.logger.warn(
        `Invalid JSON property key "${key}". Keys must contain only letters, digits, spaces, underscores, or hyphens and cannot start or end with spaces.`,
      );
    }

    return path;
  }

  private async resolveOrCreatePhysicalAssetPropertyId(
    physicalAsset: PhysicalAsset,
    physicalAssetClassId?: number,
  ): Promise<number | undefined> {
    if (physicalAssetClassId !== undefined) {
      const existingForClass =
        await this.physicalAssetPropertyRepository.findOne({
          where: { physicalAssetId: physicalAsset.id, physicalAssetClassId },
          order: { id: 'ASC' },
        });

      if (existingForClass) {
        return existingForClass.id;
      }

      const createdForClass = this.physicalAssetPropertyRepository.create({
        plant: physicalAsset.plant,
        physicalAssetId: physicalAsset.id,
        physicalAssetClassId,
        propertiesJson: {},
      });

      const savedForClass =
        await this.physicalAssetPropertyRepository.save(createdForClass);
      return savedForClass.id;
    }

    const existing = await this.physicalAssetPropertyRepository.find({
      where: { physicalAssetId: physicalAsset.id },
      order: { id: 'ASC' },
    });

    if (existing.length > 0) {
      return existing[0].id;
    }

    const links = await this.physicalAssetClassPhysicalAssetRepository.find({
      where: { physicalAssetId: physicalAsset.id },
      order: { physicalAssetClassId: 'ASC' },
    });

    if (links.length === 0) {
      this.logger.warn(
        `Cannot create physical asset property for physical asset ${physicalAsset.id} because no physical asset class link exists`,
      );
      return undefined;
    }

    const created = this.physicalAssetPropertyRepository.create({
      plant: physicalAsset.plant,
      physicalAssetId: physicalAsset.id,
      physicalAssetClassId: links[0].physicalAssetClassId,
      propertiesJson: {},
    });

    const saved = await this.physicalAssetPropertyRepository.save(created);
    return saved.id;
  }

  private async syncPhysicalAssetClasses(
    physicalAsset: PhysicalAsset,
    targetClassIds: Array<number>,
  ): Promise<void> {
    const uniqueTargetClassIds = [...new Set(targetClassIds)];
    const existingLinks =
      await this.physicalAssetClassPhysicalAssetRepository.find({
        where: { physicalAssetId: physicalAsset.id },
        order: { id: 'ASC' },
      });

    const existingClassIds = new Set(
      existingLinks.map((link) => link.physicalAssetClassId),
    );
    const targetClassIdSet = new Set(uniqueTargetClassIds);

    const toAdd = uniqueTargetClassIds.filter(
      (classId) => !existingClassIds.has(classId),
    );
    const toRemove = existingLinks
      .map((link) => link.physicalAssetClassId)
      .filter((classId) => !targetClassIdSet.has(classId));

    if (toAdd.length > 0) {
      const linksToCreate = toAdd.map((physicalAssetClassId) =>
        this.physicalAssetClassPhysicalAssetRepository.create({
          plant: physicalAsset.plant,
          physicalAssetId: physicalAsset.id,
          physicalAssetClassId,
        }),
      );
      await this.physicalAssetClassPhysicalAssetRepository.save(linksToCreate);
    }

    if (toRemove.length > 0) {
      await this.physicalAssetClassPhysicalAssetRepository.delete({
        physicalAssetId: physicalAsset.id,
        physicalAssetClassId: In(toRemove),
      });
    }
  }

  private async mergeJsonPropertiesByPropertyId(
    propertyId: number,
    properties: Record<string, unknown>,
  ): Promise<void> {
    const entries = Object.entries(properties);
    if (entries.length === 0) {
      return;
    }

    const parameters: Array<unknown> = [];
    let expression = 'properties_json';

    for (const [key, value] of entries) {
      const path = this.buildJsonPath(key);
      if (!path) {
        return;
      }

      const index = parameters.length;
      if (value !== null && typeof value === 'object') {
        parameters.push(JSON.stringify(value));
        expression = `JSON_MODIFY(${expression}, '${path}', JSON_QUERY(@${index}))`;
      } else {
        parameters.push(value);
        expression = `JSON_MODIFY(${expression}, '${path}', @${index})`;
      }
    }

    const idIndex = parameters.length;
    parameters.push(propertyId);

    await this.physicalAssetPropertyRepository.manager.query(
      `UPDATE [isa95].[physical_asset_property] SET properties_json = ${expression} WHERE id = @${idIndex}`,
      parameters,
    );
  }

  private async applyClassProperties(
    physicalAsset: PhysicalAsset,
    classProperties: Array<PhysicalAssetClassPropertiesInputDto>,
  ): Promise<void> {
    const uniqueClassIds = [
      ...new Set(classProperties.map((entry) => entry.physicalAssetClassId)),
    ];
    const classPropertiesById = new Map<
      number,
      Array<PhysicalAssetClassProperty>
    >();

    await Promise.all(
      uniqueClassIds.map(async (physicalAssetClassId) => {
        classPropertiesById.set(
          physicalAssetClassId,
          await this.getPhysicalAssetClassPropertiesWithDataTypes(
            physicalAssetClassId,
          ),
        );
      }),
    );

    await Promise.all(
      classProperties.map(async (entry) => {
        const propertiesForClass = classPropertiesById.get(
          entry.physicalAssetClassId,
        );

        const normalizedProperties = propertiesForClass
          ? validatePhysicalAssetClassPropertyValues(
              propertiesForClass,
              entry.properties,
              entry.physicalAssetClassId,
            )
          : entry.properties;

        const propertyId = await this.resolveOrCreatePhysicalAssetPropertyId(
          physicalAsset,
          entry.physicalAssetClassId,
        );

        if (propertyId !== undefined) {
          await this.mergeJsonPropertiesByPropertyId(
            propertyId,
            normalizedProperties,
          );
        }
      }),
    );
  }

  private async upsertDefaultDescription(
    physicalAssetId: number,
    plant: number,
    description: string,
  ): Promise<void> {
    const existingDescription =
      await this.physicalAssetDescriptionRepository.findOne({
        where: {
          code: PhysicalAssetCrudService.defaultDescriptionLanguageCode,
          physicalAssetId,
        },
      });

    if (existingDescription) {
      existingDescription.description = description;
      existingDescription.plant = plant;
      await this.physicalAssetDescriptionRepository.save(existingDescription);
      return;
    }

    const physicalAssetDescription =
      this.physicalAssetDescriptionRepository.create({
        code: PhysicalAssetCrudService.defaultDescriptionLanguageCode,
        description,
        physicalAssetId,
        plant,
      });
    await this.physicalAssetDescriptionRepository.save(
      physicalAssetDescription,
    );
  }

  public async create(
    payload: CreatePhysicalAssetDto,
  ): Promise<WrappedResponse<PhysicalAssetResponseDto | undefined>> {
    try {
      const existingPhysicalAsset = await this.physicalAssetRepository.findOne({
        where: {
          plant: payload.plant,
          code: payload.code,
        },
      });

      if (existingPhysicalAsset) {
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          `Physical asset with code ${payload.code} already exists in plant ${payload.plant}`,
        );
      }

      const { description, ...physicalAssetPayload } = payload;
      const physicalAsset =
        this.physicalAssetRepository.create(physicalAssetPayload);
      const savedPhysicalAsset =
        await this.physicalAssetRepository.save(physicalAsset);

      await this.upsertDefaultDescription(
        savedPhysicalAsset.id,
        savedPhysicalAsset.plant,
        description,
      );

      const createdAsset = await this.findOneWithRelations(
        savedPhysicalAsset.id,
      );
      if (createdAsset.success && createdAsset.data) {
        return ResponseWrapper.success(
          STATUS_CODE.CREATED,
          'Physical asset created successfully',
          createdAsset.data,
        );
      }

      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Physical asset created but could not retrieve details',
      );
    } catch (error) {
      return throwWrappedInternalError(this.logger, 'create', error);
    }
  }

  public async findAll(
    plant?: number,
  ): Promise<WrappedResponse<Array<PhysicalAssetResponseDto> | undefined>> {
    try {
      const assets = await this.physicalAssetRepository.find({
        order: { id: 'ASC' },
        relations: ['descriptions'],
        ...(plant === undefined ? {} : { where: { plant } }),
      });

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical assets retrieved successfully',
        assets.map((asset) => mapPhysicalAssetToResponseDto(asset)),
      );
    } catch (error) {
      return throwWrappedInternalError(this.logger, 'findAll', error);
    }
  }

  public async getRestrictedPhysicalAssetDetailsFlat(
    plant: number,
    limit = 50,
    offset = 0,
  ): Promise<
    WrappedResponse<RestrictedPhysicalAssetFlatPaginatedResponse | undefined>
  > {
    try {
      const safeLimit = Number.isNaN(limit)
        ? 50
        : Math.min(Math.max(limit, 1), 500);
      const safeOffset = Number.isNaN(offset) || offset < 0 ? 0 : offset;

      const rows = await this.physicalAssetRepository
        .createQueryBuilder('physicalAsset')
        .leftJoin(
          PhysicalAssetDescriptionByLanguage,
          'description',
          'description.physical_asset_id = physicalAsset.id',
        )
        .leftJoin(
          PhysicalAssetClassPhysicalAsset,
          'classLink',
          'classLink.physical_asset_id = physicalAsset.id AND classLink.plant = physicalAsset.plant',
        )
        .leftJoin(
          PhysicalAssetClass,
          'physicalAssetClass',
          'physicalAssetClass.id = classLink.physical_asset_class_id',
        )
        .leftJoin(
          PhysicalAssetProperty,
          'property',
          'property.physical_asset_id = physicalAsset.id AND property.plant = physicalAsset.plant AND (classLink.physical_asset_class_id IS NULL OR property.physical_asset_class_id = classLink.physical_asset_class_id)',
        )
        .where('physicalAsset.plant = :plant', { plant })
        .select([
          'physicalAsset.id AS id',
          'physicalAsset.code AS code',
          'physicalAsset.plant AS plant',
          'physicalAsset.erp_source AS erpSource',
          'physicalAsset.parent_physical_asset_id AS parentPhysicalAssetId',
          'physicalAsset.physical_asset_location AS physicalAssetLocation',
          'physicalAsset.effective_start_date AS effectiveStartDate',
          'physicalAsset.effective_end_date AS effectiveEndDate',
          'description.code AS descriptionLanguageCode',
          'description.description AS descriptionByLanguage',
          'physicalAssetClass.id AS classId',
          'physicalAssetClass.code AS classCode',
          'physicalAssetClass.is_custom AS classIsCustom',
          'property.id AS propertyId',
          'property.properties_json AS propertiesJson',
        ])
        .orderBy('physicalAsset.id', 'ASC')
        .addOrderBy('description.code', 'ASC')
        .addOrderBy('physicalAssetClass.id', 'ASC')
        .addOrderBy('property.id', 'ASC')
        .getRawMany();

      const result = {
        data: rows.slice(safeOffset, safeOffset + safeLimit),
        limit: safeLimit,
        offset: safeOffset,
        total: rows.length,
      };

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Restricted physical asset details retrieved successfully',
        result,
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        'getRestrictedPhysicalAssetDetailsFlat',
        error,
      );
    }
  }

  public async findParentOptions(
    plant: number,
    excludePhysicalAssetId?: number,
