        .leftJoinAndSelect('physicalAsset.descriptions', 'descriptions')
        .where('physicalAsset.plant = :plant', { plant })
        .orderBy('physicalAsset.id', 'ASC');

      if (excludePhysicalAssetId !== undefined) {
        query.andWhere('physicalAsset.id != :excludePhysicalAssetId', {
          excludePhysicalAssetId,
        });
      }

      const assets = await query.getMany();

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Parent asset options retrieved successfully',
        assets.map((asset) => mapPhysicalAssetToResponseDto(asset)),
      );
    } catch (error) {
      return throwWrappedInternalError(this.logger, 'findParentOptions', error);
    }
  }

  public async findAllWithRelations(
    pagination: PaginationDto,
  ): Promise<
    WrappedResponse<Array<PhysicalAssetWithRelationsResponseDto> | undefined>
  > {
    try {
      const [data] = await this.physicalAssetRepository.findAndCount({
        order: { id: 'ASC' },
        skip: pagination.offset,
        take: pagination.limit,
        relations: [
          'descriptions',
          'parentPhysicalAsset',
          'parentPhysicalAsset.descriptions',
          'children',
          'children.descriptions',
          'physicalAssetClassPhysicalAssets',
          'physicalAssetClassPhysicalAssets.physicalAssetClass',
          'physicalAssetProperties',
          'physicalAssetProperties.physicalAssetClass',
          'physicalAssetProperties.physicalAssetClass.physicalAssetClassProperties',
        ],
      });

      enrichPhysicalAssetProperties(data);

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical assets with relations retrieved successfully',
        data.map((asset) => mapPhysicalAssetToRelationsResponseDto(asset)),
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        'findAllWithRelations',
        error,
      );
    }
  }

  public async findOne(
