  public async findOneWithRelations(
    id: number,
  ): Promise<
    WrappedResponse<PhysicalAssetWithRelationsResponseDto | undefined>
  > {
    try {
      const physicalAsset = await this.physicalAssetRepository.findOne({
        where: { id },
        relations: [
          'descriptions',
          'parentPhysicalAsset',
          'parentPhysicalAsset.descriptions',
          'children',
          'children.descriptions',
          'physicalAssetClassPhysicalAssets',
          'physicalAssetClassPhysicalAssets.physicalAssetClass',
          'physicalAssetProperties',
          'physicalAssetProperties.physicalAssetClass',
