  public async update(
    id: number,
    payload: UpdatePhysicalAssetDto,
  ): Promise<WrappedResponse<PhysicalAssetResponseDto | undefined>> {
    try {
      const physicalAssetResult = await this.findOne(id);

      if (!physicalAssetResult.success || !physicalAssetResult.data) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical asset with id ${id} not found`,
        );
      }

      // Find the raw entity for modification
      const rawAsset = await this.physicalAssetRepository.findOne({
        where: { id },
      });

      if (!rawAsset) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical asset with id ${id} not found`,
        );
      }

      if (payload.plant !== undefined) {
        rawAsset.plant = payload.plant;
      }

      if (payload.code !== undefined) {
        rawAsset.code = payload.code;
      }

      if (payload.description !== undefined) {
        await this.upsertDefaultDescription(
          rawAsset.id,
          payload.plant ?? rawAsset.plant,
          payload.description,
        );
      }

      if (payload.parentPhysicalAssetId !== undefined) {
        rawAsset.parentPhysicalAssetId = payload.parentPhysicalAssetId;
      }

      if (payload.physicalAssetLocation !== undefined) {
        rawAsset.physicalAssetLocation = payload.physicalAssetLocation;
      }

      if (payload.effectiveStartDate !== undefined) {
        rawAsset.effectiveStartDate = payload.effectiveStartDate;
      }

      if (payload.effectiveEndDate !== undefined) {
        rawAsset.effectiveEndDate = payload.effectiveEndDate;
      }

      if (payload.erpSource !== undefined) {
        rawAsset.erpSource = payload.erpSource;
      }

      await this.physicalAssetRepository.save(rawAsset);
      const updatedResult = await this.findOneWithRelations(id);

      if (updatedResult.success && updatedResult.data) {
        return ResponseWrapper.success(
          STATUS_CODE.OK,
          'Physical asset updated successfully',
          updatedResult.data,
        );
      }

      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Physical asset updated but could not retrieve updated details',
      );
    } catch (error) {
      return throwWrappedInternalError(this.logger, 'update', error);
    }
  }

  public async savePhysicalAssetDetails(
    id: number,
    payload: SavePhysicalAssetDetailsDto,
  ): Promise<WrappedResponse<PhysicalAssetResponseDto | undefined>> {
    try {
      const {
        classIds,
        classProperties,
        properties,
        propertiesPhysicalAssetClassId,
        ...physicalAssetData
      } = payload;

      const physicalAssetResult = await this.findOne(id);
      if (!physicalAssetResult.success || !physicalAssetResult.data) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical asset with id ${id} not found`,
        );
      }

      const updateResult = await this.update(id, physicalAssetData);
      if (!updateResult.success) {
        return updateResult;
      }

      // Get raw entity for further operations
      const rawAsset = await this.physicalAssetRepository.findOne({
        where: { id },
      });

      if (!rawAsset) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical asset with id ${id} not found`,
        );
      }

      const classIdsFromProperties = (classProperties ?? []).map(
        (entry) => entry.physicalAssetClassId,
      );
      const targetClassIds =
        classIds !== undefined || classIdsFromProperties.length > 0
          ? [...new Set([...(classIds ?? []), ...classIdsFromProperties])]
          : undefined;

      if (targetClassIds !== undefined) {
        await this.syncPhysicalAssetClasses(rawAsset, targetClassIds);
      }

      if (properties !== undefined) {
        let normalizedProperties = properties;
        if (propertiesPhysicalAssetClassId !== undefined) {
          const classPropertiesForValidation =
            await this.getPhysicalAssetClassPropertiesWithDataTypes(
              propertiesPhysicalAssetClassId,
            );
          normalizedProperties = validatePhysicalAssetClassPropertyValues(
            classPropertiesForValidation,
            properties,
            propertiesPhysicalAssetClassId,
          );
        }

        const propertyId = await this.resolveOrCreatePhysicalAssetPropertyId(
          rawAsset,
          propertiesPhysicalAssetClassId,
        );

        if (propertyId === undefined) {
          return ResponseWrapper.error(
            STATUS_CODE.INTERNAL_SERVER_ERROR,
            'Could not resolve or create physical asset property',
          );
        }

        await this.mergeJsonPropertiesByPropertyId(
          propertyId,
          normalizedProperties,
        );
      }

      if (classProperties !== undefined && classProperties.length > 0) {
        await this.applyClassProperties(rawAsset, classProperties);
      }

      const finalResult = await this.findOneWithRelations(id);
      if (finalResult.success && finalResult.data) {
        return ResponseWrapper.success(
          STATUS_CODE.OK,
          'Physical asset details saved successfully',
          finalResult.data,
        );
      }

      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Physical asset details saved but could not retrieve updated details',
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        'savePhysicalAssetDetails',
        error,
      );
    }
  }

  public async createWithDetails(
    payload: CreatePhysicalAssetWithDetailsDto,
  ): Promise<WrappedResponse<PhysicalAssetResponseDto | undefined>> {
    try {
      const {
        classIds,
        classProperties,
        properties,
        propertiesPhysicalAssetClassId,
        ...basePayload
      } = payload;

      const createResult = await this.create(basePayload);
      if (!createResult.success || !createResult.data) {
        return createResult;
      }

      // Get raw asset for further operations
      const rawAsset = await this.physicalAssetRepository.findOne({
        where: { id: createResult.data.id },
      });

      if (!rawAsset) {
        return ResponseWrapper.error(
          STATUS_CODE.INTERNAL_SERVER_ERROR,
          'Physical asset created but could not retrieve for further operations',
        );
      }

      const classIdsFromProperties = (classProperties ?? []).map(
        (entry) => entry.physicalAssetClassId,
      );
      const targetClassIds = [
        ...new Set([...(classIds ?? []), ...classIdsFromProperties]),
      ];

      if (targetClassIds.length > 0) {
        await this.syncPhysicalAssetClasses(rawAsset, targetClassIds);
      }

      if (properties !== undefined) {
        let normalizedProperties = properties;
        if (propertiesPhysicalAssetClassId !== undefined) {
          const classPropertiesForValidation =
            await this.getPhysicalAssetClassPropertiesWithDataTypes(
              propertiesPhysicalAssetClassId,
            );
          normalizedProperties = validatePhysicalAssetClassPropertyValues(
            classPropertiesForValidation,
            properties,
            propertiesPhysicalAssetClassId,
          );
        }

        const propertyId = await this.resolveOrCreatePhysicalAssetPropertyId(
          rawAsset,
          propertiesPhysicalAssetClassId,
        );

        if (propertyId !== undefined) {
          await this.mergeJsonPropertiesByPropertyId(
            propertyId,
            normalizedProperties,
          );
        }
      }

      if (classProperties !== undefined && classProperties.length > 0) {
        await this.applyClassProperties(rawAsset, classProperties);
      }

      const finalResult = await this.findOneWithRelations(rawAsset.id);
      if (finalResult.success && finalResult.data) {
        return ResponseWrapper.success(
          STATUS_CODE.CREATED,
          'Physical asset created with details successfully',
          finalResult.data,
        );
      }

      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'Physical asset created but could not retrieve created details',
      );
    } catch (error) {
      return throwWrappedInternalError(this.logger, 'createWithDetails', error);
    }
  }

  public async remove(id: number): Promise<WrappedResponse<undefined>> {
    try {
      const physicalAssetResult = await this.findOne(id);
      if (!physicalAssetResult.success) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical asset with id ${id} not found`,
        );
      }

      await this.physicalAssetRepository.manager.transaction(
        async (manager) => {
          const physicalAssetRepository = manager.getRepository(PhysicalAsset);
          const physicalAssetDescriptionRepository = manager.getRepository(
            PhysicalAssetDescriptionByLanguage,
          );
          const physicalAssetClassPhysicalAssetRepository =
            manager.getRepository(PhysicalAssetClassPhysicalAsset);
          const physicalAssetPropertyRepository = manager.getRepository(
            PhysicalAssetProperty,
          );

          const deleteOrder =
            await PhysicalAssetCrudService.collectCascadeDeleteOrder(
              physicalAssetRepository,
              id,
            );

          if (deleteOrder.length === 0) {
            return;
          }

          await physicalAssetPropertyRepository.delete({
            physicalAssetId: In(deleteOrder),
          });
          await physicalAssetClassPhysicalAssetRepository.delete({
            physicalAssetId: In(deleteOrder),
          });
          await physicalAssetDescriptionRepository.delete({
            physicalAssetId: In(deleteOrder),
          });

          let deleteChain: Promise<unknown> = Promise.resolve();
          for (const delId of deleteOrder) {
            deleteChain = deleteChain.then(() =>
              physicalAssetRepository.delete(delId),
            );
          }
          await deleteChain;
        },
      );

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical asset deleted successfully',
      );
    } catch (error) {
      return throwWrappedInternalError(this.logger, 'remove', error);
    }
  }
}

