@Injectable()
export class PhysicalAssetDescriptionByLanguageCrudService {
  private static mapToResponseDto(
    entity: PhysicalAssetDescriptionByLanguage,
  ): PhysicalAssetDescriptionResponseDto {
    return {
      id: entity.id,
      physicalAssetId: entity.physicalAssetId,
      code: entity.code,
      description: entity.description,
    } as unknown as PhysicalAssetDescriptionResponseDto;
  }

  private readonly logger = new AppLogger(
    PhysicalAssetDescriptionByLanguageCrudService.name,
  );

  public constructor(
    @InjectRepository(PhysicalAssetDescriptionByLanguage)
    private readonly physicalAssetDescriptionRepository: Repository<PhysicalAssetDescriptionByLanguage>,
  ) {}

  public async create(
    payload: CreatePhysicalAssetDescriptionByLanguageDto,
  ): Promise<WrappedResponse<PhysicalAssetDescriptionResponseDto | undefined>> {
    try {
      const existing = await this.physicalAssetDescriptionRepository.findOne({
        where: { physicalAssetId: payload.physicalAssetId, code: payload.code },
      });

      if (existing) {
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          `Physical asset description already exists for physical asset ${payload.physicalAssetId} and language ${payload.code}`,
        );
      }

      const description =
        this.physicalAssetDescriptionRepository.create(payload);
      const saved =
        await this.physicalAssetDescriptionRepository.save(description);

      return ResponseWrapper.success(
        STATUS_CODE.CREATED,
        'Physical asset description created successfully',
        PhysicalAssetDescriptionByLanguageCrudService.mapToResponseDto(saved),
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET DESCRIPTION CREATE FAILED',
      );
    }
  }

  public async findAll(): Promise<
    WrappedResponse<Array<PhysicalAssetDescriptionResponseDto> | undefined>
  > {
    try {
      const descriptions = await this.physicalAssetDescriptionRepository.find({
        order: { id: 'ASC' },
      });

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical asset descriptions retrieved successfully',
        descriptions.map((desc) =>
          PhysicalAssetDescriptionByLanguageCrudService.mapToResponseDto(desc),
        ),
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET DESCRIPTIONS RETRIEVE FAILED',
      );
    }
  }

  public async findOne(
    id: number,
  ): Promise<WrappedResponse<PhysicalAssetDescriptionResponseDto | undefined>> {
    try {
      const description = await this.physicalAssetDescriptionRepository.findOne(
        {
          where: { id },
        },
      );

      if (!description) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical asset description with id ${id} not found`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical asset description retrieved successfully',
        PhysicalAssetDescriptionByLanguageCrudService.mapToResponseDto(
          description,
        ),
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET DESCRIPTION RETRIEVE FAILED',
      );
    }
  }

  public async update(
    id: number,
    payload: UpdatePhysicalAssetDescriptionByLanguageDto,
  ): Promise<WrappedResponse<PhysicalAssetDescriptionResponseDto | undefined>> {
    try {
      const description = await this.physicalAssetDescriptionRepository.findOne(
        {
          where: { id },
        },
      );

      if (!description) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical asset description with id ${id} not found`,
        );
      }

      if (payload.plant !== undefined) {
        description.plant = payload.plant;
      }

      if (payload.code !== undefined) {
        description.code = payload.code;
      }

      if (payload.description !== undefined) {
        description.description = payload.description;
      }

      if (payload.physicalAssetId !== undefined) {
        description.physicalAssetId = payload.physicalAssetId;
      }

      const saved =
        await this.physicalAssetDescriptionRepository.save(description);

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical asset description updated successfully',
        PhysicalAssetDescriptionByLanguageCrudService.mapToResponseDto(saved),
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET DESCRIPTION UPDATE FAILED',
      );
    }
  }

  public async remove(id: number): Promise<WrappedResponse<undefined>> {
    try {
      const response = await this.physicalAssetDescriptionRepository.delete({
        id,
      });

      if (!response.affected) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical asset description with id ${id} not found`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical asset description deleted successfully',
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET DESCRIPTION DELETE FAILED',
      );
    }
  }
}

