import {
  Column,
  Entity,
  JoinColumn,
  ManyToOne,
  OneToMany,
  PrimaryGeneratedColumn,
  Unique,
} from 'typeorm';
import { TimeStamp } from '@/modules/generics/timestamp';
import { PhysicalAssetDescriptionByLanguage } from '@/modules/isa9-physical-asset-model/physical-asset/physical-asset-description-by-language/physical-asset-description-by-language.entity';
import { PhysicalAssetClassPhysicalAsset } from '@/modules/isa9-physical-asset-model/shared/physical-asset-class-physical-asset/physical-asset-class-physical-asset.entity';
import { PhysicalAssetProperty } from '@/modules/isa9-physical-asset-model/shared/physical-asset-property/physical-asset-property.entity';

@Entity({ name: 'physical_asset', schema: 'isa95' })
@Unique('uq_physical_asset_plant_code', ['plant', 'code'])
export class PhysicalAsset extends TimeStamp {
  @PrimaryGeneratedColumn({ name: 'id' })
  public id: number;

  @Column({ name: 'parent_physical_asset_id', nullable: true })
  public parentPhysicalAssetId: number | null;

  @Column({
    name: 'plant',
    nullable: false,
    type: 'smallint',
  })
  public plant: number;

  @Column({
    length: 18,
    name: 'code',
    nullable: false,
    type: 'nvarchar',
  })
  public code: string;

  @Column({
    length: 30,
    name: 'physical_asset_location',
    nullable: true,
    type: 'nvarchar',
  })
  public physicalAssetLocation: string | null;

  @Column({ name: 'effective_start_date', nullable: true })
  public effectiveStartDate: Date;

  @Column({ name: 'effective_end_date', nullable: true })
  public effectiveEndDate: Date;

  @Column({
    length: 3,
    name: 'erp_source',
    nullable: false,
    type: 'char',
  })
  public erpSource: string;

  @ManyToOne(() => PhysicalAsset, (physicalAsset) => physicalAsset.children)
  @JoinColumn({
    name: 'parent_physical_asset_id',
    referencedColumnName: 'id',
    foreignKeyConstraintName: 'fk_physical_asset_physical_asset',
  })
  public parentPhysicalAsset: PhysicalAsset | null;

  @OneToMany(
    () => PhysicalAsset,
    (physicalAsset) => physicalAsset.parentPhysicalAsset,
  )
  public children: Array<PhysicalAsset>;

  @OneToMany(
    () => PhysicalAssetDescriptionByLanguage,
    (physicalAssetDescriptionByLanguage) =>
      physicalAssetDescriptionByLanguage.physicalAsset,
  )
  public descriptions: Array<PhysicalAssetDescriptionByLanguage>;

  @OneToMany(
    () => PhysicalAssetClassPhysicalAsset,
    (physicalAssetClassPhysicalAsset) =>
      physicalAssetClassPhysicalAsset.physicalAsset,
  )
  public physicalAssetClassPhysicalAssets: Array<PhysicalAssetClassPhysicalAsset>;

  @OneToMany(
    () => PhysicalAssetProperty,
    (physicalAssetProperty) => physicalAssetProperty.physicalAsset,
  )
  public physicalAssetProperties: Array<PhysicalAssetProperty>;
}

