import {
  ResponseWrapper,
  STATUS_CODE,
  WrappedResponse,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AppLogger } from '@/common/logger/app-logger';
import { CreatePhysicalAssetClassPhysicalAssetDto } from '@/modules/isa9-physical-asset-model/dtos/create-physical-asset-class-physical-asset.dto';
import { PhysicalAssetClassPhysicalAssetResponseDto } from '@/modules/isa9-physical-asset-model/dtos/physical-asset-class-physical-asset-response.dto';
import { PhysicalAssetClassPhysicalAsset } from '@/modules/isa9-physical-asset-model/shared/physical-asset-class-physical-asset/physical-asset-class-physical-asset.entity';

@Injectable()
export class PhysicalAssetClassPhysicalAssetCrudService {
  private static mapToResponseDto(
    entity: PhysicalAssetClassPhysicalAsset,
  ): PhysicalAssetClassPhysicalAssetResponseDto {
    return {
      id: entity.id,
      physicalAssetClassId: entity.physicalAssetClassId,
      physicalAssetId: entity.physicalAssetId,
    } as unknown as PhysicalAssetClassPhysicalAssetResponseDto;
  }

  private readonly logger = new AppLogger(
    PhysicalAssetClassPhysicalAssetCrudService.name,
  );

  public constructor(
    @InjectRepository(PhysicalAssetClassPhysicalAsset)
    private readonly physicalAssetClassPhysicalAssetRepository: Repository<PhysicalAssetClassPhysicalAsset>,
  ) {}

  public async create(
    payload: CreatePhysicalAssetClassPhysicalAssetDto,
  ): Promise<
    WrappedResponse<PhysicalAssetClassPhysicalAssetResponseDto | undefined>
  > {
    try {
      const existing =
        await this.physicalAssetClassPhysicalAssetRepository.findOne({
          where: {
            physicalAssetId: payload.physicalAssetId,
            physicalAssetClassId: payload.physicalAssetClassId,
          },
        });

      if (existing) {
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          `Physical asset ${payload.physicalAssetId} is already linked to class ${payload.physicalAssetClassId}`,
        );
      }

      const link =
        this.physicalAssetClassPhysicalAssetRepository.create(payload);
      const saved =
        await this.physicalAssetClassPhysicalAssetRepository.save(link);

      return ResponseWrapper.success(
        STATUS_CODE.CREATED,
        'Physical asset-to-class link created successfully',
        PhysicalAssetClassPhysicalAssetCrudService.mapToResponseDto(saved),
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET CLASS PHYSICAL ASSET CREATE FAILED',
      );
    }
  }

  public async findAll(): Promise<
    WrappedResponse<
      Array<PhysicalAssetClassPhysicalAssetResponseDto> | undefined
    >
  > {
    try {
      const links = await this.physicalAssetClassPhysicalAssetRepository.find({
        order: { id: 'ASC' },
      });

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical asset-to-class links retrieved successfully',
        links.map((link) =>
          PhysicalAssetClassPhysicalAssetCrudService.mapToResponseDto(link),
        ),
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET CLASS PHYSICAL ASSETS RETRIEVE FAILED',
      );
    }
  }

  public async findByPhysicalAssetId(
    physicalAssetId: number,
  ): Promise<
    WrappedResponse<
      Array<PhysicalAssetClassPhysicalAssetResponseDto> | undefined
    >
  > {
    try {
      const links = await this.physicalAssetClassPhysicalAssetRepository.find({
        where: { physicalAssetId },
        order: { id: 'ASC' },
      });

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical asset-to-class links retrieved successfully',
        links.map((link) =>
          PhysicalAssetClassPhysicalAssetCrudService.mapToResponseDto(link),
        ),
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET CLASS PHYSICAL ASSETS RETRIEVE FAILED',
      );
    }
  }

  public async findByPhysicalAssetClassId(
    physicalAssetClassId: number,
  ): Promise<
    WrappedResponse<
      Array<PhysicalAssetClassPhysicalAssetResponseDto> | undefined
    >
  > {
    try {
      const links = await this.physicalAssetClassPhysicalAssetRepository.find({
        where: { physicalAssetClassId },
        order: { id: 'ASC' },
      });

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical asset-to-class links retrieved successfully',
        links.map((link) =>
          PhysicalAssetClassPhysicalAssetCrudService.mapToResponseDto(link),
        ),
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET CLASS PHYSICAL ASSETS RETRIEVE FAILED',
      );
    }
  }

  public async findOne(
    id: number,
  ): Promise<
    WrappedResponse<PhysicalAssetClassPhysicalAssetResponseDto | undefined>
  > {
    try {
      const link = await this.physicalAssetClassPhysicalAssetRepository.findOne(
        {
          where: { id },
        },
      );

      if (!link) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical-asset-to-class link with id ${id} not found`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical asset-to-class link retrieved successfully',
        PhysicalAssetClassPhysicalAssetCrudService.mapToResponseDto(link),
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET CLASS PHYSICAL ASSET RETRIEVE FAILED',
      );
    }
  }

  public async remove(id: number): Promise<WrappedResponse<undefined>> {
    try {
      const response =
        await this.physicalAssetClassPhysicalAssetRepository.delete({
          id,
        });

      if (!response.affected) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical-asset-to-class link with id ${id} not found`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical asset-to-class link deleted successfully',
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET CLASS PHYSICAL ASSET DELETE FAILED',
      );
    }
  }

  public async removeByPhysicalAssetAndClass(
    physicalAssetId: number,
    physicalAssetClassId: number,
  ): Promise<WrappedResponse<undefined>> {
    try {
      const response =
        await this.physicalAssetClassPhysicalAssetRepository.delete({
          physicalAssetId,
          physicalAssetClassId,
        });

      if (!response.affected) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `No link found between physical asset ${physicalAssetId} and class ${physicalAssetClassId}`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical asset-to-class link deleted successfully',
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET CLASS PHYSICAL ASSET DELETE FAILED',
      );
    }
  }
}

