const SAFE_PHYSICAL_ASSET_JSON_KEY_PATTERN = /^[\w -]+$/;

/**
 * Returns whether a JSON property key is safe to use in SQL Server JSON path expressions.
 * @param key The physical asset JSON property key to validate.
 * @returns `true` when the key is safe to use in a JSON path expression.
 */
export function isSafePhysicalAssetJsonKey(key: string): boolean {
  return (
    key.length > 0 &&
    key === key.trim() &&
    SAFE_PHYSICAL_ASSET_JSON_KEY_PATTERN.test(key)
  );
}

/**
 * Builds a SQL Server JSON path for a validated physical asset property key.
 * @param key The physical asset JSON property key to convert to a JSON path.
 * @returns The SQL Server JSON path when the key is valid; otherwise `undefined`.
 */
export function buildPhysicalAssetJsonPath(key: string): string | undefined {
  if (!isSafePhysicalAssetJsonKey(key)) {
    return undefined;
  }

  return `$."${key}"`;
}

/**
 * Normalizes a property key for case-insensitive matching across JSON keys and class property codes.
 * @param key The JSON property key or class property code to normalize.
 * @returns The normalized key used for lookups.
 */
export function normalizePhysicalAssetPropertyKey(key: string): string {
  return key
    .trim()
    .toLowerCase()
    .replaceAll(/[^\da-z]+/g, '');
}

import {
  ResponseWrapper,
  STATUS_CODE,
  WrappedResponse,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AppLogger } from '@/common/logger/app-logger';
import { CreatePhysicalAssetPropertyDto } from '@/modules/isa9-physical-asset-model/dtos/create-physical-asset-property.dto';
import { PhysicalAssetPropertyResponseDto } from '@/modules/isa9-physical-asset-model/dtos/physical-asset-property-response.dto';
import { UpdatePhysicalAssetPropertyDto } from '@/modules/isa9-physical-asset-model/dtos/update-physical-asset-property.dto';
import { buildPhysicalAssetJsonPath } from '@/modules/isa9-physical-asset-model/shared/physical-asset-json-path.util';
import { PhysicalAssetProperty } from '@/modules/isa9-physical-asset-model/shared/physical-asset-property/physical-asset-property.entity';
import { DeleteJsonPropertiesDto } from '@/modules/isa95-equipment-model/dtos/delete-json-properties.dto';
import { PatchJsonPropertiesDto } from '@/modules/isa95-equipment-model/dtos/patch-json-properties.dto';

@Injectable()
export class PhysicalAssetPropertyCrudService {
  private static mapToResponseDto(
    entity: PhysicalAssetProperty,
  ): PhysicalAssetPropertyResponseDto {
    return {
      id: entity.id,
      physicalAssetClassId: entity.physicalAssetClassId,
      physicalAssetClassPropertyId: 0, // Not available in entity
      physicalAssetId: entity.physicalAssetId,
      propertiesJson: entity.propertiesJson,
    } as unknown as PhysicalAssetPropertyResponseDto;
  }

  private readonly logger = new AppLogger(
    PhysicalAssetPropertyCrudService.name,
  );

  public constructor(
    @InjectRepository(PhysicalAssetProperty)
    private readonly physicalAssetPropertyRepository: Repository<PhysicalAssetProperty>,
  ) {}

  private buildJsonPath(key: string): string | undefined {
    const path = buildPhysicalAssetJsonPath(key);

    if (!path) {
      this.logger.warn(
        `Invalid JSON property key "${key}". Keys must contain only letters, digits, spaces, underscores, or hyphens and cannot start or end with spaces.`,
      );
    }

    return path;
  }

  public async create(
    payload: CreatePhysicalAssetPropertyDto,
  ): Promise<WrappedResponse<PhysicalAssetPropertyResponseDto | undefined>> {
    try {
      const physicalAssetProperty =
        this.physicalAssetPropertyRepository.create(payload);
      const saved = await this.physicalAssetPropertyRepository.save(
        physicalAssetProperty,
      );

      return ResponseWrapper.success(
        STATUS_CODE.CREATED,
        'Physical asset property created successfully',
        PhysicalAssetPropertyCrudService.mapToResponseDto(saved),
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET PROPERTY CREATE FAILED',
      );
    }
  }

  public async findAll(): Promise<
    WrappedResponse<Array<PhysicalAssetPropertyResponseDto> | undefined>
  > {
    try {
      const properties = await this.physicalAssetPropertyRepository.find({
        order: { id: 'ASC' },
      });

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical asset properties retrieved successfully',
        properties.map((property) =>
          PhysicalAssetPropertyCrudService.mapToResponseDto(property),
        ),
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET PROPERTIES RETRIEVE FAILED',
      );
    }
  }

  public async findOne(
    id: number,
  ): Promise<WrappedResponse<PhysicalAssetPropertyResponseDto | undefined>> {
    try {
      const physicalAssetProperty =
        await this.physicalAssetPropertyRepository.findOne({
          where: { id },
        });

      if (!physicalAssetProperty) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical asset property with id ${id} not found`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical asset property retrieved successfully',
        PhysicalAssetPropertyCrudService.mapToResponseDto(
          physicalAssetProperty,
        ),
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET PROPERTY RETRIEVE FAILED',
      );
    }
  }

  public async update(
    id: number,
    payload: UpdatePhysicalAssetPropertyDto,
  ): Promise<WrappedResponse<PhysicalAssetPropertyResponseDto | undefined>> {
    try {
      const existing = await this.physicalAssetPropertyRepository.findOne({
        where: { id },
      });

      if (!existing) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical asset property with id ${id} not found`,
        );
      }

      const setClauses: Array<string> = [];
      const parameters: Array<unknown> = [];

      if (payload.plant !== undefined) {
        setClauses.push(`plant = @${parameters.length}`);
        parameters.push(payload.plant);
      }

      if (payload.physicalAssetId !== undefined) {
        setClauses.push(`physical_asset_id = @${parameters.length}`);
        parameters.push(payload.physicalAssetId);
      }

      if (payload.physicalAssetClassId !== undefined) {
        setClauses.push(`physical_asset_class_id = @${parameters.length}`);
        parameters.push(payload.physicalAssetClassId);
      }

      if (payload.propertiesJson !== undefined) {
        setClauses.push(`properties_json = @${parameters.length}`);
        parameters.push(JSON.stringify(payload.propertiesJson));
      }

      if (setClauses.length > 0) {
        parameters.push(id);
        await this.physicalAssetPropertyRepository.manager.query(
          `UPDATE [isa95].[physical_asset_property] SET ${setClauses.join(', ')} WHERE id = @${parameters.length - 1}`,
          parameters,
        );
      }

      const updated = await this.physicalAssetPropertyRepository.findOne({
        where: { id },
      });

      if (!updated) {
        return ResponseWrapper.error(
          STATUS_CODE.INTERNAL_SERVER_ERROR,
          'Failed to retrieve updated property',
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical asset property updated successfully',
        PhysicalAssetPropertyCrudService.mapToResponseDto(updated),
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET PROPERTY UPDATE FAILED',
      );
    }
  }

  public async remove(id: number): Promise<WrappedResponse<undefined>> {
    try {
      const response = await this.physicalAssetPropertyRepository.delete({
        id,
      });

      if (!response.affected) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical asset property with id ${id} not found`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Physical asset property deleted successfully',
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET PROPERTY DELETE FAILED',
      );
    }
  }

  public async getJsonProperties(
    id: number,
    keys: Array<string>,
  ): Promise<WrappedResponse<Record<string, unknown> | undefined>> {
    try {
      if (keys.length === 0) {
        return ResponseWrapper.success(
          STATUS_CODE.OK,
          'JSON properties retrieved successfully',
          {},
        );
      }

      const projections = keys.map((key) => {
        const path = this.buildJsonPath(key);
        return path
          ? `JSON_VALUE(p.properties_json, '${path}') AS [${key}]`
          : '';
      });

      if (projections.some((projection) => projection.length === 0)) {
        return ResponseWrapper.error(
          STATUS_CODE.BAD_REQUEST,
          'Invalid JSON property key',
        );
      }

      const rows: Array<Record<string, string | null>> =
        await this.physicalAssetPropertyRepository.manager.query(
          `SELECT ${projections.join(', ')} FROM [isa95].[physical_asset_property] p WHERE p.id = @0`,
          [id],
        );

      if (rows.length === 0) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Physical asset property with id ${id} not found`,
        );
      }

      const result = Object.fromEntries(
        Object.entries(rows[0]).filter(([, value]) => value !== null),
      ) as Record<string, unknown>;

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'JSON properties retrieved successfully',
        result,
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET PROPERTY JSON GET FAILED',
      );
    }
  }

  public async mergeJsonProperties(
    id: number,
    payload: PatchJsonPropertiesDto,
  ): Promise<WrappedResponse<PhysicalAssetPropertyResponseDto | undefined>> {
    try {
      const entries = Object.entries(payload.properties);

      if (entries.length === 0) {
        const result = await this.physicalAssetPropertyRepository.findOne({
          where: { id },
        });

        if (!result) {
          return ResponseWrapper.error(
            STATUS_CODE.NOT_FOUND,
            `Physical asset property with id ${id} not found`,
          );
        }

        return ResponseWrapper.success(
          STATUS_CODE.OK,
          'JSON properties merged successfully',
          PhysicalAssetPropertyCrudService.mapToResponseDto(result),
        );
      }

      const parameters: Array<unknown> = [];
      let expression = 'properties_json';

      for (const [key, value] of entries) {
        const path = this.buildJsonPath(key);
        if (!path) {
          return ResponseWrapper.error(
            STATUS_CODE.BAD_REQUEST,
            'Invalid JSON property key',
          );
        }

        const index = parameters.length;
        if (value !== null && typeof value === 'object') {
          parameters.push(JSON.stringify(value));
          expression = `JSON_MODIFY(${expression}, '${path}', JSON_QUERY(@${index}))`;
        } else {
          parameters.push(value);
          expression = `JSON_MODIFY(${expression}, '${path}', @${index})`;
        }
      }

      const idIndex = parameters.length;
      parameters.push(id);

      await this.physicalAssetPropertyRepository.manager.query(
        `UPDATE [isa95].[physical_asset_property] SET properties_json = ${expression} WHERE id = @${idIndex}`,
        parameters,
      );

      const updated = await this.physicalAssetPropertyRepository.findOne({
        where: { id },
      });

      if (!updated) {
        return ResponseWrapper.error(
          STATUS_CODE.INTERNAL_SERVER_ERROR,
          'Failed to retrieve updated property',
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'JSON properties merged successfully',
        PhysicalAssetPropertyCrudService.mapToResponseDto(updated),
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET PROPERTY JSON MERGE FAILED',
      );
    }
  }

  public async deleteJsonProperties(
    id: number,
    payload: DeleteJsonPropertiesDto,
  ): Promise<WrappedResponse<PhysicalAssetPropertyResponseDto | undefined>> {
    try {
      if (payload.keys.length === 0) {
        const result = await this.physicalAssetPropertyRepository.findOne({
          where: { id },
        });

        if (!result) {
          return ResponseWrapper.error(
            STATUS_CODE.NOT_FOUND,
            `Physical asset property with id ${id} not found`,
          );
        }

        return ResponseWrapper.success(
          STATUS_CODE.OK,
          'JSON properties deleted successfully',
          PhysicalAssetPropertyCrudService.mapToResponseDto(result),
        );
      }

      let expression = 'properties_json';
      for (const key of payload.keys) {
        const path = this.buildJsonPath(key);
        if (!path) {
          return ResponseWrapper.error(
            STATUS_CODE.BAD_REQUEST,
            'Invalid JSON property key',
          );
        }

        expression = `JSON_MODIFY(${expression}, '${path}', NULL)`;
      }

      await this.physicalAssetPropertyRepository.manager.query(
        `UPDATE [isa95].[physical_asset_property] SET properties_json = ${expression} WHERE id = @0`,
        [id],
      );

      const updated = await this.physicalAssetPropertyRepository.findOne({
        where: { id },
      });

      if (!updated) {
        return ResponseWrapper.error(
          STATUS_CODE.INTERNAL_SERVER_ERROR,
          'Failed to retrieve updated property',
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'JSON properties deleted successfully',
        PhysicalAssetPropertyCrudService.mapToResponseDto(updated),
      );
    } catch {
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'PHYSICAL ASSET PROPERTY JSON DELETE FAILED',
      );
    }
  }
}

