import {
  ResponseWrapper,
  STATUS_CODE,
  WrappedResponse,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AppLogger } from '@/common/logger/app-logger';
import { PhysicalAssetClassProperty } from '@/modules/isa9-physical-asset-model/physical-asset-class/physical-asset-class-property/physical-asset-class-property.entity';
import { PropertyDataType } from '@/modules/isa95-common/property-data-type/property-data-type.entity';
import { throwWrappedInternalError } from '@/modules/isa95-equipment-model/common/internal-error.util';
import { CreatePropertyDataTypeDto } from '@/modules/isa95-equipment-model/dtos/create-property-data-type.dto';
import { PropertyDataTypeResponseDto } from '@/modules/isa95-equipment-model/dtos/property-data-type-response.dto';
import { UpdatePropertyDataTypeDto } from '@/modules/isa95-equipment-model/dtos/update-property-data-type.dto';
import { EquipmentClassProperty } from '@/modules/isa95-equipment-model/equipment-class/equipment-class-property/equipment-class-property.entity';

@Injectable()
export class PropertyDataTypeCrudService {
  private static toResponseDto(
    propertyDataType: PropertyDataType,
  ): PropertyDataTypeResponseDto {
    return {
      code: propertyDataType.code,
      id: propertyDataType.id,
    };
  }

  private readonly logger = new AppLogger(PropertyDataTypeCrudService.name);

  public constructor(
    @InjectRepository(PropertyDataType)
    private readonly propertyDataTypeRepository: Repository<PropertyDataType>,
  ) {}

  public async create(
    payload: CreatePropertyDataTypeDto,
  ): Promise<WrappedResponse<PropertyDataTypeResponseDto | undefined>> {
    try {
      const existingType = await this.propertyDataTypeRepository.findOne({
        where: { code: payload.code },
      });

      if (existingType) {
        this.logger.warn(
          `Property data type with code ${payload.code} already exists`,
        );
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          'Property data type already exists',
        );
      }

      const propertyDataType = this.propertyDataTypeRepository.create(payload);
      const created =
        await this.propertyDataTypeRepository.save(propertyDataType);
      return ResponseWrapper.success(
        STATUS_CODE.CREATED,
        'Property data type created successfully',
        PropertyDataTypeCrudService.toResponseDto(created),
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        'Failed to create property data type',
        error,
      );
    }
  }

  public async findAll(): Promise<
    WrappedResponse<Array<PropertyDataTypeResponseDto> | undefined>
  > {
    try {
      const propertyDataTypes = await this.propertyDataTypeRepository.find({
        order: { id: 'ASC' },
      });
      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Property data types retrieved successfully',
        propertyDataTypes.map((propertyDataType) =>
          PropertyDataTypeCrudService.toResponseDto(propertyDataType),
        ),
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        'Failed to retrieve property data types',
        error,
      );
    }
  }

  public async findOne(
    id: number,
  ): Promise<WrappedResponse<PropertyDataTypeResponseDto | undefined>> {
    try {
      const propertyDataType = await this.propertyDataTypeRepository.findOne({
        where: { id },
      });

      if (!propertyDataType) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Property data type with id ${id} not found`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Property data type retrieved successfully',
        PropertyDataTypeCrudService.toResponseDto(propertyDataType),
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to retrieve property data type with id ${id}`,
        error,
      );
    }
  }

  public async update(
    id: number,
    payload: UpdatePropertyDataTypeDto,
  ): Promise<WrappedResponse<PropertyDataTypeResponseDto | undefined>> {
    try {
      const propertyDataType = await this.propertyDataTypeRepository.findOne({
        where: { id },
      });

      if (!propertyDataType) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Property data type with id ${id} not found`,
        );
      }

      if (payload.code !== undefined) {
        const existingType = await this.propertyDataTypeRepository.findOne({
          where: { code: payload.code },
        });

        if (existingType && existingType.id !== id) {
          this.logger.warn(
            `Property data type with code ${payload.code} already exists`,
          );
          return ResponseWrapper.error(
            STATUS_CODE.CONFLICT,
            'Property data type already exists',
          );
        }

        propertyDataType.code = payload.code;
      }

      const updated =
        await this.propertyDataTypeRepository.save(propertyDataType);
      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Property data type updated successfully',
        PropertyDataTypeCrudService.toResponseDto(updated),
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to update property data type with id ${id}`,
        error,
      );
    }
  }

  public async remove(id: number): Promise<WrappedResponse<undefined>> {
    try {
      const [equipmentUsageCount, physicalAssetUsageCount] = await Promise.all([
        this.propertyDataTypeRepository.manager
          .getRepository(EquipmentClassProperty)
          .count({ where: { propertyDataTypeId: id } }),
        this.propertyDataTypeRepository.manager
          .getRepository(PhysicalAssetClassProperty)
          .count({ where: { propertyDataTypeId: id } }),
      ]);

      if (equipmentUsageCount > 0 || physicalAssetUsageCount > 0) {
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          `Property data type with id ${id} cannot be deleted because class properties reference it`,
        );
      }

      const response = await this.propertyDataTypeRepository.delete({ id });

      if (!response.affected) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Property data type with id ${id} not found`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Property data type deleted successfully',
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to delete property data type with id ${id}`,
        error,
      );
    }
  }
}

