/**
 * Parses an optional string into an integer.
 * @param value Optional string input to parse.
 * @returns Parsed integer when valid; otherwise undefined.
 */
export function parseOptionalInteger(value?: string): number | undefined {
  const parsedValue =
    value === undefined ? undefined : Number.parseInt(value, 10);
  return Number.isNaN(parsedValue) ? undefined : parsedValue;
}

/**
 * Parses a string into an integer and falls back when parsing fails.
 * @param value Required string input to parse.
 * @param fallback Fallback number returned when parsing fails.
 * @returns Parsed integer when valid; otherwise the provided fallback.
 */
export function parseIntegerOrDefault(value: string, fallback: number): number {
  const parsedValue = Number.parseInt(value, 10);
  return Number.isNaN(parsedValue) ? fallback : parsedValue;
}

import { ResponseWrapper, STATUS_CODE } from '@mesx/common-lib';
import { InternalServerErrorException } from '@nestjs/common';

interface LoggerLike {
  error(message: string, stack?: string): void;
}

/**
 * Logs an internal error and throws a wrapped internal server exception.
 * @param logger Logger implementation used to write server-side error details.
 * @param context Operation context included in the log message.
 * @param error Original unknown error received from the failing operation.
 */
export function throwWrappedInternalError(
  logger: LoggerLike,
  context: string,
  error: unknown,
): never {
  const message = error instanceof Error ? error.message : String(error);
  const stack = error instanceof Error ? error.stack : undefined;
  logger.error(`${context}: ${message}`, stack);
  throw new InternalServerErrorException(
    ResponseWrapper.error(
      STATUS_CODE.INTERNAL_SERVER_ERROR,
      'Internal server error',
    ),
  );
}

