@Injectable()
export class EquipmentClassCrudService {
  private static readonly defaultDescriptionLanguageCode = 'EN';

  private static isUniqueConstraintViolation(error: unknown): boolean {
    const normalizedMessage = JSON.stringify(error).toLowerCase();

    return (
      /\b(2601|2627)\b/.test(normalizedMessage) ||
      normalizedMessage.includes('unique key constraint') ||
      normalizedMessage.includes('duplicate key') ||
      normalizedMessage.includes('uq_equipment_class_code')
    );
  }

  private static selectEquipmentClassDescription(
    descriptions: Array<EquipmentClassDescription> | undefined,
    language: string,
  ): { description: string | null; descriptionLanguageCode: string | null } {
    if (!descriptions || descriptions.length === 0) {
      return { description: null, descriptionLanguageCode: null };
    }

    const selected =
      descriptions.find(
        (description) => description.code?.trim() === language,
      ) ??
      descriptions.find(
        (description) =>
          description.code?.trim() ===
          EquipmentClassCrudService.defaultDescriptionLanguageCode,
      ) ??
      descriptions[0];

    return {
      description: selected?.description ?? null,
      descriptionLanguageCode: selected?.code?.trim() ?? null,
    };
  }

  private static mapToResponseDto(
    equipmentClass: EquipmentClass,
    language = 'EN',
  ): EquipmentClassResponseDto {
    const { description, descriptionLanguageCode } =
      EquipmentClassCrudService.selectEquipmentClassDescription(
        equipmentClass.descriptions,
        language,
      );

    return {
      code: equipmentClass.code,
      description,
      descriptionLanguageCode,
      equipmentClassPropertiesCount:
        equipmentClass.equipmentClassPropertiesCount,
      equipmentLevelId: null, // EquipmentClass doesn't have direct equipmentLevel
      id: equipmentClass.id,
      isCustom: equipmentClass.isCustom,
      parentEquipmentClassId: null, // Will be populated from inheritance if needed
    };
  }

  private static mapToRelationsResponseDto(
    equipmentClass: EquipmentClass,
    language = 'EN',
  ): EquipmentClassWithRelationsResponseDto {
    const baseDto = EquipmentClassCrudService.mapToResponseDto(
      equipmentClass,
      language,
    );

    return {
      ...baseDto,
      childEquipmentClasses:
        equipmentClass.childInheritances?.map((inh) =>
          EquipmentClassCrudService.mapToResponseDto(
            inh.childEquipmentClass,
            language,
          ),
        ) ?? [],
      equipmentClassProperties: equipmentClass.equipmentClassProperties,
      equipmentIds:
        equipmentClass.equipmentEquipmentClasses?.map(
          (eec) => eec.equipmentId,
        ) ?? [],
      parentEquipmentClasses:
        equipmentClass.parentInheritances?.map((inh) =>
          EquipmentClassCrudService.mapToResponseDto(
            inh.parentEquipmentClass,
            language,
          ),
        ) ?? [],
    };
  }

  private static selectEquipmentDescription(
    descriptions: Array<EquipmentDescriptionByLanguage> | undefined,
    language: string,
  ): EquipmentDescriptionByLanguage | undefined {
    if (!descriptions || descriptions.length === 0) {
      return undefined;
    }

    return (
      descriptions.find(
        (description) => description.code?.trim() === language,
      ) ??
      descriptions.find(
        (description) =>
          description.code?.trim() ===
          EquipmentClassCrudService.defaultDescriptionLanguageCode,
      ) ??
      descriptions[0]
    );
  }

  private static mapEquipmentForClass(
    equipment: Equipment,
    language: string,
  ): EquipmentClassRelatedEquipmentDto {
    const selectedDescription =
      EquipmentClassCrudService.selectEquipmentDescription(
        equipment.descriptions,
        language,
      );

    const properties = (equipment.equipmentProperties ?? [])
      .sort((left, right) => left.id - right.id)
      .map<EquipmentClassRelatedEquipmentPropertyDto>((property) => ({
        id: property.id,
        equipmentClassId: property.equipmentClassId,
        propertiesJson: property.propertiesJson ?? {},
      }));

    return {
      code: equipment.code?.trim() ?? '',
      description: selectedDescription?.description ?? null,
      descriptionLanguageCode: selectedDescription?.code?.trim() ?? null,
      equipmentLevelCode: equipment.equipmentLevel?.code ?? null,
      equipmentLevelId: equipment.equipmentLevelId,
      id: equipment.id,
      parentEquipmentId: equipment.parentEquipmentId ?? null,
      plant: equipment.plant,
      properties,
    };
  }

  private readonly logger = new AppLogger(EquipmentClassCrudService.name);

  public constructor(
    @InjectRepository(EquipmentClass)
    private readonly equipmentClassRepository: Repository<EquipmentClass>,
    @InjectRepository(EquipmentClassDescription)
    private readonly equipmentClassDescriptionRepository: Repository<EquipmentClassDescription>,
    @InjectRepository(EquipmentEquipmentClass)
    private readonly equipmentEquipmentClassRepository: Repository<EquipmentEquipmentClass>,
  ) {}

  private applyEquipmentClassUpdates(
    equipmentClass: EquipmentClass,
    payload: UpdateEquipmentClassDto,
  ): EquipmentClass {
    try {
      const updated = equipmentClass;
      if (payload.code !== undefined) {
        updated.code = payload.code;
      }
      return updated;
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to apply equipment class updates for ${equipmentClass.id}`,
        error,
      );
    }
  }

  private async upsertDescription(
    equipmentClassId: number,
    description: string,
    languageCode?: string,
    equipmentClassDescriptionRepository: Repository<EquipmentClassDescription> = this
      .equipmentClassDescriptionRepository,
  ): Promise<void> {
    const code = (languageCode ?? 'EN').toUpperCase();

    const existingDescription =
      await equipmentClassDescriptionRepository.findOne({
        where: {
          code,
          equipmentClassId,
        },
      });

    if (existingDescription) {
      existingDescription.description = description;
      await equipmentClassDescriptionRepository.save(existingDescription);
      return;
    }

    const equipmentClassDescription =
      equipmentClassDescriptionRepository.create({
        code,
        description,
        equipmentClassId,
      });

    await equipmentClassDescriptionRepository.save(equipmentClassDescription);
  }

  public async createWithDescription(
    payload: CreateEquipmentClassWithDescriptionDto,
  ): Promise<WrappedResponse<EquipmentClassResponseDto | undefined>> {
    try {
      const customCode = payload.className.trim();
      let savedEquipmentClassId: number | undefined;

      await this.equipmentClassRepository.manager.transaction(
        async (manager) => {
          const equipmentClassRepository =
            manager.getRepository(EquipmentClass);
          const equipmentClassDescriptionRepository = manager.getRepository(
            EquipmentClassDescription,
          );

          const existingEquipmentClass = await equipmentClassRepository.findOne(
            {
              where: { code: customCode },
            },
          );

          if (existingEquipmentClass) {
            throw new ConflictException(
              `Equipment class with code ${customCode} already exists`,
            );
          }

          const equipmentClass = equipmentClassRepository.create({
            code: customCode,
            isCustom: true,
          });

          const savedEquipmentClass =
            await equipmentClassRepository.save(equipmentClass);

          savedEquipmentClassId = savedEquipmentClass.id;

          await this.upsertDescription(
            savedEquipmentClass.id,
            payload.description,
            payload.descriptionLanguageCode,
            equipmentClassDescriptionRepository,
          );
        },
      );

      // Reload with description.
      const reloaded = await this.equipmentClassRepository.findOne({
        where: { id: savedEquipmentClassId },
        relations: ['descriptions'],
      });
      if (!reloaded) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Equipment class with id ${savedEquipmentClassId} not found`,
        );
      }
      const response = EquipmentClassCrudService.mapToResponseDto(
        reloaded,
        payload.descriptionLanguageCode ?? 'EN',
      );
      return ResponseWrapper.success(
        STATUS_CODE.CREATED,
        'Equipment class created successfully',
        response,
      );
    } catch (error) {
      if (error instanceof ConflictException) {
        throw error;
      }
      return throwWrappedInternalError(
        this.logger,
        'Failed to create equipment class with description',
        error,
      );
    }
  }

  public async findAll(): Promise<
    WrappedResponse<Array<EquipmentClassResponseDto> | undefined>
  > {
    try {
      const classes = await this.equipmentClassRepository.find({
        relations: ['descriptions'],
        order: { id: 'ASC' },
      });
      const data = classes.map((ec) =>
        EquipmentClassCrudService.mapToResponseDto(ec, 'EN'),
      );
      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Equipment classes retrieved successfully',
        data,
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        'Failed to retrieve equipment classes',
        error,
      );
    }
  }

  public async findEquipmentClasses(
    language?: string,
  ): Promise<WrappedResponse<Array<EquipmentClassResponseDto> | undefined>> {
    try {
      const lang = (language ?? 'EN').toUpperCase();

      const classes = await this.equipmentClassRepository
        .createQueryBuilder('ec')
        .leftJoinAndSelect('ec.descriptions', 'd', 'd.code = :lang', { lang })
        .loadRelationCountAndMap(
          'ec.equipmentClassPropertiesCount',
          'ec.equipmentClassProperties',
        )
        .orderBy('ec.id', 'ASC')
        .getMany();

      const data = classes.map((ec) =>
        EquipmentClassCrudService.mapToResponseDto(ec, lang),
      );
      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Equipment classes retrieved successfully',
        data,
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        'Failed to retrieve equipment classes',
        error,
      );
    }
  }

  public async findOne(
    id: number,
  ): Promise<WrappedResponse<EquipmentClassResponseDto | undefined>> {
    try {
      const equipmentClass = await this.equipmentClassRepository.findOne({
        where: { id },
        relations: ['descriptions'],
      });

      if (!equipmentClass) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Equipment class with id ${id} not found`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Equipment class retrieved successfully',
        EquipmentClassCrudService.mapToResponseDto(equipmentClass),
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to retrieve equipment class with id ${id}`,
        error,
      );
    }
  }

  public async findOneWithRelations(
    id: number,
  ): Promise<
    WrappedResponse<EquipmentClassWithRelationsResponseDto | undefined>
  > {
    try {
      const equipmentClass = await this.equipmentClassRepository.findOne({
        where: { id },
        relations: [
          'descriptions',
          'parentInheritances',
          'parentInheritances.parentEquipmentClass',
          'childInheritances',
          'childInheritances.childEquipmentClass',
          'equipmentClassProperties',
          'equipmentClassProperties.descriptions',
          'equipmentClassProperties.propertyDataType',
          'equipmentClassProperties.children',
          'equipmentEquipmentClasses',
          'equipmentEquipmentClasses.equipment',
        ],
      });

      if (!equipmentClass) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Equipment class with id ${id} not found`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Equipment class with relations retrieved successfully',
        EquipmentClassCrudService.mapToRelationsResponseDto(equipmentClass),
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to retrieve equipment class with relations for id ${id}`,
        error,
      );
    }
  }

  public async findRelatedEquipment(
    equipmentClassId: number,
    language?: string,
  ): Promise<
    WrappedResponse<Array<EquipmentClassRelatedEquipmentDto> | undefined>
  > {
    try {
      // Verify equipment class exists
      const equipmentClass = await this.equipmentClassRepository.findOne({
        where: { id: equipmentClassId },
      });

      if (!equipmentClass) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Equipment class with id ${equipmentClassId} not found`,
        );
      }

      const selectedLanguage = (
        language ?? EquipmentClassCrudService.defaultDescriptionLanguageCode
      )
        .trim()
        .toUpperCase();

      const links = await this.equipmentEquipmentClassRepository
        .createQueryBuilder('link')
        .leftJoinAndSelect('link.equipment', 'equipment')
        .leftJoinAndSelect('equipment.descriptions', 'description')
        .leftJoinAndSelect('equipment.equipmentLevel', 'equipmentLevel')
        .leftJoinAndSelect(
          'equipment.equipmentProperties',
          'equipmentProperty',
          'equipmentProperty.equipmentClassId = :equipmentClassId',
          { equipmentClassId },
        )
        .where('link.equipmentClassId = :equipmentClassId', {
          equipmentClassId,
        })
        .select([
          'link.id',
          'link.equipmentId',
          'equipment.id',
          'equipment.code',
          'equipment.plant',
          'equipment.parentEquipmentId',
          'equipment.equipmentLevelId',
          'equipmentLevel.id',
          'equipmentLevel.code',
          'description.id',
          'description.code',
          'description.description',
          'equipmentProperty.id',
          'equipmentProperty.equipmentClassId',
          'equipmentProperty.propertiesJson',
        ])
        .orderBy('link.equipmentId', 'ASC')
        .getMany();

      const relatedEquipment = links
        .map((link) => link.equipment)
        .filter(Boolean)
        .map((equipment) =>
          EquipmentClassCrudService.mapEquipmentForClass(
            equipment,
            selectedLanguage,
          ),
        );

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Related equipment retrieved successfully',
        relatedEquipment,
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to retrieve related equipment for class id ${equipmentClassId}`,
        error,
      );
    }
  }

  public async update(
    id: number,
    payload: UpdateEquipmentClassDto,
  ): Promise<WrappedResponse<EquipmentClassResponseDto | undefined>> {
    try {
      const existingEquipmentClass =
        await this.equipmentClassRepository.findOne({
          where: { id },
        });

      if (!existingEquipmentClass) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Equipment class with id ${id} not found`,
        );
      }

      await this.equipmentClassRepository.manager.transaction(
        async (manager) => {
          const equipmentClassRepository =
            manager.getRepository(EquipmentClass);
          const equipmentClassDescriptionRepository = manager.getRepository(
            EquipmentClassDescription,
          );

          const appliedUpdates = this.applyEquipmentClassUpdates(
            existingEquipmentClass,
            payload,
          );

          await equipmentClassRepository.save(appliedUpdates);

          if (payload.description !== undefined) {
            await this.upsertDescription(
              id,
              payload.description,
              payload.descriptionLanguageCode,
              equipmentClassDescriptionRepository,
            );
          }
        },
      );

      // Reload with updated description.
      const reloaded = await this.equipmentClassRepository.findOne({
        where: { id },
        relations: ['descriptions'],
      });
      if (!reloaded) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Equipment class with id ${id} not found`,
        );
      }
      const response = EquipmentClassCrudService.mapToResponseDto(
        reloaded,
        payload.descriptionLanguageCode ?? 'EN',
      );
      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Equipment class updated successfully',
        response,
      );
    } catch (error) {
      if (
        error instanceof ConflictException ||
        EquipmentClassCrudService.isUniqueConstraintViolation(error)
      ) {
        const requestedCode = payload.code?.trim();
        this.logger.warn(
          `Update conflict for equipment class ${id}: ${
            error instanceof Error ? error.message : String(error)
          }`,
        );
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          requestedCode
            ? `The code "${requestedCode}" is already used by another equipment class.`
            : 'Equipment class code already exists',
        );
      }
      return throwWrappedInternalError(
        this.logger,
        `Failed to update equipment class ${id}`,
        error,
      );
    }
  }

  public async removeEquipmentClass(
    id: number,
  ): Promise<WrappedResponse<undefined>> {
    try {
      const equipmentClass = await this.equipmentClassRepository.findOne({
        where: { id },
      });
      if (!equipmentClass) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Equipment class with id ${id} not found`,
        );
      }

      await this.equipmentClassRepository.manager.transaction(
        async (manager) => {
          const classDescriptionRepository = manager.getRepository(
            EquipmentClassDescription,
          );
          const inheritanceRepository = manager.getRepository(
            EquipmentClassInheritance,
          );
          const classPropertyRepository = manager.getRepository(
            EquipmentClassProperty,
          );
          const propertyDescriptionRepository = manager.getRepository(
            EquipmentPropertyDescription,
          );
          const equipmentClassLinkRepository = manager.getRepository(
            EquipmentEquipmentClass,
          );
          const equipmentPropertyRepository =
            manager.getRepository(EquipmentProperty);
          const equipmentClassRepository =
            manager.getRepository(EquipmentClass);

          await propertyDescriptionRepository
            .createQueryBuilder()
            .delete()
            .from(EquipmentPropertyDescription)
            .where(
              'equipment_class_property_id IN (SELECT id FROM isa95.equipment_class_property WHERE equipment_class_id = :id)',
              { id },
            )
            .execute();
          await classPropertyRepository.delete({ equipmentClassId: id });

          await equipmentPropertyRepository.delete({ equipmentClassId: id });
          await equipmentClassLinkRepository.delete({ equipmentClassId: id });
          await inheritanceRepository
            .createQueryBuilder()
            .delete()
            .from(EquipmentClassInheritance)
            .where('parent_equipment_class_id = :id', { id })
            .orWhere('child_equipment_class_id = :id', { id })
            .execute();
          await classDescriptionRepository.delete({ equipmentClassId: id });
          await equipmentClassRepository.delete({ id });
        },
      );
      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Equipment class deleted successfully',
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to cascade delete equipment class ${id}`,
        error,
      );
    }
  }
}

import {
  ResponseWrapper,
  STATUS_CODE,
  WrappedResponse,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { EquipmentClassDescription } from './equipment-class-description.entity';
import { AppLogger } from '@/common/logger/app-logger';
import { throwWrappedInternalError } from '@/modules/isa95-equipment-model/common/internal-error.util';
import { CreateEquipmentClassDescriptionDto } from '@/modules/isa95-equipment-model/dtos/create-equipment-class-description.dto';
import { UpdateEquipmentClassDescriptionDto } from '@/modules/isa95-equipment-model/dtos/update-equipment-class-description.dto';

@Injectable()
export class EquipmentClassDescriptionCrudService {
  private static isUniqueConstraintViolation(error: unknown): boolean {
    const message = error instanceof Error ? error.message : String(error);
    return /\b(2601|2627)\b/.test(message);
  }

  private readonly logger = new AppLogger(
    EquipmentClassDescriptionCrudService.name,
  );

  public constructor(
    @InjectRepository(EquipmentClassDescription)
    private readonly equipmentClassDescriptionRepository: Repository<EquipmentClassDescription>,
  ) {}

  public async create(
    payload: CreateEquipmentClassDescriptionDto,
  ): Promise<WrappedResponse<EquipmentClassDescription | undefined>> {
    try {
      const existing = await this.equipmentClassDescriptionRepository.findOne({
        where: {
          equipmentClassId: payload.equipmentClassId,
          code: payload.code,
        },
      });

      if (existing) {
        this.logger.warn(
          `Equipment class description already exists for class ${payload.equipmentClassId} and language ${payload.code}`,
        );
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          'Equipment class description already exists',
        );
      }

      const description =
        this.equipmentClassDescriptionRepository.create(payload);
      try {
        const created =
          await this.equipmentClassDescriptionRepository.save(description);
        return ResponseWrapper.success(
          STATUS_CODE.CREATED,
          'Equipment class description created successfully',
          created,
        );
      } catch (error) {
        if (
          !EquipmentClassDescriptionCrudService.isUniqueConstraintViolation(
            error,
          )
        ) {
          return throwWrappedInternalError(
            this.logger,
            'Failed to create equipment class description',
            error,
          );
        }

        const existingAfterConflict =
          await this.equipmentClassDescriptionRepository.findOne({
            where: {
              equipmentClassId: payload.equipmentClassId,
              code: payload.code,
            },
            order: { id: 'ASC' },
          });
        if (existingAfterConflict) {
          return ResponseWrapper.error(
            STATUS_CODE.CONFLICT,
            'Equipment class description already exists',
          );
        }

        return ResponseWrapper.error(
          STATUS_CODE.INTERNAL_SERVER_ERROR,
          'Internal server error',
        );
      }
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        'Failed to create equipment class description',
        error,
      );
    }
  }

  public async findAll(): Promise<
    WrappedResponse<Array<EquipmentClassDescription> | undefined>
  > {
    try {
      const descriptions = await this.equipmentClassDescriptionRepository.find({
        order: { id: 'ASC' },
      });
      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Equipment class descriptions retrieved successfully',
        descriptions,
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        'Failed to retrieve equipment class descriptions',
        error,
      );
    }
  }

  public async findOne(
    id: number,
  ): Promise<WrappedResponse<EquipmentClassDescription | undefined>> {
    try {
      const description =
        await this.equipmentClassDescriptionRepository.findOne({
          where: { id },
        });

      if (!description) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Equipment class description with id ${id} not found`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Equipment class description retrieved successfully',
        description,
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to retrieve equipment class description with id ${id}`,
        error,
      );
    }
  }

  public async update(
    id: number,
    payload: UpdateEquipmentClassDescriptionDto,
  ): Promise<WrappedResponse<EquipmentClassDescription | undefined>> {
    try {
      const findOneResponse = await this.findOne(id);
      if (!findOneResponse.success || !findOneResponse.data) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Equipment class description with id ${id} not found`,
        );
      }

      const description = findOneResponse.data;

      if (payload.code !== undefined) {
        description.code = payload.code;
      }

      if (payload.description !== undefined) {
        description.description = payload.description;
      }

      if (payload.equipmentClassId !== undefined) {
        description.equipmentClassId = payload.equipmentClassId;
      }

      try {
        const updated =
          await this.equipmentClassDescriptionRepository.save(description);
        return ResponseWrapper.success(
          STATUS_CODE.OK,
          'Equipment class description updated successfully',
          updated,
        );
      } catch (error) {
        if (
          !EquipmentClassDescriptionCrudService.isUniqueConstraintViolation(
            error,
          )
        ) {
          return throwWrappedInternalError(
            this.logger,
            `Failed to update equipment class description with id ${id}`,
            error,
          );
        }

        this.logger.warn(
          `Equipment class description conflict while updating id ${id}`,
        );
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          'Equipment class description already exists',
        );
      }
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to update equipment class description with id ${id}`,
        error,
      );
    }
  }

  public async remove(id: number): Promise<WrappedResponse<undefined>> {
    try {
      const response = await this.equipmentClassDescriptionRepository.delete({
        id,
      });

      if (!response.affected) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Equipment class description with id ${id} not found`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Equipment class description deleted successfully',
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to delete equipment class description with id ${id}`,
        error,
      );
    }
  }
}

