import {
  ResponseWrapper,
  STATUS_CODE,
  WrappedResponse,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { EquipmentClassInheritance } from './equipment-class-inheritance.entity';
import { AppLogger } from '@/common/logger/app-logger';
import { throwWrappedInternalError } from '@/modules/isa95-equipment-model/common/internal-error.util';
import { CreateEquipmentClassInheritanceDto } from '@/modules/isa95-equipment-model/dtos/create-equipment-class-inheritance.dto';

@Injectable()
export class EquipmentClassInheritanceCrudService {
  private static isUniqueConstraintViolation(error: unknown): boolean {
    const message = error instanceof Error ? error.message : String(error);
    return /\b(2601|2627)\b/.test(message);
  }

  private readonly logger = new AppLogger(
    EquipmentClassInheritanceCrudService.name,
  );

  public constructor(
    @InjectRepository(EquipmentClassInheritance)
    private readonly equipmentClassInheritanceRepository: Repository<EquipmentClassInheritance>,
  ) {}

  public async create(
    payload: CreateEquipmentClassInheritanceDto,
  ): Promise<WrappedResponse<EquipmentClassInheritance | undefined>> {
    try {
      if (payload.parentEquipmentClassId === payload.childEquipmentClassId) {
        this.logger.warn(
          `Cannot create self inheritance link for equipment class ${payload.parentEquipmentClassId}`,
        );
        return ResponseWrapper.error(
          STATUS_CODE.BAD_REQUEST,
          'Parent and child equipment class cannot be the same',
        );
      }

      const existing = await this.equipmentClassInheritanceRepository.findOne({
        where: {
          parentEquipmentClassId: payload.parentEquipmentClassId,
          childEquipmentClassId: payload.childEquipmentClassId,
        },
      });

      if (existing) {
        this.logger.warn(
          `Inheritance link between parent ${payload.parentEquipmentClassId} and child ${payload.childEquipmentClassId} already exists`,
        );
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          'Inheritance link already exists',
        );
      }

      const reverseLink =
        await this.equipmentClassInheritanceRepository.findOne({
          where: {
            parentEquipmentClassId: payload.childEquipmentClassId,
            childEquipmentClassId: payload.parentEquipmentClassId,
          },
        });

      if (reverseLink) {
        this.logger.warn(
          `Cannot create inheritance link ${payload.parentEquipmentClassId} -> ${payload.childEquipmentClassId} because reverse link already exists`,
        );
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          'Reverse inheritance link already exists',
        );
      }

      const link = this.equipmentClassInheritanceRepository.create(payload);
      try {
        const created =
          await this.equipmentClassInheritanceRepository.save(link);
        return ResponseWrapper.success(
          STATUS_CODE.CREATED,
          'Inheritance link created successfully',
          created,
        );
      } catch (error) {
        if (
          !EquipmentClassInheritanceCrudService.isUniqueConstraintViolation(
            error,
          )
        ) {
          return throwWrappedInternalError(
            this.logger,
            'Failed to create equipment class inheritance link',
            error,
          );
        }

        const existingAfterConflict =
          await this.equipmentClassInheritanceRepository.findOne({
            where: {
              parentEquipmentClassId: payload.parentEquipmentClassId,
              childEquipmentClassId: payload.childEquipmentClassId,
            },
          });
        if (existingAfterConflict) {
          return ResponseWrapper.error(
            STATUS_CODE.CONFLICT,
            'Inheritance link already exists',
          );
        }

        return ResponseWrapper.error(
          STATUS_CODE.INTERNAL_SERVER_ERROR,
          'Internal server error',
        );
      }
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        'Failed to create equipment class inheritance link',
        error,
      );
    }
  }

  public async findAll(): Promise<
    WrappedResponse<Array<EquipmentClassInheritance> | undefined>
  > {
    try {
      const inheritances = await this.equipmentClassInheritanceRepository.find({
        order: { id: 'ASC' },
        relations: ['parentEquipmentClass', 'childEquipmentClass'],
      });
      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Inheritance links retrieved successfully',
        inheritances,
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        'Failed to retrieve equipment class inheritance links',
        error,
      );
    }
  }

  public async findChildrenByParentId(
    parentId: number,
  ): Promise<Array<EquipmentClassInheritance>> {
    try {
      return await this.equipmentClassInheritanceRepository.find({
        where: { parentEquipmentClassId: parentId },
        order: { id: 'ASC' },
        relations: ['childEquipmentClass'],
      });
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to retrieve child inheritance links for parent ${parentId}`,
        error,
      );
    }
  }

  public async findParentsByChildId(
    childId: number,
  ): Promise<Array<EquipmentClassInheritance>> {
    try {
      return await this.equipmentClassInheritanceRepository.find({
        where: { childEquipmentClassId: childId },
        order: { id: 'ASC' },
        relations: ['parentEquipmentClass'],
      });
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to retrieve parent inheritance links for child ${childId}`,
        error,
      );
    }
  }

  public async findOne(id: number): Promise<EquipmentClassInheritance | null> {
    try {
      const link = await this.equipmentClassInheritanceRepository.findOne({
        where: { id },
        relations: ['parentEquipmentClass', 'childEquipmentClass'],
      });
      return link ?? null;
    } catch (error) {
      throwWrappedInternalError(
        this.logger,
        `Failed to retrieve equipment class inheritance link with id ${id}`,
        error,
      );
      return null;
    }
  }

  public async remove(id: number): Promise<boolean> {
    try {
      const response = await this.equipmentClassInheritanceRepository.delete({
        id,
      });
      return !!response.affected;
    } catch (error) {
      throwWrappedInternalError(
        this.logger,
        `Failed to delete equipment class inheritance link with id ${id}`,
        error,
      );
      return false;
    }
  }

  public async removeByParentAndChild(
    parentId: number,
    childId: number,
  ): Promise<WrappedResponse<undefined>> {
    try {
      const response = await this.equipmentClassInheritanceRepository.delete({
        parentEquipmentClassId: parentId,
        childEquipmentClassId: childId,
      });

      if (!response.affected) {
        this.logger.warn(
          `No inheritance link found between parent ${parentId} and child ${childId}`,
        );
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          'Inheritance link not found',
        );
      }
      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Inheritance link removed successfully',
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to delete equipment class inheritance link for parent ${parentId} and child ${childId}`,
        error,
      );
    }
  }
}

