  STATUS_CODE,
  WrappedResponse,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AppLogger } from '@/common/logger/app-logger';
import { CreateEquipmentClassPropertyDto } from '@/modules/isa95-equipment-model/dtos/create-equipment-class-property.dto';
import { EquipmentClassPropertyResponseDto } from '@/modules/isa95-equipment-model/dtos/equipment-class-property-response.dto';
import { EquipmentClassPropertySemanticsTransformerDto } from '@/modules/isa95-equipment-model/dtos/equipment-class-property-semantics-transformer.dto';
import { UpdateEquipmentClassPropertyDto } from '@/modules/isa95-equipment-model/dtos/update-equipment-class-property.dto';
import { EquipmentPropertyDescription } from '@/modules/isa95-equipment-model/equipment/equipment-property-description/equipment-property-description.entity';
import { EquipmentClassProperty } from '@/modules/isa95-equipment-model/equipment-class/equipment-class-property/equipment-class-property.entity';

interface LocalizedDescription {
  code: string;
  description: string;
}

interface PropertyIdPayload {
  id: number;
}
type EquipmentClassPropertyCreateResponse =
  | EquipmentClassPropertyResponseDto
  | undefined;
type EquipmentClassPropertyItemResponse =
  | EquipmentClassPropertyResponseDto
  | PropertyIdPayload
  | undefined;
type EquipmentClassPropertyListResponse =
  | Array<EquipmentClassPropertyResponseDto>
  | undefined;

@Injectable()
export class EquipmentClassPropertyCrudService {
  private static isUniqueConstraintViolation(error: unknown): boolean {
    const message = error instanceof Error ? error.message : String(error);
    return /\b(2601|2627)\b/.test(message);
  }

  private static extractPropertyDescription(
    property: EquipmentClassProperty,
    languageCode = 'EN',
  ): LocalizedDescription | null {
    const descriptions = property.descriptions ?? [];
    const lang = languageCode.toUpperCase();
    const requestedDescription = descriptions.find(
      (description) => description.code === lang,
    );
    const englishDescription = descriptions.find(
      (description) => description.code === 'EN',
    );
    const fallbackDescription = descriptions[0];

    return (
      requestedDescription ?? englishDescription ?? fallbackDescription ?? null
    );
  }

  private static toNullableString(value: unknown): string | null {
    if (typeof value === 'string') {
      return value;
    }

    if (typeof value === 'number' || typeof value === 'boolean') {
      return String(value);
    }

    return null;
  }

  private static mapToResponseDto(
    property: EquipmentClassProperty,
    languageCode = 'EN',
  ): EquipmentClassPropertyResponseDto {
    const selectedDescription =
      EquipmentClassPropertyCrudService.extractPropertyDescription(
        property,
        languageCode,
      );
    const semantics =
      EquipmentClassPropertySemanticsTransformerDto.toApi(
        property.propertySemanticsJson,
      ) ?? {};

    const allowedValues = Array.isArray(semantics.allowedValues)
      ? semantics.allowedValues
          .map((value) =>
            EquipmentClassPropertyCrudService.toNullableString(value),
          )
          .filter((value): value is string => value !== null)
      : null;

    return {
      allowedValues,
      cardinality: EquipmentClassPropertyCrudService.toNullableString(
        semantics.cardinality,
      ),
      classPropertyType: EquipmentClassPropertyCrudService.toNullableString(
        semantics.classPropertyType,
      ),
      code: property.code,
      defaultValue: EquipmentClassPropertyCrudService.toNullableString(
        semantics.defaultValue,
      ),
      description: selectedDescription?.description ?? null,
      descriptionLanguageCode: selectedDescription?.code ?? null,
      equipmentClassId: property.equipmentClassId,
      id: property.id,
      isCustom: property.isCustom,
      length: property.length ?? null,
      parentEquipmentClassPropertyId:
        property.parentEquipmentClassPropertyId ?? null,
      propertyDataTypeCode: property.propertyDataType?.code ?? null,
      propertyDataTypeId: property.propertyDataType?.id,
      scale: property.scale ?? null,
    };
  }

  private readonly logger = new AppLogger(
    EquipmentClassPropertyCrudService.name,
  );

  public constructor(
    @InjectRepository(EquipmentClassProperty)
    private readonly equipmentClassPropertyRepository: Repository<EquipmentClassProperty>,
    @InjectRepository(EquipmentPropertyDescription)
    private readonly equipmentPropertyDescriptionRepository: Repository<EquipmentPropertyDescription>,
  ) {}

  private async upsertDescription(
    equipmentClassPropertyId: number,
    description: string,
    languageCode = 'EN',
    equipmentPropertyDescriptionRepository: Repository<EquipmentPropertyDescription> = this
      .equipmentPropertyDescriptionRepository,
  ): Promise<void> {
    const code = languageCode.toUpperCase();
    const existing = await equipmentPropertyDescriptionRepository.findOne({
      where: {
        code,
        equipmentClassPropertyId,
      },
    });

    if (existing) {
      existing.description = description;
      await equipmentPropertyDescriptionRepository.save(existing);
      return;
    }

    const nextDescription = equipmentPropertyDescriptionRepository.create({
      code,
      description,
      equipmentClassPropertyId,
    });
    await equipmentPropertyDescriptionRepository.save(nextDescription);
  }

  private async findOneEntity(
    id: number,
  ): Promise<EquipmentClassProperty | undefined> {
    const equipmentClassProperty =
      await this.equipmentClassPropertyRepository.findOne({
        where: { id },
      });

    if (!equipmentClassProperty) {
      this.logger.warn(`Equipment class property with id ${id} not found`);
      return undefined;
    }

    return equipmentClassProperty;
  }

  public async create(
    payload: CreateEquipmentClassPropertyDto,
  ): Promise<WrappedResponse<EquipmentClassPropertyCreateResponse>> {
    try {
      const customCode = payload.code.trim();
      const existingEquipmentClassProperty =
        await this.equipmentClassPropertyRepository.findOne({
          where: {
            code: customCode,
            equipmentClassId: payload.equipmentClassId,
          },
        });

      if (existingEquipmentClassProperty) {
        this.logger.warn(
          `Equipment class property with code ${customCode} already exists`,
        );
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          'Equipment class property already exists',
        );
      }

      let createdPropertyId: number | undefined;

      await this.equipmentClassPropertyRepository.manager.transaction(
        async (manager) => {
          const equipmentClassPropertyRepository = manager.getRepository(
            EquipmentClassProperty,
          );
          const equipmentPropertyDescriptionRepository = manager.getRepository(
            EquipmentPropertyDescription,
          );

          const equipmentClassProperty =
            equipmentClassPropertyRepository.create({
              ...payload,
              code: customCode,
              isCustom: true,
              propertySemanticsJson:
                EquipmentClassPropertySemanticsTransformerDto.toDatabase(
                  payload.propertySemanticsJson,
                ),
            });

          const createdProperty = await equipmentClassPropertyRepository.save(
            equipmentClassProperty,
          );

          createdPropertyId = createdProperty.id;

          if (payload.description?.trim()) {
            await this.upsertDescription(
              createdProperty.id,
              payload.description.trim(),
              payload.descriptionCode ?? 'EN',
              equipmentPropertyDescriptionRepository,
            );
          }
        },
      );
      if (!createdPropertyId) {
        return ResponseWrapper.error(
          STATUS_CODE.INTERNAL_SERVER_ERROR,
          'EQUIPMENT CLASS PROPERTY CREATE FAILED',
        );
      }

      const createdEntity = await this.equipmentClassPropertyRepository.findOne(
        {
          relations: {
            descriptions: true,
            propertyDataType: true,
          },
          where: { id: createdPropertyId },
        },
      );

      if (!createdEntity) {
        return ResponseWrapper.error(
          STATUS_CODE.INTERNAL_SERVER_ERROR,
          'EQUIPMENT CLASS PROPERTY CREATE FAILED',
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.CREATED,
        'Equipment class property created successfully',
        EquipmentClassPropertyCrudService.mapToResponseDto(
          createdEntity,
          payload.descriptionCode ?? 'EN',
        ),
      );
    } catch (error) {
      if (
        EquipmentClassPropertyCrudService.isUniqueConstraintViolation(error)
      ) {
        this.logger.warn(
          `Equipment class property with code ${payload.code.trim()} already exists`,
        );
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          'Equipment class property already exists',
        );
      }
      this.logger.error(
        `Failed to create equipment class property: ${error instanceof Error ? error.message : String(error)}`,
      );
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'EQUIPMENT CLASS PROPERTY CREATE FAILED',
      );
    }
  }

  public async findAll(): Promise<
    WrappedResponse<EquipmentClassPropertyListResponse>
  > {
    try {
      const properties = await this.equipmentClassPropertyRepository.find({
        relations: {
          descriptions: true,
          propertyDataType: true,
        },
        order: { id: 'ASC' },
      });

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Equipment class properties retrieved successfully',
        properties.map((property) =>
          EquipmentClassPropertyCrudService.mapToResponseDto(property),
        ),
      );
    } catch (error) {
      this.logger.error(
        `Failed to retrieve equipment class properties: ${error instanceof Error ? error.message : String(error)}`,
      );
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'EQUIPMENT CLASS PROPERTY RETRIEVE FAILED',
      );
    }
  }

  public async findByEquipmentClassId(
    equipmentClassId: number,
    language = 'EN',
  ): Promise<WrappedResponse<EquipmentClassPropertyListResponse>> {
    try {
      const properties = await this.equipmentClassPropertyRepository.find({
        relations: {
          descriptions: true,
          propertyDataType: true,
        },
        where: { equipmentClassId },
        order: { id: 'ASC' },
      });

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Equipment class properties retrieved successfully',
        properties.map((property) =>
          EquipmentClassPropertyCrudService.mapToResponseDto(
            property,
            language,
          ),
        ),
      );
    } catch (error) {
      this.logger.error(
        `Failed to retrieve equipment class properties for class ${equipmentClassId}: ${error instanceof Error ? error.message : String(error)}`,
      );
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'EQUIPMENT CLASS PROPERTY RETRIEVE FAILED',
      );
    }
  }

  public async findOne(
    id: number,
  ): Promise<WrappedResponse<EquipmentClassPropertyItemResponse>> {
    try {
      const equipmentClassProperty =
        await this.equipmentClassPropertyRepository.findOne({
          relations: {
            descriptions: true,
            propertyDataType: true,
          },
          where: { id },
        });

      if (!equipmentClassProperty) {
        this.logger.warn(`Equipment class property with id ${id} not found`);
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Equipment class property with id ${id} not found`,
          { id },
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Equipment class property retrieved successfully',
        EquipmentClassPropertyCrudService.mapToResponseDto(
          equipmentClassProperty,
        ),
      );
    } catch (error) {
      this.logger.error(
        `Failed to retrieve equipment class property with id ${id}: ${error instanceof Error ? error.message : String(error)}`,
      );
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'EQUIPMENT CLASS PROPERTY RETRIEVE FAILED',
      );
    }
  }

  public async update(
    id: number,
    payload: UpdateEquipmentClassPropertyDto,
  ): Promise<WrappedResponse<EquipmentClassPropertyItemResponse>> {
    let exists = true;

    try {
      await this.equipmentClassPropertyRepository.manager.transaction(
        async (manager) => {
          const equipmentClassPropertyRepository = manager.getRepository(
            EquipmentClassProperty,
          );
          const equipmentPropertyDescriptionRepository = manager.getRepository(
            EquipmentPropertyDescription,
          );

          const equipmentClassProperty =
            await equipmentClassPropertyRepository.findOne({
              where: { id },
            });

          if (!equipmentClassProperty) {
            exists = false;
            return;
          }

          if (payload.code !== undefined) {
            equipmentClassProperty.code = payload.code;
          }

          if (payload.propertySemanticsJson !== undefined) {
            equipmentClassProperty.propertySemanticsJson =
              EquipmentClassPropertySemanticsTransformerDto.toDatabase(
                payload.propertySemanticsJson,
              ) ?? payload.propertySemanticsJson;
          }

          if (payload.description?.trim()) {
            await this.upsertDescription(
              equipmentClassProperty.id,
              payload.description.trim(),
              payload.descriptionCode ?? 'EN',
              equipmentPropertyDescriptionRepository,
            );
          }

          if (payload.propertyDataTypeId !== undefined) {
            equipmentClassProperty.propertyDataTypeId =
              payload.propertyDataTypeId;
          }

          if (payload.equipmentClassId !== undefined) {
            equipmentClassProperty.equipmentClassId = payload.equipmentClassId;
          }

          if (payload.parentEquipmentClassPropertyId !== undefined) {
            equipmentClassProperty.parentEquipmentClassPropertyId =
              payload.parentEquipmentClassPropertyId;
          }

          if (payload.length !== undefined) {
            equipmentClassProperty.length = payload.length;
          }

          if (payload.scale !== undefined) {
            equipmentClassProperty.scale = payload.scale;
          }

          await equipmentClassPropertyRepository.save(equipmentClassProperty);
        },
      );
    } catch (error) {
      if (
        EquipmentClassPropertyCrudService.isUniqueConstraintViolation(error)
      ) {
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          `Equipment class property with id ${id} already exists`,
          { id },
        );
      }
      this.logger.error(
        `Failed to update equipment class property with id ${id}: ${error instanceof Error ? error.message : String(error)}`,
      );
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'EQUIPMENT CLASS PROPERTY UPDATE FAILED',
      );
    }

    if (!exists) {
      return ResponseWrapper.error(
        STATUS_CODE.NOT_FOUND,
        `Equipment class property with id ${id} not found`,
        { id },
      );
    }

    return this.findOne(id);
  }

  public async remove(
    id: number,
  ): Promise<WrappedResponse<null | PropertyIdPayload | undefined>> {
    try {
      const response =
        await this.equipmentClassPropertyRepository.manager.transaction(
          async (manager) => {
            await manager.getRepository(EquipmentPropertyDescription).delete({
              equipmentClassPropertyId: id,
            });

            await manager
              .getRepository(EquipmentClassProperty)
              .createQueryBuilder()
              .update(EquipmentClassProperty)
              .set({ parentEquipmentClassPropertyId: () => 'NULL' })
              .where('parentEquipmentClassPropertyId = :id', { id })
              .execute();

            return manager.getRepository(EquipmentClassProperty).delete({ id });
          },
        );

      if (!response.affected) {
        this.logger.warn(`Equipment class property with id ${id} not found`);
        return ResponseWrapper.error<null | PropertyIdPayload>(
          STATUS_CODE.NOT_FOUND,
          `Equipment class property with id ${id} not found`,
          { id },
        );
      }

      return ResponseWrapper.success<null | PropertyIdPayload>(
        STATUS_CODE.OK,
        'Equipment class property deleted successfully',
        null,
      );
    } catch (error) {
      this.logger.error(
        `Failed to delete equipment class property with id ${id}: ${error instanceof Error ? error.message : String(error)}`,
      );
      return ResponseWrapper.error<null | PropertyIdPayload>(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'EQUIPMENT CLASS PROPERTY DELETE FAILED',
        null,
      );
    }
  }
}

