@Entity({
  name: 'equipment_class_property',
  schema: 'isa95',
  synchronize: false,
})
@Unique('uq_equipment_class_property_code_equipment_class_id', [
  'code',
  'equipmentClassId',
])
export class EquipmentClassProperty extends TimeStamp {
  @PrimaryGeneratedColumn({ name: 'id' })
  public id: number;

  @Column({
    length: 255,
    name: 'code',
    nullable: false,
  })
  public code: string;

  @Column({
    length: 'MAX',
    name: 'property_semantics_json',
    nullable: false,
    transformer: {
      to: (value: Record<string, unknown>) => {
        return JSON.stringify(value);
      },
      from: (value: string) => {
        if (typeof value !== 'string') {
          return value;
        }

        return JSON.parse(value);
      },
    },
    type: 'nvarchar',
  })
  public propertySemanticsJson: Record<string, unknown>;

  @Column({ default: false, name: 'is_custom', nullable: false })
  public isCustom: boolean;

  @Column({ name: 'property_data_type_id', nullable: false })
  public propertyDataTypeId: number;

  @Column({ name: 'equipment_class_id', nullable: false })
  public equipmentClassId: number;

  @Column({ name: 'parent_equipment_class_property_id', nullable: true })
  public parentEquipmentClassPropertyId: number;

  @Column({ name: 'length', type: 'int', nullable: true })
  public length: number;

  @Column({ name: 'scale', type: 'int', nullable: true })
  public scale: number;

  @ManyToOne(
    () => PropertyDataType,
    (propertyDataType) => propertyDataType.equipmentClassProperties,
  )
  @JoinColumn({
    name: 'property_data_type_id',
    foreignKeyConstraintName: 'fk_equipment_class_property_property_data_type',
  })
  public propertyDataType: PropertyDataType;

  @ManyToOne(
    () => EquipmentClass,
    (equipmentClass) => equipmentClass.equipmentClassProperties,
  )
  @JoinColumn({
    name: 'equipment_class_id',
    foreignKeyConstraintName: 'fk_equipment_class_property_equipment_class',
  })
  public equipmentClass: EquipmentClass;

  @ManyToOne(
    () => EquipmentClassProperty,
    (equipmentClassProperty) => equipmentClassProperty.children,
  )
  @JoinColumn({
    name: 'parent_equipment_class_property_id',
    foreignKeyConstraintName:
      'fk_equipment_class_property_equipment_class_property',
  })
  public parentEquipmentClassProperty: EquipmentClassProperty;

  @OneToMany(
    () => EquipmentClassProperty,
    (equipmentClassProperty) =>
      equipmentClassProperty.parentEquipmentClassProperty,
  )
  public children: Array<EquipmentClassProperty>;

  @OneToMany(
    () => EquipmentPropertyDescription,
    (equipmentPropertyDescription) =>
      equipmentPropertyDescription.equipmentClassProperty,
  )
  public descriptions: Array<EquipmentPropertyDescription>;
}

