    private readonly equipmentEquipmentClassRepository: Repository<EquipmentEquipmentClass>,
  ) {}

  private async resolveParentLevelId(
    equipmentLevelId: number,
  ): Promise<number | undefined> {
    const level = await this.equipmentLevelRepository.findOne({
      where: { id: equipmentLevelId },
    });

    return level?.parentEquipmentLevelId ?? undefined;
  }

  private async validateCreateWithDetailsPayload(
    payload: CreateEquipmentWithDetailsDto,
  ): Promise<WrappedResponse<EquipmentCreateWithDetailsResponse> | undefined> {
    const equipmentLevel = await this.equipmentLevelRepository.findOne({
      where: { id: payload.equipmentLevelId },
    });
    if (!equipmentLevel) {
      return ResponseWrapper.error(
        STATUS_CODE.BAD_REQUEST,
        `Equipment level with id ${payload.equipmentLevelId} does not exist`,
      );
    }

    const isSiteLevel =
      equipmentLevel.code.trim().toLowerCase() ===
      EquipmentCrudService.siteEquipmentLevelCode;
    if (isSiteLevel) {
      const siteCode = Number(payload.code.trim());

      if (Number.isNaN(siteCode)) {
        return ResponseWrapper.error(
          STATUS_CODE.BAD_REQUEST,
          'Site equipment code must be a number',
        );
      }

      if (siteCode < 1000 || siteCode > 9999) {
        return ResponseWrapper.error(
          STATUS_CODE.BAD_REQUEST,
          'Site equipment code must be between 1000 and 9999',
        );
      }

      const existingSite = await this.equipmentRepository.findOne({
        where: {
          plant: Number(payload.code.trim()),
        },
      });
      if (existingSite) {
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          'Equipment already exists',
        );
      }
      return undefined;
    }

    // Non-site: plant is required
    if (payload.plant === undefined) {
      return ResponseWrapper.error(
        STATUS_CODE.BAD_REQUEST,
        'Plant is required for non-site equipment levels',
      );
    }

    // Duplicate: same code at the same level within the same plant
    const existingAtLevel = await this.equipmentRepository.findOne({
      where: {
        plant: payload.plant,
        code: payload.code.trim(),
        equipmentLevelId: payload.equipmentLevelId,
      },
    });

    if (existingAtLevel) {
      return ResponseWrapper.error(
        STATUS_CODE.CONFLICT,
        `An equipment with code "${payload.code}" already exists at level "${equipmentLevel.code}" in plant ${payload.plant}`,
      );
    }

    // Parent equipment must exist when provided
    if (payload.parentEquipmentId !== undefined) {
      const parentExists = await this.equipmentRepository.findOne({
        where: { id: payload.parentEquipmentId },
      });

      if (!parentExists) {
        return ResponseWrapper.error(
          STATUS_CODE.BAD_REQUEST,
          `Parent equipment with id ${payload.parentEquipmentId} does not exist`,
        );
      }
    }

    return undefined;
  }

  private async upsertDefaultDescription(
    equipmentId: number,
    plant: number,
    description: string,
    equipmentDescriptionRepository: Repository<EquipmentDescriptionByLanguage> = this
      .equipmentDescriptionRepository,
  ): Promise<void> {
    const existingDescription = await equipmentDescriptionRepository.findOne({
      where: {
        code: EquipmentCrudService.defaultDescriptionLanguageCode,
        equipmentId,
      },
    });

    if (existingDescription) {
      existingDescription.description = description;
      existingDescription.plant = plant;
      await equipmentDescriptionRepository.save(existingDescription);
      return;
    }

    const equipmentDescription = equipmentDescriptionRepository.create({
      code: EquipmentCrudService.defaultDescriptionLanguageCode,
      description,
      equipmentId,
      plant,
    });
    await equipmentDescriptionRepository.save(equipmentDescription);
  }

  public async create(
    payload: CreateEquipmentDto,
  ): Promise<WrappedResponse<EquipmentCreateResponse>> {
    try {
      const existingEquipment = await this.equipmentRepository.findOne({
        where: {
          plant: payload.plant,
          code: payload.code,
          equipmentLevelId: payload.equipmentLevelId,
        },
      });

      if (existingEquipment) {
        this.logger.warn(
          `Equipment with plant ${payload.plant}, code ${payload.code}, and equipmentLevelId ${payload.equipmentLevelId} already exists`,
        );
        return ResponseWrapper.error<EquipmentCreateResponse>(
          STATUS_CODE.CONFLICT,
          'Equipment already exists',
          null,
        );
      }

      const { description, ...equipmentPayload } = payload;
      const equipment = this.equipmentRepository.create(equipmentPayload);
      let savedEquipment: Equipment;
      try {
        savedEquipment = await this.equipmentRepository.save(equipment);
      } catch (error) {
        if (!isUniqueConstraintViolation(error)) {
          throwWrappedInternalError(
            this.logger,
            'Failed to create equipment',
            error,
          );
        }

        this.logger.warn(
          `Equipment with plant ${payload.plant}, code ${payload.code}, and equipmentLevelId ${payload.equipmentLevelId} already exists`,
        );
        return ResponseWrapper.error<EquipmentCreateResponse>(
          STATUS_CODE.CONFLICT,
          'Equipment already exists',
          null,
        );
      }

      await this.upsertDefaultDescription(
        savedEquipment.id,
        savedEquipment.plant,
        description,
      );

      const createdResponse = await this.findOneWithRelations(
        savedEquipment.id,
      );
      if (
        !createdResponse.success ||
        !createdResponse.data ||
        !('code' in createdResponse.data)
      ) {
        return ResponseWrapper.error<EquipmentCreateResponse>(
          STATUS_CODE.INTERNAL_SERVER_ERROR,
          'EQUIPMENT RETRIEVE FAILED',
          null,
        );
      }

      return ResponseWrapper.success<EquipmentCreateResponse>(
        STATUS_CODE.OK,
        'Equipment with relations retrieved successfully',
        createdResponse.data,
      );
    } catch (error) {
      if (isUniqueConstraintViolation(error)) {
        return ResponseWrapper.error<EquipmentCreateResponse>(
          STATUS_CODE.CONFLICT,
          'Equipment already exists',
          null,
        );
      }
      if (error instanceof ConflictException) {
        return ResponseWrapper.error<EquipmentCreateResponse>(
          STATUS_CODE.CONFLICT,
          error.message,
          null,
        );
      }
      this.logger.error(
        `Failed to create equipment: ${error instanceof Error ? error.message : String(error)}`,
      );
      return ResponseWrapper.error<EquipmentCreateResponse>(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'EQUIPMENT CREATE FAILED',
        null,
      );
    }
  }

