    } catch (error) {
      this.logger.error(
        `Failed to retrieve equipment with id ${id}: ${error instanceof Error ? error.message : String(error)}`,
      );
      return ResponseWrapper.error<EquipmentItemResponse>(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
