  public async findParentOptions(
    plant: number,
    equipmentLevelId: number,
  ): Promise<WrappedResponse<EquipmentListResponse>> {
    try {
      const parentLevelId = await this.resolveParentLevelId(equipmentLevelId);
      if (parentLevelId === undefined) {
        return ResponseWrapper.success<EquipmentListResponse>(
          STATUS_CODE.OK,
          'Parent options retrieved successfully',
          [],
        );
      }

      const parentOptions = await this.equipmentRepository.find({
        where: {
          plant,
          equipmentLevelId: parentLevelId,
        },
        order: { id: 'ASC' },
        relations: ['descriptions', 'equipmentLevel'],
      });

      return ResponseWrapper.success<EquipmentListResponse>(
        STATUS_CODE.OK,
        'Parent options retrieved successfully',
        parentOptions,
      );
    } catch (error) {
      this.logger.error(
        `Failed to retrieve parent equipment options: ${error instanceof Error ? error.message : String(error)}`,
      );
      return ResponseWrapper.error<EquipmentListResponse>(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'EQUIPMENT RETRIEVE FAILED',
      );
    }
  }

  public async findOneWithRelations(
    id: number,
  ): Promise<WrappedResponse<EquipmentWithRelationsItemResponse>> {
    try {
      const equipment = await this.equipmentRepository.findOne({
        where: { id },
        relations: [
          'descriptions',
          'equipmentLevel',
          'parentEquipment',
          'parentEquipment.descriptions',
          'children',
          'children.descriptions',
          'equipmentEquipmentClasses',
          'equipmentEquipmentClasses.equipmentClass',
          'equipmentProperties',
          'equipmentProperties.equipmentClass',
          'equipmentProperties.equipmentClass.equipmentClassProperties',
        ],
      });

      if (!equipment) {
        this.logger.warn(`Equipment with id ${id} not found`);
        return ResponseWrapper.error<EquipmentWithRelationsItemResponse>(
          STATUS_CODE.NOT_FOUND,
          `Equipment with id ${id} not found`,
          { id },
        );
      }

      for (const property of equipment.equipmentProperties ?? []) {
        const json = property.propertiesJson ?? {};
        const semanticsByCode = new Map(
          (property.equipmentClass?.equipmentClassProperties ?? []).map(
            (cp) => [cp.code, cp],
          ),
        );

        const merged = Object.entries(json).map(([key, value]) => {
          const classProperty = semanticsByCode.get(key);
          return {
            ...(classProperty ?? { code: key, propertySemanticsJson: null }),
            value,
          };
        });

        Object.assign(property, { allProperties: merged });

        if (property.equipmentClass) {
          property.equipmentClass.equipmentClassProperties = [];
        }
      }

      return ResponseWrapper.success<EquipmentWithRelationsItemResponse>(
        STATUS_CODE.OK,
        'Equipment with relations retrieved successfully',
        equipment,
      );
    } catch (error) {
      this.logger.error(
        `Failed to retrieve equipment with relations for id ${id}: ${error instanceof Error ? error.message : String(error)}`,
      );
      return ResponseWrapper.error<EquipmentWithRelationsItemResponse>(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'EQUIPMENT RETRIEVE FAILED',
        null,
      );
    }
  }

  public async update(
    id: number,
    payload: UpdateEquipmentDto,
  ): Promise<WrappedResponse<EquipmentWithRelationsItemResponse>> {
    try {
      const equipment = await this.equipmentRepository.findOne({
        where: { id },
      });

      if (!equipment) {
        return ResponseWrapper.error<EquipmentWithRelationsItemResponse>(
          STATUS_CODE.NOT_FOUND,
          `Equipment with id ${id} not found`,
          { id },
        );
      }

      if (payload.plant !== undefined) {
        equipment.plant = payload.plant;
      }

      if (payload.code !== undefined) {
        equipment.code = payload.code;
      }

      if (payload.description !== undefined) {
        await this.upsertDefaultDescription(
          equipment.id,
          payload.plant ?? equipment.plant,
          payload.description,
        );
      }

      if (payload.sapObjId !== undefined) {
        equipment.sapObjId = payload.sapObjId;
      }

      if (payload.equipmentLevelId !== undefined) {
        equipment.equipmentLevelId = payload.equipmentLevelId;
      }

      if (payload.parentEquipmentId !== undefined) {
        equipment.parentEquipmentId = payload.parentEquipmentId;
      }

      if (payload.erpSource !== undefined) {
        equipment.erpSource = payload.erpSource;
      }

      await this.equipmentRepository.save(equipment);
      return await this.findOneWithRelations(id);
    } catch (error) {
      this.logger.error(
        `Failed to update equipment with id ${id}: ${error instanceof Error ? error.message : String(error)}`,
      );
      return ResponseWrapper.error<EquipmentWithRelationsItemResponse>(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'EQUIPMENT UPDATE FAILED',
        null,
      );
    }
  }

  public async saveEquipmentDetails(
    id: number,
    payload: SaveEquipmentDetailsDto,
  ): Promise<WrappedResponse<EquipmentWithRelationsItemResponse>> {
    try {
      const {
        classIds,
        classProperties,
        properties,
        propertiesEquipmentClassId,
        ...equipmentData
      } = payload;

      const saveDetailsResult =
        await this.equipmentRepository.manager.transaction(
          async (
            manager,
          ): Promise<
            WrappedResponse<EquipmentWithRelationsItemResponse> | undefined
          > => {
            const equipmentRepository = manager.getRepository(Equipment);
            const equipmentDescriptionRepository = manager.getRepository(
              EquipmentDescriptionByLanguage,
            );
            const equipmentPropertyRepository =
              manager.getRepository(EquipmentProperty);
            const equipmentEquipmentClassRepository = manager.getRepository(
              EquipmentEquipmentClass,
            );

            const equipment = await equipmentRepository.findOne({
              where: { id },
            });
            if (!equipment) {
              return ResponseWrapper.error(
                STATUS_CODE.NOT_FOUND,
                'Equipment not found',
              );
            }

            if (equipmentData.plant !== undefined) {
              equipment.plant = equipmentData.plant;
            }

            if (equipmentData.code !== undefined) {
              equipment.code = equipmentData.code;
            }

            if (equipmentData.sapObjId !== undefined) {
              equipment.sapObjId = equipmentData.sapObjId;
            }

            if (equipmentData.equipmentLevelId !== undefined) {
              equipment.equipmentLevelId = equipmentData.equipmentLevelId;
            }

            if (equipmentData.parentEquipmentId !== undefined) {
              equipment.parentEquipmentId = equipmentData.parentEquipmentId;
            }

            if (equipmentData.erpSource !== undefined) {
              equipment.erpSource = equipmentData.erpSource;
            }

            await equipmentRepository.save(equipment);

            if (equipmentData.description !== undefined) {
              await this.upsertDefaultDescription(
                equipment.id,
                equipment.plant,
                equipmentData.description,
                equipmentDescriptionRepository,
              );
            }

            const classIdsFromProperties = (classProperties ?? []).map(
              (entry) => entry.equipmentClassId,
            );
            const targetClassIds =
              classIds !== undefined || classIdsFromProperties.length > 0
                ? [...new Set([...(classIds ?? []), ...classIdsFromProperties])]
                : undefined;

            if (targetClassIds !== undefined) {
              await syncEquipmentClasses(
                equipment,
                targetClassIds,
                equipmentEquipmentClassRepository,
              );
            }

            if (properties !== undefined) {
              const propertyId = await resolveOrCreateEquipmentPropertyId(
                equipment,
                this.logger,
                equipmentPropertyRepository,
                equipmentEquipmentClassRepository,
                propertiesEquipmentClassId,
              );

              if (propertyId === undefined) {
                return ResponseWrapper.error(
                  STATUS_CODE.BAD_REQUEST,
                  `Cannot resolve equipment property row for equipment ${equipment.id}`,
                  null,
                );
              }

              const mergeError = await mergeJsonPropertiesByPropertyId(
                propertyId,
                properties,
                equipmentPropertyRepository,
              );

              if (mergeError) {
                return ResponseWrapper.error<EquipmentCreateWithDetailsResponse>(
                  STATUS_CODE.BAD_REQUEST,
                  'Invalid equipment property key',
                );
              }
            }

            if (classProperties !== undefined && classProperties.length > 0) {
              const applyError = await applyClassProperties(
                equipment,
                classProperties,
                this.logger,
                equipmentPropertyRepository,
                equipmentEquipmentClassRepository,
              );

              if (applyError) {
                return ResponseWrapper.error(
                  STATUS_CODE.BAD_REQUEST,
                  'Invalid equipment property key',
                );
              }
            }

            return undefined;
          },
        );

      if (saveDetailsResult) {
        return saveDetailsResult;
      }

      return await this.findOneWithRelations(id);
    } catch (error) {
      this.logger.error(
        `Failed to save equipment details for id ${id}: ${error instanceof Error ? error.message : String(error)}`,
      );
      return ResponseWrapper.error(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'EQUIPMENT UPDATE FAILED',
        null,
      );
    }
  }

  public async createWithDetails(
    payload: CreateEquipmentWithDetailsDto,
  ): Promise<WrappedResponse<EquipmentCreateWithDetailsResponse>> {
    try {
      const validationError =
        await this.validateCreateWithDetailsPayload(payload);
      if (validationError) {
        return validationError;
      }

      const {
        classIds,
        classProperties,
        properties,
        propertiesEquipmentClassId,
        isPrivilegedRole: privilegedRole,
        ...basePayload
      } = payload;

      const resolvedEquipmentLevel =
        await this.equipmentLevelRepository.findOne({
          where: { id: basePayload.equipmentLevelId },
        });

      if (
        resolvedEquipmentLevel?.code.trim().toLowerCase() ===
        EquipmentCrudService.siteEquipmentLevelCode
      ) {
        basePayload.plant = Number(basePayload.code.trim());
      }

      let createdEquipmentId: number | undefined;

      const createDetailsResult =
        await this.equipmentRepository.manager.transaction(
          async (
            manager,
          ): Promise<
            WrappedResponse<EquipmentCreateWithDetailsResponse> | undefined
          > => {
            const equipmentRepository = manager.getRepository(Equipment);
            const equipmentDescriptionRepository = manager.getRepository(
              EquipmentDescriptionByLanguage,
            );
            const equipmentPropertyRepository =
              manager.getRepository(EquipmentProperty);
            const equipmentEquipmentClassRepository = manager.getRepository(
              EquipmentEquipmentClass,
            );

            const duplicate = await equipmentRepository.findOne({
              where: {
                plant: basePayload.plant,
                code: basePayload.code,
                equipmentLevelId: basePayload.equipmentLevelId,
              },
            });

            if (duplicate) {
              createdEquipmentId = undefined;
              return undefined;
            }

            const {
              description,
              ...equipmentPayload
            }: CreateEquipmentWithDetailsDto = basePayload;
            const equipment = equipmentRepository.create(equipmentPayload);
            const savedEquipment = await equipmentRepository.save(equipment);
            createdEquipmentId = savedEquipment.id;

            await this.upsertDefaultDescription(
              savedEquipment.id,
              savedEquipment.plant,
              description,
              equipmentDescriptionRepository,
            );

            const classIdsFromProperties = (classProperties ?? []).map(
              (entry) => entry.equipmentClassId,
            );
            const targetClassIds = [
              ...new Set([...(classIds ?? []), ...classIdsFromProperties]),
            ];

            if (targetClassIds.length > 0) {
              await syncEquipmentClasses(
                savedEquipment,
                targetClassIds,
                equipmentEquipmentClassRepository,
              );
            }

            if (properties !== undefined) {
              const propertyId = await resolveOrCreateEquipmentPropertyId(
                savedEquipment,
                this.logger,
                equipmentPropertyRepository,
                equipmentEquipmentClassRepository,
                propertiesEquipmentClassId,
              );

              if (propertyId !== undefined) {
                const mergeError = await mergeJsonPropertiesByPropertyId(
                  propertyId,
                  properties,
                  equipmentPropertyRepository,
                );

                if (mergeError) {
                  return ResponseWrapper.error<EquipmentCreateWithDetailsResponse>(
                    STATUS_CODE.BAD_REQUEST,
                    'Invalid equipment property key',
                  );
                }
              }
            }

            if (classProperties !== undefined && classProperties.length > 0) {
              const applyError = await applyClassProperties(
                savedEquipment,
                classProperties,
                this.logger,
                equipmentPropertyRepository,
                equipmentEquipmentClassRepository,
              );

              if (applyError) {
                return ResponseWrapper.error<EquipmentCreateWithDetailsResponse>(
                  STATUS_CODE.BAD_REQUEST,
                  'Invalid equipment property key',
                );
              }
            }

            return undefined;
          },
        );

      if (createDetailsResult) {
        return createDetailsResult;
      }

      if (!createdEquipmentId) {
        return ResponseWrapper.error<EquipmentCreateWithDetailsResponse>(
          STATUS_CODE.CONFLICT,
          'Equipment already exists',
        );
      }

      const createdWithDetailsResponse =
        await this.findOneWithRelations(createdEquipmentId);
      if (
        !createdWithDetailsResponse.success ||
        !createdWithDetailsResponse.data ||
        !('code' in createdWithDetailsResponse.data)
      ) {
        return ResponseWrapper.error<EquipmentCreateWithDetailsResponse>(
          STATUS_CODE.INTERNAL_SERVER_ERROR,
          'EQUIPMENT RETRIEVE FAILED',
        );
      }

      return ResponseWrapper.success<EquipmentCreateWithDetailsResponse>(
        STATUS_CODE.OK,
        'Equipment with relations retrieved successfully',
        createdWithDetailsResponse.data,
      );
    } catch (error) {
      if (isUniqueConstraintViolation(error)) {
        return ResponseWrapper.error<EquipmentCreateWithDetailsResponse>(
          STATUS_CODE.CONFLICT,
          'Equipment already exists',
        );
      }
      if (error instanceof ConflictException) {
        return ResponseWrapper.error<EquipmentCreateWithDetailsResponse>(
          STATUS_CODE.CONFLICT,
          error.message,
        );
      }
      this.logger.error(
        `Failed to create equipment with details: ${error instanceof Error ? error.message : String(error)}`,
      );
      return ResponseWrapper.error<EquipmentCreateWithDetailsResponse>(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'EQUIPMENT CREATE FAILED',
      );
    }
  }

  public async remove(
    id: number,
  ): Promise<WrappedResponse<null | EquipmentIdentityPayload | undefined>> {
    try {
      const equipment = await this.equipmentRepository.findOne({
        where: { id },
      });
      if (!equipment) {
        return ResponseWrapper.error<null | EquipmentIdentityPayload>(
          STATUS_CODE.NOT_FOUND,
          `Equipment with id ${id} not found`,
          { id },
        );
      }

      await this.equipmentRepository.manager.transaction(async (manager) => {
        const equipmentRepository = manager.getRepository(Equipment);
        const descriptionRepository = manager.getRepository(
          EquipmentDescriptionByLanguage,
        );
        const equipmentClassLinkRepository = manager.getRepository(
          EquipmentEquipmentClass,
        );
        const equipmentPropertyRepository =
          manager.getRepository(EquipmentProperty);

        const deleteOrder = await collectCascadeDeleteOrder(
          equipmentRepository,
          id,
        );

        if (deleteOrder.length === 0) {
          return;
        }

        await equipmentPropertyRepository.delete({
          equipmentId: In(deleteOrder),
        });
        await equipmentClassLinkRepository.delete({
          equipmentId: In(deleteOrder),
        });
        await descriptionRepository.delete({ equipmentId: In(deleteOrder) });

        await equipmentRepository.delete({ id: In(deleteOrder) });
      });

      return ResponseWrapper.success<null | EquipmentIdentityPayload>(
        STATUS_CODE.OK,
        'Equipment deleted successfully',
        null,
      );
    } catch (error) {
      this.logger.error(
        `Failed to cascade delete equipment ${id}: ${error instanceof Error ? error.message : String(error)}`,
      );
      return ResponseWrapper.error<null | EquipmentIdentityPayload>(
        STATUS_CODE.INTERNAL_SERVER_ERROR,
        'EQUIPMENT DELETE FAILED',
        null,
      );
    }
  }
}

import { Equipment } from '@/modules/isa95-equipment-model/equipment/equipment.entity';

export interface EquipmentIdentityPayload {
  id: number;
}

export interface EquipmentDuplicatePayload {
  plant: number;
  code: string;
  equipmentLevelId: number;
}

export type EquipmentCreateResponse =
  | Equipment
  | EquipmentDuplicatePayload
  | null
  | undefined;

export type EquipmentListResponse = Array<Equipment> | undefined;

export type EquipmentWithRelationsListResponse = Array<Equipment> | undefined;

export type EquipmentItemResponse =
  | Equipment
  | EquipmentIdentityPayload
  | null
  | undefined;

export type EquipmentWithRelationsItemResponse =
  | Equipment
  | EquipmentIdentityPayload
  | null
  | undefined;

export type EquipmentCreateWithDetailsResponse = Equipment | undefined;

import {
  ResponseWrapper,
  STATUS_CODE,
  WrappedResponse,
} from '@mesx/common-lib';
import { In, Repository } from 'typeorm';
import { throwWrappedInternalError } from '@/modules/isa95-equipment-model/common/internal-error.util';
import { EquipmentClassPropertiesInputDto } from '@/modules/isa95-equipment-model/dtos/equipment-class-properties-input.dto';
import { Equipment } from '@/modules/isa95-equipment-model/equipment/equipment.entity';
import { EquipmentEquipmentClass } from '@/modules/isa95-equipment-model/shared/equipment-equipment-class/equipment-equipment-class.entity';
import { EquipmentProperty } from '@/modules/isa95-equipment-model/shared/equipment-property/equipment-property.entity';

interface EquipmentCrudLogger {
  error(message: string, stack?: string): void;
  warn(message: string): void;
}

/**
 * Returns descendant-first order for cascading equipment deletes.
 * @param equipmentRepository Equipment repository used to query the hierarchy.
 * @param rootId Root equipment identifier to start traversal from.
 * @returns Equipment ids ordered from deepest descendants to root.
 */
export async function collectCascadeDeleteOrder(
  equipmentRepository: Repository<Equipment>,
  rootId: number,
): Promise<Array<number>> {
  const rows = await equipmentRepository.query(
    `WITH equipment_tree AS (
      SELECT
        equipment.id,
        equipment.parent_equipment_id,
        0 AS depth
      FROM isa95.equipment AS equipment
      WHERE equipment.id = @0

      UNION ALL

      SELECT
        child.id,
        child.parent_equipment_id,
        tree.depth + 1 AS depth
      FROM isa95.equipment AS child
      INNER JOIN equipment_tree AS tree
        ON child.parent_equipment_id = tree.id
    )
    SELECT id
    FROM equipment_tree
    ORDER BY depth DESC, id DESC
    OPTION (MAXRECURSION 0)`,
    [rootId],
  );

  return rows.map(({ id }: { id: number | string }) => Number(id));
}

/**
 * Ensures JSON property keys are valid SQL JSON path tokens.
 * @param key JSON key to validate.
 * @returns Wrapped bad-request response when key is invalid; otherwise undefined.
 */
export function validateJsonKey(
  key: string,
): WrappedResponse<undefined> | undefined {
  if (!/^[A-Z_a-z]\w*$/.test(key)) {
    return ResponseWrapper.error<undefined>(
      STATUS_CODE.BAD_REQUEST,
      `${key} must be a valid column name: start with a letter or underscore and use only letters, numbers, and underscores`,
    );
  }

  return undefined;
}

/**
 * Detects SQL Server duplicate-key violations from driver errors.
 * @param error Unknown error value from repository operations.
 * @returns True when the error represents SQL Server duplicate-key violations.
 */
export function isUniqueConstraintViolation(error: unknown): boolean {
  const message = error instanceof Error ? error.message : String(error);
  return /\b(2601|2627)\b/.test(message);
}

/**
 * Gets or creates the equipment_property row for an equipment/class pair.
 * @param equipment Equipment entity owning the property row.
 * @param logger Logger used for warnings and wrapped internal errors.
 * @param equipmentPropertyRepository Repository for equipment property rows.
 * @param equipmentEquipmentClassRepository Repository for equipment-class links.
 * @param equipmentClassId Optional class id to scope property resolution.
 * @returns Resolved or newly created equipment_property id, or undefined when no class link exists.
 */
export async function resolveOrCreateEquipmentPropertyId(
  equipment: Equipment,
  logger: EquipmentCrudLogger,
  equipmentPropertyRepository: Repository<EquipmentProperty>,
  equipmentEquipmentClassRepository: Repository<EquipmentEquipmentClass>,
  equipmentClassId?: number,
): Promise<number | undefined> {
  if (equipmentClassId !== undefined) {
    const existingForClass = await equipmentPropertyRepository.findOne({
      where: { equipmentId: equipment.id, equipmentClassId },
      order: { id: 'ASC' },
    });

    if (existingForClass) {
      return existingForClass.id;
    }

    const createdForClass = equipmentPropertyRepository.create({
      plant: equipment.plant,
      equipmentId: equipment.id,
      equipmentClassId,
      propertiesJson: {},
    });

    try {
      const savedForClass =
        await equipmentPropertyRepository.save(createdForClass);
      return savedForClass.id;
    } catch (error) {
      // Under concurrent writes another request may create the same row first.
      if (!isUniqueConstraintViolation(error)) {
        throwWrappedInternalError(
          logger,
          'Failed to resolve or create equipment property row',
          error,
        );
      }

      const existingAfterConflict = await equipmentPropertyRepository.findOne({
        where: { equipmentId: equipment.id, equipmentClassId },
        order: { id: 'ASC' },
      });
      return existingAfterConflict?.id;
    }
  }

  const existingProperty = await equipmentPropertyRepository.findOne({
    select: { id: true },
    where: { equipmentId: equipment.id },
    order: { id: 'ASC' },
  });

  if (existingProperty) {
    return existingProperty.id;
  }

  const firstLink = await equipmentEquipmentClassRepository.findOne({
    select: { equipmentClassId: true },
    where: { equipmentId: equipment.id },
    order: { equipmentClassId: 'ASC' },
  });

  if (!firstLink) {
    logger.warn(
      `Cannot create equipment property for equipment ${equipment.id} because no equipment class link exists`,
    );
    return undefined;
  }

  const created = equipmentPropertyRepository.create({
    plant: equipment.plant,
    equipmentId: equipment.id,
    equipmentClassId: firstLink.equipmentClassId,
    propertiesJson: {},
  });

  try {
    const saved = await equipmentPropertyRepository.save(created);
    return saved.id;
  } catch (error) {
    if (!isUniqueConstraintViolation(error)) {
      throwWrappedInternalError(
        logger,
        'Failed to resolve or create equipment property row',
        error,
      );
    }

    const existingAfterConflict = await equipmentPropertyRepository.findOne({
      where: {
        equipmentId: equipment.id,
        equipmentClassId: firstLink.equipmentClassId,
      },
      order: { id: 'ASC' },
    });
    return existingAfterConflict?.id;
  }
}

/**
 * Reconciles equipment-class links to exactly match the target class list.
 * @param equipment Equipment entity to reconcile links for.
 * @param targetClassIds Desired equipment class ids after synchronization.
 * @param equipmentEquipmentClassRepository Repository for equipment-class links.
 * @returns Promise that resolves when link reconciliation is complete.
 */
export async function syncEquipmentClasses(
  equipment: Equipment,
  targetClassIds: Array<number>,
  equipmentEquipmentClassRepository: Repository<EquipmentEquipmentClass>,
): Promise<void> {
  const uniqueTargetClassIds = [...new Set(targetClassIds)];
  const existingLinks = await equipmentEquipmentClassRepository.find({
    where: { equipmentId: equipment.id },
    order: { id: 'ASC' },
  });

  const existingClassIds = new Set(
    existingLinks.map((link) => link.equipmentClassId),
  );
  const targetClassIdSet = new Set(uniqueTargetClassIds);

  const toAdd = uniqueTargetClassIds.filter(
    (classId) => !existingClassIds.has(classId),
  );
  const toRemove = existingLinks
    .map((link) => link.equipmentClassId)
    .filter((classId) => !targetClassIdSet.has(classId));

  if (toAdd.length > 0) {
    const linksToCreate = toAdd.map((equipmentClassId) =>
      equipmentEquipmentClassRepository.create({
        plant: equipment.plant,
        equipmentId: equipment.id,
        equipmentClassId,
      }),
    );
    await equipmentEquipmentClassRepository.save(linksToCreate);
  }

  if (toRemove.length > 0) {
    await equipmentEquipmentClassRepository.delete({
      equipmentId: equipment.id,
      equipmentClassId: In(toRemove),
    });
  }
}

/**
 * Merges key/value pairs into properties_json using SQL JSON_MODIFY updates.
 * @param propertyId equipment_property row id to update.
 * @param properties Partial property map to merge into JSON payload.
 * @param equipmentPropertyRepository Repository used for SQL update execution.
 * @returns Promise that resolves when JSON merge is persisted.
 */
export async function mergeJsonPropertiesByPropertyId(
  propertyId: number,
  properties: Record<string, unknown>,
  equipmentPropertyRepository: Repository<EquipmentProperty>,
): Promise<WrappedResponse<null | undefined> | undefined> {
  const entries = Object.entries(properties);
  if (entries.length === 0) {
    return undefined;
  }

  for (const [key] of entries) {
    const validationError = validateJsonKey(key);
    if (validationError) {
      return validationError;
    }
  }

  const parameters: Array<unknown> = [];
  let expression = 'properties_json';

  for (const [key, value] of entries) {
    const index = parameters.length;
    if (value !== null && typeof value === 'object') {
      parameters.push(JSON.stringify(value));
      expression = `JSON_MODIFY(${expression}, '$.${key}', JSON_QUERY(@${index}))`;
    } else {
      parameters.push(value);
      expression = `JSON_MODIFY(${expression}, '$.${key}', @${index})`;
    }
  }

  const idIndex = parameters.length;
  parameters.push(propertyId);

  await equipmentPropertyRepository.manager.query(
    `UPDATE [isa95].[equipment_property] SET properties_json = ${expression} WHERE id = @${idIndex}`,
    parameters,
  );

  return undefined;
}

/**
 * Applies class-scoped property payloads in a deterministic write order.
 * @param equipment Equipment entity receiving class property values.
 * @param classProperties Input values grouped by equipment class.
 * @param logger Logger used for conflict and warning paths.
 * @param equipmentPropertyRepository Repository for equipment property rows.
 * @param equipmentEquipmentClassRepository Repository for equipment-class links.
 * @returns Promise that resolves when all class property writes complete.
 */
export async function applyClassProperties(
  equipment: Equipment,
  classProperties: Array<EquipmentClassPropertiesInputDto>,
  logger: EquipmentCrudLogger,
  equipmentPropertyRepository: Repository<EquipmentProperty>,
  equipmentEquipmentClassRepository: Repository<EquipmentEquipmentClass>,
): Promise<WrappedResponse<null | undefined> | undefined> {
  // Keep writes ordered to reduce lock contention and duplicate-create races.
  const applyAtIndex = async (
    index: number,
  ): Promise<WrappedResponse<null | undefined> | undefined> => {
    if (index >= classProperties.length) {
      return undefined;
    }

    const entry = classProperties[index];
    const propertyId = await resolveOrCreateEquipmentPropertyId(
      equipment,
      logger,
      equipmentPropertyRepository,
      equipmentEquipmentClassRepository,
      entry.equipmentClassId,
    );

    if (propertyId !== undefined) {
      const mergeError = await mergeJsonPropertiesByPropertyId(
        propertyId,
        entry.properties,
        equipmentPropertyRepository,
      );

      if (mergeError) {
        return mergeError;
      }
    }

    return applyAtIndex(index + 1);
  };

  return applyAtIndex(0);
}

