import {
  ResponseWrapper,
  STATUS_CODE,
  WrappedResponse,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AppLogger } from '@/common/logger/app-logger';
import { throwWrappedInternalError } from '@/modules/isa95-equipment-model/common/internal-error.util';
import { CreateEquipmentLevelDto } from '@/modules/isa95-equipment-model/dtos/create-equipment-level.dto';
import { UpdateEquipmentLevelDto } from '@/modules/isa95-equipment-model/dtos/update-equipment-level.dto';
import { EquipmentLevel } from '@/modules/isa95-equipment-model/equipment/equipment-level/equipment-level.entity';

@Injectable()
export class EquipmentLevelCrudService {
  private static isUniqueConstraintViolation(error: unknown): boolean {
    const message = error instanceof Error ? error.message : String(error);
    return /\b(2601|2627)\b/.test(message);
  }

  private readonly logger = new AppLogger(EquipmentLevelCrudService.name);

  public constructor(
    @InjectRepository(EquipmentLevel)
    private readonly equipmentLevelRepository: Repository<EquipmentLevel>,
  ) {}

  public async create(
    payload: CreateEquipmentLevelDto,
  ): Promise<WrappedResponse<EquipmentLevel | undefined>> {
    try {
      const existingLevel = await this.equipmentLevelRepository.findOne({
        where: { code: payload.code },
      });

      if (existingLevel) {
        this.logger.warn(
          `Equipment level with code ${payload.code} already exists`,
        );
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          'Equipment level already exists',
        );
      }

      const equipmentLevel = this.equipmentLevelRepository.create(payload);
      try {
        const created =
          await this.equipmentLevelRepository.save(equipmentLevel);
        return ResponseWrapper.success(
          STATUS_CODE.CREATED,
          'Equipment level created successfully',
          created,
        );
      } catch (error) {
        if (!EquipmentLevelCrudService.isUniqueConstraintViolation(error)) {
          return throwWrappedInternalError(
            this.logger,
            'Failed to create equipment level',
            error,
          );
        }

        this.logger.warn(
          `Equipment level with code ${payload.code} already exists`,
        );
        const existingAfterConflict =
          await this.equipmentLevelRepository.findOne({
            where: { code: payload.code },
          });
        if (existingAfterConflict) {
          return ResponseWrapper.error(
            STATUS_CODE.CONFLICT,
            'Equipment level already exists',
          );
        }

        return ResponseWrapper.error(
          STATUS_CODE.INTERNAL_SERVER_ERROR,
          'Internal server error',
        );
      }
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        'Failed to create equipment level',
        error,
      );
    }
  }

  public async findAll(): Promise<
    WrappedResponse<Array<EquipmentLevel> | undefined>
  > {
    try {
      const levels = await this.equipmentLevelRepository.find({
        order: { id: 'ASC' },
      });
      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Equipment levels retrieved successfully',
        levels,
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        'Failed to retrieve equipment levels',
        error,
      );
    }
  }

  public async findOne(
    id: number,
  ): Promise<WrappedResponse<EquipmentLevel | undefined>> {
    try {
      const equipmentLevel = await this.equipmentLevelRepository.findOne({
        where: { id },
      });

      if (!equipmentLevel) {
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          `Equipment level with id ${id} not found`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Equipment level retrieved successfully',
        equipmentLevel,
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to retrieve equipment level with id ${id}`,
        error,
      );
    }
  }

  public async update(
    id: number,
    payload: UpdateEquipmentLevelDto,
  ): Promise<WrappedResponse<EquipmentLevel | undefined>> {
    try {
      const equipmentLevel = await this.equipmentLevelRepository.findOne({
        where: { id },
      });
      if (!equipmentLevel) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Equipment level with id ${id} not found`,
        );
      }

      if (payload.code !== undefined) {
        equipmentLevel.code = payload.code;
      }

      const updated = await this.equipmentLevelRepository.save(equipmentLevel);
      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Equipment level updated successfully',
        updated,
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to update equipment level with id ${id}`,
        error,
      );
    }
  }

  public async remove(id: number): Promise<WrappedResponse<undefined>> {
    try {
      const childLevelsCount = await this.equipmentLevelRepository.count({
        where: { parentEquipmentLevelId: id },
      });

      if (childLevelsCount > 0) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Equipment level with id ${id} cannot be deleted because it has child levels`,
        );
      }

      const linkedEquipmentRows: Array<{ exists: number }> =
        await this.equipmentLevelRepository.manager.query(
          'SELECT TOP (1) 1 AS exists FROM [isa95].[equipment] WHERE equipment_level_id = @0',
          [id],
        );

      if (linkedEquipmentRows.length > 0) {
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          `Equipment level with id ${id} cannot be deleted because equipment rows reference it`,
        );
      }

      const response = await this.equipmentLevelRepository.delete({ id });

      if (!response.affected) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Equipment level with id ${id} not found`,
        );
      }
      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Equipment level deleted successfully',
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to delete equipment level with id ${id}`,
        error,
      );
    }
  }
}

