import {
  ResponseWrapper,
  STATUS_CODE,
  WrappedResponse,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { EquipmentPropertyDescription } from './equipment-property-description.entity';
import { AppLogger } from '@/common/logger/app-logger';
import { throwWrappedInternalError } from '@/modules/isa95-equipment-model/common/internal-error.util';
import { CreateEquipmentPropertyDescriptionDto } from '@/modules/isa95-equipment-model/dtos/create-equipment-property-description.dto';
import { UpdateEquipmentPropertyDescriptionDto } from '@/modules/isa95-equipment-model/dtos/update-equipment-property-description.dto';

@Injectable()
export class EquipmentPropertyDescriptionCrudService {
  private readonly logger = new AppLogger(
    EquipmentPropertyDescriptionCrudService.name,
  );

  public constructor(
    @InjectRepository(EquipmentPropertyDescription)
    private readonly equipmentPropertyDescriptionRepository: Repository<EquipmentPropertyDescription>,
  ) {}

  public async create(
    payload: CreateEquipmentPropertyDescriptionDto,
  ): Promise<WrappedResponse<EquipmentPropertyDescription | undefined>> {
    try {
      const existing =
        await this.equipmentPropertyDescriptionRepository.findOne({
          where: {
            equipmentClassPropertyId: payload.equipmentClassPropertyId,
            code: payload.code,
          },
        });

      if (existing) {
        this.logger.warn(
          `Equipment property description already exists for property ${payload.equipmentClassPropertyId} and language ${payload.code}`,
        );
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          'Equipment property description already exists',
        );
      }

      const description =
        this.equipmentPropertyDescriptionRepository.create(payload);
      const created =
        await this.equipmentPropertyDescriptionRepository.save(description);
      return ResponseWrapper.success(
        STATUS_CODE.CREATED,
        'Equipment property description created successfully',
        created,
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        'Failed to create equipment property description',
        error,
      );
    }
  }

  public async findAll(): Promise<
    WrappedResponse<Array<EquipmentPropertyDescription> | undefined>
  > {
    try {
      const descriptions =
        await this.equipmentPropertyDescriptionRepository.find({
          order: { id: 'ASC' },
        });
      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Equipment property descriptions retrieved successfully',
        descriptions,
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        'Failed to retrieve equipment property descriptions',
        error,
      );
    }
  }

  public async findOne(
    id: number,
  ): Promise<WrappedResponse<EquipmentPropertyDescription | undefined>> {
    try {
      const description =
        await this.equipmentPropertyDescriptionRepository.findOne({
          where: { id },
        });

      if (!description) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Equipment property description with id ${id} not found`,
        );
      }

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Equipment property description retrieved successfully',
        description,
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to retrieve equipment property description with id ${id}`,
        error,
      );
    }
  }

  public async update(
    id: number,
    payload: UpdateEquipmentPropertyDescriptionDto,
  ): Promise<WrappedResponse<EquipmentPropertyDescription | undefined>> {
    try {
      const findOneResponse = await this.findOne(id);

      if (!findOneResponse.success || !findOneResponse.data) {
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Equipment property description with id ${id} not found`,
        );
      }

      const description = findOneResponse.data;

      if (payload.code !== undefined) {
        description.code = payload.code;
      }

      if (payload.description !== undefined) {
        description.description = payload.description;
      }

      if (payload.equipmentClassPropertyId !== undefined) {
        description.equipmentClassPropertyId = payload.equipmentClassPropertyId;
      }

      const saved =
        await this.equipmentPropertyDescriptionRepository.save(description);

      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Equipment property description updated successfully',
        saved,
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to update equipment property description with id ${id}`,
        error,
      );
    }
  }

  public async remove(id: number): Promise<void> {
    try {
      const response = await this.equipmentPropertyDescriptionRepository.delete(
        {
          id,
        },
      );

      if (!response.affected) {
        ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          `Equipment property description with id ${id} not found`,
        );
      }
    } catch (error) {
      throwWrappedInternalError(
        this.logger,
        `Failed to delete equipment property description with id ${id}`,
        error,
      );
    }
  }
}

