import {
  Column,
  Entity,
  JoinColumn,
  ManyToOne,
  OneToMany,
  PrimaryGeneratedColumn,
  Unique,
} from 'typeorm';
import { TimeStamp } from '@/modules/generics/timestamp';
import { EquipmentDescriptionByLanguage } from '@/modules/isa95-equipment-model/equipment/equipment-description-by-language/equipment-description-by-language.entity';
import { EquipmentLevel } from '@/modules/isa95-equipment-model/equipment/equipment-level/equipment-level.entity';
import { EquipmentEquipmentClass } from '@/modules/isa95-equipment-model/shared/equipment-equipment-class/equipment-equipment-class.entity';
import { EquipmentProperty } from '@/modules/isa95-equipment-model/shared/equipment-property/equipment-property.entity';

@Entity({ name: 'equipment', schema: 'isa95' })
@Unique('uq_equipment_plant_code_equipment_level_id', [
  'plant',
  'code',
  'equipmentLevelId',
])
export class Equipment extends TimeStamp {
  @PrimaryGeneratedColumn({ name: 'id' })
  public id: number;

  @Column({
    name: 'plant',
    type: 'smallint',
  })
  public plant: number;

  @Column({
    length: 20,
    name: 'code',
    nullable: false,
    type: 'nvarchar',
  })
  public code: string;

  @Column({
    name: 'sap_obj_id',
    nullable: false,
    precision: 8,
    scale: 0,
    type: 'numeric',
  })
  public sapObjId: number;

  @Column({ name: 'equipment_level_id', nullable: false })
  public equipmentLevelId: number;

  @Column({ name: 'parent_equipment_id', nullable: true })
  public parentEquipmentId: number;

  @Column({
    length: 3,
    name: 'erp_source',
    nullable: true,
    type: 'char',
  })
  public erpSource: string;

  @ManyToOne(() => EquipmentLevel, (equipmentLevel) => equipmentLevel.equipment)
  @JoinColumn({
    name: 'equipment_level_id',
    foreignKeyConstraintName: 'fk_equipment_equipment_level',
  })
  public equipmentLevel: EquipmentLevel;

  @ManyToOne(() => Equipment, (equipment) => equipment.children)
  @JoinColumn({
    name: 'parent_equipment_id',
    referencedColumnName: 'id',
    foreignKeyConstraintName: 'fk_equipment_equipment',
  })
  public parentEquipment: Equipment;

  @OneToMany(() => Equipment, (equipment) => equipment.parentEquipment)
  public children: Array<Equipment>;

  @OneToMany(
    () => EquipmentDescriptionByLanguage,
    (equipmentDescription) => equipmentDescription.equipment,
  )
  public descriptions: Array<EquipmentDescriptionByLanguage>;

  @OneToMany(
    () => EquipmentEquipmentClass,
    (equipmentEquipmentClass) => equipmentEquipmentClass.equipment,
  )
  public equipmentEquipmentClasses: Array<EquipmentEquipmentClass>;

  @OneToMany(
    () => EquipmentProperty,
    (equipmentProperty) => equipmentProperty.equipment,
  )
  public equipmentProperties: Array<EquipmentProperty>;
}

