  WrappedResponse,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AppLogger } from '@/common/logger/app-logger';
import { throwWrappedInternalError } from '@/modules/isa95-equipment-model/common/internal-error.util';
import { CreateEquipmentEquipmentClassDto } from '@/modules/isa95-equipment-model/dtos/create-equipment-equipment-class.dto';
import { EquipmentEquipmentClass } from '@/modules/isa95-equipment-model/shared/equipment-equipment-class/equipment-equipment-class.entity';

@Injectable()
export class EquipmentEquipmentClassCrudService {
  private static isUniqueConstraintViolation(error: unknown): boolean {
    const message = error instanceof Error ? error.message : String(error);
    return /\b(2601|2627)\b/.test(message);
  }

  private readonly logger = new AppLogger(
    EquipmentEquipmentClassCrudService.name,
  );

  public constructor(
    @InjectRepository(EquipmentEquipmentClass)
    private readonly equipmentEquipmentClassRepository: Repository<EquipmentEquipmentClass>,
  ) {}

  public async create(
    payload: CreateEquipmentEquipmentClassDto,
  ): Promise<WrappedResponse<EquipmentEquipmentClass | undefined>> {
    try {
      const existing = await this.equipmentEquipmentClassRepository.findOne({
        where: {
          equipmentId: payload.equipmentId,
          equipmentClassId: payload.equipmentClassId,
        },
      });

      if (existing) {
        this.logger.warn(
          `Equipment ${payload.equipmentId} is already linked to class ${payload.equipmentClassId} on plant ${payload.plant}`,
        );
        return ResponseWrapper.error(
          STATUS_CODE.CONFLICT,
          'Equipment-to-class link already exists',
        );
      }

      const link = this.equipmentEquipmentClassRepository.create(payload);
      try {
        const created = await this.equipmentEquipmentClassRepository.save(link);
        return ResponseWrapper.success(
          STATUS_CODE.CREATED,
          'Equipment-to-class link created successfully',
          created,
        );
      } catch (error) {
        if (
          !EquipmentEquipmentClassCrudService.isUniqueConstraintViolation(error)
        ) {
          return throwWrappedInternalError(
            this.logger,
            'Failed to create equipment-to-class link',
            error,
          );
        }

        this.logger.warn(
          `Equipment ${payload.equipmentId} is already linked to class ${payload.equipmentClassId} on plant ${payload.plant}`,
        );
        const existingAfterConflict =
          await this.equipmentEquipmentClassRepository.findOne({
            where: {
              equipmentId: payload.equipmentId,
              equipmentClassId: payload.equipmentClassId,
            },
          });
        if (existingAfterConflict) {
          return ResponseWrapper.error(
            STATUS_CODE.CONFLICT,
            'Equipment-to-class link already exists',
          );
        }

        return ResponseWrapper.error(
          STATUS_CODE.INTERNAL_SERVER_ERROR,
          'Internal server error',
        );
      }
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        'Failed to create equipment-to-class link',
        error,
      );
    }
  }

  public async findAll(): Promise<
    WrappedResponse<Array<EquipmentEquipmentClass> | undefined>
  > {
    try {
      const links = await this.equipmentEquipmentClassRepository.find({
        order: { id: 'ASC' },
      });
      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Equipment-to-class links retrieved successfully',
        links,
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        'Failed to retrieve equipment-to-class links',
        error,
      );
    }
  }

  public async findByEquipmentId(
    equipmentId: number,
  ): Promise<Array<EquipmentEquipmentClass>> {
    try {
      return await this.equipmentEquipmentClassRepository.find({
        where: { equipmentId },
        order: { id: 'ASC' },
      });
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to retrieve equipment-to-class links for equipment ${equipmentId}`,
        error,
      );
    }
  }

  public async findByEquipmentClassId(
    equipmentClassId: number,
  ): Promise<Array<EquipmentEquipmentClass>> {
    try {
      return await this.equipmentEquipmentClassRepository.find({
        where: { equipmentClassId },
        order: { id: 'ASC' },
      });
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to retrieve equipment-to-class links for class ${equipmentClassId}`,
        error,
      );
    }
  }

  public async findOne(id: number): Promise<EquipmentEquipmentClass | null> {
    try {
      const link = await this.equipmentEquipmentClassRepository.findOne({
        where: { id },
      });
      return link ?? null;
    } catch (error) {
      throwWrappedInternalError(
        this.logger,
        `Failed to retrieve equipment-to-class link with id ${id}`,
        error,
      );
      return null;
    }
  }

  public async remove(id: number): Promise<boolean> {
    try {
      const response = await this.equipmentEquipmentClassRepository.delete({
        id,
      });
      return !!response.affected;
    } catch (error) {
      throwWrappedInternalError(
        this.logger,
        `Failed to delete equipment-to-class link with id ${id}`,
        error,
      );
      return false;
    }
  }

  public async removeByEquipmentAndClass(
    equipmentId: number,
    equipmentClassId: number,
  ): Promise<WrappedResponse<undefined>> {
    try {
      const response = await this.equipmentEquipmentClassRepository.delete({
        equipmentId,
        equipmentClassId,
      });

      if (!response.affected) {
        this.logger.warn(
          `No link found between equipment ${equipmentId} and class ${equipmentClassId}`,
        );
        return ResponseWrapper.error(
          STATUS_CODE.NOT_FOUND,
          'Equipment-to-class link not found',
        );
      }
      return ResponseWrapper.success(
        STATUS_CODE.OK,
        'Equipment-to-class link removed successfully',
      );
    } catch (error) {
      return throwWrappedInternalError(
        this.logger,
        `Failed to delete equipment-to-class link for equipment ${equipmentId} and class ${equipmentClassId}`,
        error,
      );
    }
  }
}

