import {
  Column,
  Entity,
  JoinColumn,
  ManyToOne,
  PrimaryGeneratedColumn,
  Unique,
} from 'typeorm';
import { TimeStamp } from '@/modules/generics/timestamp';
import { Equipment } from '@/modules/isa95-equipment-model/equipment/equipment.entity';
import { EquipmentClass } from '@/modules/isa95-equipment-model/equipment-class/equipment-class.entity';

@Entity({ name: 'equipment_property', schema: 'isa95', synchronize: false })
@Unique('uq_equipment_property_equipment_class_id_equipment_id', [
  'equipmentClassId',
  'equipmentId',
])
export class EquipmentProperty extends TimeStamp {
  @PrimaryGeneratedColumn({ name: 'id' })
  public id: number;

  @Column({
    name: 'plant',
    type: 'smallint',
  })
  public plant: number;

  @Column({
    length: 'MAX',
    name: 'properties_json',
    nullable: false,
    transformer: {
      to: (value: Record<string, unknown>) => {
        return JSON.stringify(value);
      },
      from: (value: string) => {
        return typeof value === 'string' ? JSON.parse(value) : value;
      },
    },
    type: 'nvarchar',
  })
  public propertiesJson: Record<string, unknown>;

  @Column({ name: 'equipment_id', nullable: false })
  public equipmentId: number;

  @Column({ name: 'equipment_class_id', nullable: false })
  public equipmentClassId: number;

  @ManyToOne(() => Equipment, (equipment) => equipment.equipmentProperties)
  @JoinColumn({
    name: 'equipment_id',
    referencedColumnName: 'id',
    foreignKeyConstraintName: 'fk_equipment_property_equipment',
  })
  public equipment: Equipment;

  @ManyToOne(
    () => EquipmentClass,
    (equipmentClass) => equipmentClass.equipmentProperties,
  )
  @JoinColumn({
    name: 'equipment_class_id',
    foreignKeyConstraintName: 'fk_equipment_property_equipment_class',
  })
  public equipmentClass: EquipmentClass;
}

